COMMENT ON TABLE partner_account IS '거래처 계좌 - 한 행=거래처 계좌 1건. 거래처 N:1 필수. 계좌번호 암호화. 사용 여부.';

COMMENT ON COLUMN partner_account.partner_account_id IS '거래처 계좌 ID - 대리키';

COMMENT ON COLUMN partner_account.partner_id IS '거래처';

COMMENT ON COLUMN partner_account.bank_name IS '은행 - (가정) 은행 코드 체계 미확인으로 명칭 텍스트';

COMMENT ON COLUMN partner_account.account_number_enc IS '계좌번호(암호화) - 암호화 저장. 평문 중복 저장 금지. 키는 DB와 분리';

COMMENT ON COLUMN partner_account.account_holder IS '예금주 - (가정) 필수';

COMMENT ON COLUMN partner_account.use_status IS '사용 여부 - (가정) 신규 등록 시 사용으로 시작. 미사용 계좌는 신규 업무에서 선택 불가';

COMMENT ON COLUMN partner_account.created_at IS '생성 일시';

COMMENT ON COLUMN partner_account.updated_at IS '수정 일시';

CREATE TABLE credit_card (
    credit_card_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    card_type VARCHAR(20) NOT NULL,
    card_number_enc VARCHAR(500) NOT NULL,
    card_number_last4 VARCHAR(4),
    card_name VARCHAR(100),
    issuer_name VARCHAR(100),
    expiry_date DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_credit_card PRIMARY KEY (credit_card_id),
    CONSTRAINT ck_credit_card_card_type CHECK (card_type IN ('법인', '개인', '사업용'))
);

COMMENT ON TABLE credit_card IS '신용카드 - 한 행=카드 1매. 카드유형(법인/개인/사업용), 카드번호 암호화.';

COMMENT ON COLUMN credit_card.credit_card_id IS '신용카드 ID - 대리키';

COMMENT ON COLUMN credit_card.card_type IS '카드 유형 - 카드 유형은 법인·개인·사업용 중 하나(원문). 카드 등록 시 필수 입력';

COMMENT ON COLUMN credit_card.card_number_enc IS '카드번호(암호화) - 카드번호는 암호화 저장하며 화면에는 일부만 표시. 평문은 저장하지 않음. 암호문 길이 500은 가정';

COMMENT ON COLUMN credit_card.card_number_last4 IS '카드번호 끝 4자리 - (가정) 화면 일부 표시용 마스킹 값. 암호문에서 산출 가능하면 생략 가능';

COMMENT ON COLUMN credit_card.card_name IS '카드명 - (가정) 카드 상세정보. 길이는 가정';

COMMENT ON COLUMN credit_card.issuer_name IS '카드사명 - (가정) 카드 상세정보. 길이는 가정';

COMMENT ON COLUMN credit_card.expiry_date IS '유효기간 만료일 - (가정) 카드 상세정보';

COMMENT ON COLUMN credit_card.created_at IS '생성 일시';

COMMENT ON COLUMN credit_card.updated_at IS '수정 일시';

CREATE TABLE approval_document (
    approval_document_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    document_no VARCHAR(50) NOT NULL,
    approval_form_id BIGINT NOT NULL,
    drafter_id BIGINT NOT NULL,
    title VARCHAR(500) NOT NULL,
    body TEXT,
    approval_status VARCHAR(10) NOT NULL,
    submitted_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_approval_document PRIMARY KEY (approval_document_id),
    CONSTRAINT uq_approval_document_document_no UNIQUE (document_no),
    CONSTRAINT ck_approval_document_approval_status CHECK (approval_status IN ('기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료')),
    CONSTRAINT ck_approval_document_submitted_at_req CHECK (approval_status NOT IN ('결재대기', '승인', '보류', '반려', '완료') OR submitted_at IS NOT NULL),
    CONSTRAINT ck_approval_document_completed_at_req CHECK (approval_status NOT IN ('완료') OR completed_at IS NOT NULL),
    CONSTRAINT ck_approval_document_completed_at_ge_submitted_at CHECK (completed_at >= submitted_at)
);

COMMENT ON TABLE approval_document IS '전자결재 문서 - 한 행=결재문서 1건. 문서번호 유일. 전자결재 처리 상태(기안/결재대기/승인/보류/반려/회수/재기안/완료).';

COMMENT ON COLUMN approval_document.approval_document_id IS '전자결재 문서 ID - 대리키';

COMMENT ON COLUMN approval_document.document_no IS '문서번호 - 문서번호 유일. 채번 방식·길이는 가정. 삽입 전 채번 공급(가정)';

COMMENT ON COLUMN approval_document.approval_form_id IS '결재양식';

COMMENT ON COLUMN approval_document.drafter_id IS '기안자 - 기안자(임직원 계정 FK)';

COMMENT ON COLUMN approval_document.title IS '문서 제목 - 길이는 가정';

COMMENT ON COLUMN approval_document.body IS '문서 본문 - HTML 본문. 기안 단계 저장 시 비어 있을 수 있음(가정)';

COMMENT ON COLUMN approval_document.approval_status IS '전자결재 처리 상태 - 공통 결정의 전자결재 처리 상태(근거: 가정). 초기값: 기안 작성 저장→기안. 상신 시 결재대기로 전환';

COMMENT ON COLUMN approval_document.submitted_at IS '상신 일시 - 상신 시 채워짐. 기안 상태에서는 NULL';

COMMENT ON COLUMN approval_document.completed_at IS '완료 일시 - 저장 후 처리로 채워짐. 완료 상태에서 필수';

COMMENT ON COLUMN approval_document.created_at IS '생성 일시';

COMMENT ON COLUMN approval_document.updated_at IS '수정 일시';

CREATE TABLE approval_form (
    approval_form_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    form_name VARCHAR(200) NOT NULL,
    form_body TEXT,
    approval_process_rule TEXT,
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_approval_form PRIMARY KEY (approval_form_id),
    CONSTRAINT ck_approval_form_use_status CHECK (use_status IN ('사용', '미사용'))
);

COMMENT ON TABLE approval_form IS '결재양식 - 한 행=결재양식 1건. 사용 여부.';

COMMENT ON COLUMN approval_form.approval_form_id IS '결재양식 ID - 대리키';

COMMENT ON COLUMN approval_form.form_name IS '결재양식명 - 길이는 가정';

COMMENT ON COLUMN approval_form.form_body IS '양식 본문(HTML) - HTML 결재양식 본문. 파일 변환 후 편집·저장되므로 최초 저장 시 비어 있을 수 있음(가정)';

COMMENT ON COLUMN approval_form.approval_process_rule IS '결재 프로세스 규칙 - (가정) 업무규정 기반 결재 프로세스 규칙. 결재선은 별도 엔티티로 관리(카탈로그에 없음, 확인 필요)';

COMMENT ON COLUMN approval_form.use_status IS '사용 여부 - 공통 결정의 사용 여부 도메인. 초기값은 사용(가정). 미사용 양식은 기안 시 선택 불가';

COMMENT ON COLUMN approval_form.created_at IS '생성 일시';

COMMENT ON COLUMN approval_form.updated_at IS '수정 일시';

CREATE TABLE notification (
    notification_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    recipient_id BIGINT NOT NULL,
    channel VARCHAR(10) NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    read_status VARCHAR(10) NOT NULL,
    read_at TIMESTAMPTZ,
    event_type VARCHAR(50),
    target_type VARCHAR(50),
    target_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_notification PRIMARY KEY (notification_id),
    CONSTRAINT ck_notification_channel CHECK (channel IN ('포털', '메신저', '모바일', '대화방', '메일')),
    CONSTRAINT ck_notification_read_status CHECK (read_status IN ('안읽음', '읽음')),
    CONSTRAINT ck_notification_read_at_req CHECK (read_status NOT IN ('읽음') OR read_at IS NOT NULL),
    CONSTRAINT ck_notification_target_id_req CHECK (target_type NOT IN ('APPROVAL_DOCUMENT') OR target_id IS NOT NULL)
);

COMMENT ON TABLE notification IS '알림 - 한 행=수신자별 알림 1건. 채널, 읽음 상태(읽음/안읽음), 바로가기 대상.';

COMMENT ON COLUMN notification.notification_id IS '알림 ID - 대리키';

COMMENT ON COLUMN notification.recipient_id IS '수신자 - 수신자별 1건. 본인 수신 알림만 조회';

COMMENT ON COLUMN notification.channel IS '알림 채널 - 공통 결정 알림 채널(원문). 첫 값 포털은 기본 채널로 가정';

COMMENT ON COLUMN notification.title IS '알림 제목 - 길이는 가정';

COMMENT ON COLUMN notification.content IS '알림 내용 - 알림 요약·상세 내용';

COMMENT ON COLUMN notification.read_status IS '읽음 상태 - 신규 알림은 안읽음으로 생성(원문)';

COMMENT ON COLUMN notification.read_at IS '읽은 일시 - 읽음 처리 시 채워짐';

COMMENT ON COLUMN notification.event_type IS '알림 이벤트 유형 - (가정) 결재 요청·승인·반려, @멘션, 예약 승인 등 이벤트. 전체 코드 집합 미확정이라 허용값 생략';

COMMENT ON COLUMN notification.target_type IS '바로가기 대상 유형 - (가정) 이동할 메뉴·문서 유형. 코드 집합 미확정';

COMMENT ON COLUMN notification.target_id IS '바로가기 대상 ID - (가정) 바로가기 대상 PK. 다형 참조라 FK 불가. 이동 시 권한 확인 필요';

COMMENT ON COLUMN notification.created_at IS '생성 일시';

COMMENT ON COLUMN notification.updated_at IS '수정 일시';

CREATE TABLE attachment (
    attachment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    uploader_id BIGINT NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    file_extension VARCHAR(20),
    file_size BIGINT,
    ecm_ref VARCHAR(500),
    file_hash VARCHAR(128),
    target_type VARCHAR(50),
    target_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attachment PRIMARY KEY (attachment_id),
    CONSTRAINT ck_attachment_target_id_req CHECK (target_type NOT IN ('APPROVAL_DOCUMENT', 'APPROVAL_FORM') OR target_id IS NOT NULL),
    CONSTRAINT ck_attachment_file_size_ge_0 CHECK (file_size >= 0)
);

COMMENT ON TABLE attachment IS '첨부파일 - 한 행=첨부파일 1건. ECM 저장 참조. 업무 대상은 유형+ID로 참조(가정).';

COMMENT ON COLUMN attachment.attachment_id IS '첨부파일 ID - 대리키';

COMMENT ON COLUMN attachment.uploader_id IS '업로드 임직원 - 외부 시스템(ECM) 자동 저장 시에도 등록 임직원 필요(가정)';

COMMENT ON COLUMN attachment.file_name IS '파일명 - 길이는 가정';

COMMENT ON COLUMN attachment.file_extension IS '확장자 - 미리보기 대상(HWP·Word·Excel·PPT) 판단용';

COMMENT ON COLUMN attachment.file_size IS '파일 크기(바이트)';

COMMENT ON COLUMN attachment.ecm_ref IS 'ECM 저장 참조 - ECM 문서 식별자. 자동 저장 후 채워질 수 있어 NULL 허용(가정). 파일 본문은 DB에 저장하지 않음';

COMMENT ON COLUMN attachment.file_hash IS '파일 해시 - (가정) 중복 검증용 해시. 중복 시 안내 후 사용자 선택이라 유일 제약은 두지 않음';

COMMENT ON COLUMN attachment.target_type IS '업무 대상 유형 - (가정) 업무 대상 유형+ID 참조. 코드 집합 미확정';

COMMENT ON COLUMN attachment.target_id IS '업무 대상 ID - (가정) 다형 참조라 FK 불가';

COMMENT ON COLUMN attachment.created_at IS '생성 일시';

COMMENT ON COLUMN attachment.updated_at IS '수정 일시';

CREATE TABLE budget_main (
    budget_main_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    accounting_unit VARCHAR(50) NOT NULL,
    fiscal_year INTEGER NOT NULL,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    budget_group VARCHAR(100),
    requested_amount NUMERIC(18,2) NOT NULL,
    requested_date DATE NOT NULL,
    requester_id BIGINT NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_main PRIMARY KEY (budget_main_id),
    CONSTRAINT ck_budget_main_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT uq_budget_main_accounting_unit_fiscal_year_project_id__dc984588 UNIQUE (accounting_unit, fiscal_year, project_id, budget_account_id),
    CONSTRAINT ck_budget_main_requested_amount_ge_0 CHECK (requested_amount >= 0)
);

COMMENT ON TABLE budget_main IS '본예산 - 한 행=회계단위·기수·프로젝트·예산과목별 본예산 1건. 승인 처리 상태 속성.';

COMMENT ON COLUMN budget_main.budget_main_id IS '본예산 ID - 대리키';

COMMENT ON COLUMN budget_main.accounting_unit IS '회계단위 - (가정) 회계단위 코드/명 문자열, 신청 시 필수 입력. 별도 엔티티 없음(카탈로그 수정 필요 여부 확인 필요)';

COMMENT ON COLUMN budget_main.fiscal_year IS '기수(회계연도) - 신청 시 필수 입력. 회계연도(예: 2025)';

COMMENT ON COLUMN budget_main.project_id IS '프로젝트';

COMMENT ON COLUMN budget_main.budget_account_id IS '예산과목';

COMMENT ON COLUMN budget_main.budget_group IS '예산그룹 - (가정) 예산그룹 구분 문자열, 필수 여부 불명확하여 선택값';

COMMENT ON COLUMN budget_main.requested_amount IS '신청금액 - 신청 시 예산과목별 입력. 원 단위 금액';

COMMENT ON COLUMN budget_main.requested_date IS '신청일 - 신청 시 입력';

COMMENT ON COLUMN budget_main.requester_id IS '신청자';

COMMENT ON COLUMN budget_main.approval_status IS '승인 처리 상태 - 공통 결정 ''승인 처리 상태'' 도메인 사용. 초기값: 신청 저장→신청';

COMMENT ON COLUMN budget_main.created_at IS '생성 일시';

COMMENT ON COLUMN budget_main.updated_at IS '수정 일시';

CREATE TABLE budget_execution (
    budget_execution_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    budget_main_id BIGINT NOT NULL,
    execution_month INTEGER NOT NULL,
    execution_amount NUMERIC(18,2) NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_execution PRIMARY KEY (budget_execution_id),
    CONSTRAINT ck_budget_execution_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT uq_budget_execution_budget_main_id_execution_month UNIQUE (budget_main_id, execution_month),
    CONSTRAINT ck_budget_execution_execution_month_ge_1 CHECK (execution_month >= 1),
    CONSTRAINT ck_budget_execution_execution_month_le_12 CHECK (execution_month <= 12),
    CONSTRAINT ck_budget_execution_execution_amount_ge_0 CHECK (execution_amount >= 0)
);

COMMENT ON TABLE budget_execution IS '실행예산 - 한 행=월별 실행예산 1건. 본예산 기반.';

COMMENT ON COLUMN budget_execution.budget_execution_id IS '실행예산 ID - 대리키';

COMMENT ON COLUMN budget_execution.budget_main_id IS '본예산';

COMMENT ON COLUMN budget_execution.execution_month IS '편성월 - 월 단위 편성(1~12)';

COMMENT ON COLUMN budget_execution.execution_amount IS '실행예산 금액 - 월별 실행예산 금액 입력';

COMMENT ON COLUMN budget_execution.approval_status IS '승인 처리 상태 - 공통 결정 ''승인 처리 상태'' 도메인 사용. 초기값: 신청 저장→신청 (가정)';

COMMENT ON COLUMN budget_execution.created_at IS '생성 일시';

COMMENT ON COLUMN budget_execution.updated_at IS '수정 일시';

CREATE TABLE budget_adjustment (
    budget_adjustment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    target_budget_account_id BIGINT,
    adjustment_type VARCHAR(20) NOT NULL,
    adjustment_amount NUMERIC(18,2) NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_adjustment PRIMARY KEY (budget_adjustment_id),
    CONSTRAINT ck_budget_adjustment_adjustment_type CHECK (adjustment_type IN ('추경예산', '전용', '이용', '예비비')),
    CONSTRAINT ck_budget_adjustment_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_budget_adjustment_target_budget_account_id_req CHECK (adjustment_type NOT IN ('전용', '이용') OR target_budget_account_id IS NOT NULL),
    CONSTRAINT ck_budget_adjustment_adjustment_amount_gt_0 CHECK (adjustment_amount > 0),
    CONSTRAINT ck_budget_adjustment_target_budget_account_id_ne_budge_36efd277 CHECK (target_budget_account_id <> budget_account_id)
);

COMMENT ON TABLE budget_adjustment IS '예산조정 - 한 행=예산조정 1건. 구분(추경예산/전용/이용/예비비).';

COMMENT ON COLUMN budget_adjustment.budget_adjustment_id IS '예산조정 ID - 대리키';

COMMENT ON COLUMN budget_adjustment.project_id IS '프로젝트';

COMMENT ON COLUMN budget_adjustment.budget_account_id IS '예산과목(출처) - 전용·이용이면 출처 예산과목, 추경예산·예비비이면 대상 예산과목 (가정)';

COMMENT ON COLUMN budget_adjustment.target_budget_account_id IS '상대 예산과목 - 전용·이용일 때 대상 예산과목. 카탈로그 parents에 budget_account가 한 번만 있어 역할별 참조 추가 필요 (카탈로그 수정 필요)';

COMMENT ON COLUMN budget_adjustment.adjustment_type IS '예산 조정 구분 - 원문 확정 목록. 신청 시 선택';

COMMENT ON COLUMN budget_adjustment.adjustment_amount IS '조정 금액 - 신청 시 입력';

COMMENT ON COLUMN budget_adjustment.approval_status IS '승인 처리 상태 - 공통 승인 처리 상태 도메인. 초기값: 신청 (신청된 예산조정만 마감 가능)';

COMMENT ON COLUMN budget_adjustment.created_at IS '생성 일시';

COMMENT ON COLUMN budget_adjustment.updated_at IS '수정 일시';

CREATE TABLE requisition (
    requisition_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    drafter_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    requisition_type VARCHAR(20) NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    requisition_amount NUMERIC(18,2) NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_requisition PRIMARY KEY (requisition_id),
    CONSTRAINT ck_requisition_requisition_type CHECK (requisition_type IN ('지출', '구매')),
    CONSTRAINT ck_requisition_status CHECK (status IN ('기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료')),
    CONSTRAINT ck_requisition_requisition_amount_gt_0 CHECK (requisition_amount > 0)
);

COMMENT ON TABLE requisition IS '품의서 - 한 행=품의서 1건(지출/구매 구분 유형 속성). 프로젝트·예산과목 필수.';

COMMENT ON COLUMN requisition.requisition_id IS '품의서 ID - 대리키';

COMMENT ON COLUMN requisition.project_id IS '프로젝트';

COMMENT ON COLUMN requisition.budget_account_id IS '예산과목';

COMMENT ON COLUMN requisition.drafter_id IS '기안자';

COMMENT ON COLUMN requisition.approval_document_id IS '전자결재 문서 - 상신 시점에 연결되므로 저장 시점에는 없을 수 있음 (가정). 결재 연계 사용 여부는 환경설정에 따름';

COMMENT ON COLUMN requisition.requisition_type IS '품의 유형 - (가정) 지출품의서/구매품의서 구분 코드';

COMMENT ON COLUMN requisition.title IS '품의 제목 - (가정) 길이 200';

COMMENT ON COLUMN requisition.content IS '품의 내용 - 품의 내용 또는 구매 내용';

COMMENT ON COLUMN requisition.requisition_amount IS '품의 금액';

COMMENT ON COLUMN requisition.status IS '처리 상태 - 전자결재 처리 상태 도메인 사용. 초기값: 작성 저장→기안 (가정). 결재 결과를 상태에 반영';

COMMENT ON COLUMN requisition.created_at IS '생성 일시';

COMMENT ON COLUMN requisition.updated_at IS '수정 일시';

CREATE TABLE expense_resolution (
    expense_resolution_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requisition_id BIGINT,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    partner_id BIGINT,
    department_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    resolution_method VARCHAR(20) NOT NULL,
    resolution_amount NUMERIC(18,2) NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_expense_resolution PRIMARY KEY (expense_resolution_id),
    CONSTRAINT ck_expense_resolution_resolution_method CHECK (resolution_method IN ('카드사용내역', '세금계산서', '통장거래내역', '직접입력')),
    CONSTRAINT ck_expense_resolution_status CHECK (status IN ('기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료')),
    CONSTRAINT ck_expense_resolution_resolution_amount_gt_0 CHECK (resolution_amount > 0)
);

COMMENT ON TABLE expense_resolution IS '결의서 - 한 행=결의서 1건. 품의서 선택 연결, 거래처·예산과목 참조.';

COMMENT ON COLUMN expense_resolution.expense_resolution_id IS '결의서 ID - 대리키';

COMMENT ON COLUMN expense_resolution.requisition_id IS '품의서 - 연계 품의서가 있을 때만';

COMMENT ON COLUMN expense_resolution.project_id IS '프로젝트 - 검토 지적 반영. 카탈로그 parents에 project 없음 (카탈로그 수정 필요)';

COMMENT ON COLUMN expense_resolution.budget_account_id IS '예산과목';

COMMENT ON COLUMN expense_resolution.partner_id IS '거래처 - 직접입력 등 거래처 없는 경우 가능 (가정)';

COMMENT ON COLUMN expense_resolution.department_id IS '결의부서';

COMMENT ON COLUMN expense_resolution.approval_document_id IS '전자결재 문서 - 상신 후 연계되므로 저장 후 채움 (가정)';

COMMENT ON COLUMN expense_resolution.resolution_method IS '결의 방식 - 4가지 방식 확정 (표시 코드는 가정)';

COMMENT ON COLUMN expense_resolution.resolution_amount IS '결의 금액 - 입력 필수';

COMMENT ON COLUMN expense_resolution.status IS '진행 상태 - 전자결재 처리 상태 도메인을 따름. 초기값: 기안 (가정)';

COMMENT ON COLUMN expense_resolution.created_at IS '생성 일시';

COMMENT ON COLUMN expense_resolution.updated_at IS '수정 일시';

CREATE TABLE journal_entry (
    journal_entry_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    expense_resolution_id BIGINT NOT NULL,
    entry_date DATE NOT NULL,
    status VARCHAR(20) NOT NULL,
    total_debit_amount NUMERIC(18,2),
    total_credit_amount NUMERIC(18,2),
    summary VARCHAR(500),
    evidence_detail VARCHAR(1000),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_journal_entry PRIMARY KEY (journal_entry_id),
    CONSTRAINT ck_journal_entry_status CHECK (status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_journal_entry_total_debit_amount_ge_0 CHECK (total_debit_amount >= 0),
    CONSTRAINT ck_journal_entry_total_credit_amount_ge_0 CHECK (total_credit_amount >= 0)
);

COMMENT ON TABLE journal_entry IS '전표 - 한 행=전표 1건. 차대변 일치 필수.';

COMMENT ON COLUMN journal_entry.journal_entry_id IS '전표 ID - 대리키';

COMMENT ON COLUMN journal_entry.expense_resolution_id IS '결의서 ID - 승인된 결의서 기반 생성(FN-SFR-004-05). 한 결의서당 전표 수는 불명확하여 unique 미적용(확인 필요)';

COMMENT ON COLUMN journal_entry.entry_date IS '전표 일자 - 전표 입력 시 공급';

COMMENT ON COLUMN journal_entry.status IS '전표 상태 - 승인 처리 상태 도메인 사용. (가정) 최초 저장 시 ''신청''. 승인 해제는 ''승인 취소''로 표현. 결재 연계 결과 반영. 마감 기간 수정 불가 규칙은 (확인 필요)';

COMMENT ON COLUMN journal_entry.total_debit_amount IS '차변 합계 - 저장 후 산출. 분개 라인 합계이며 차대변 일치는 라인 간 규칙으로 (확인 필요)';

COMMENT ON COLUMN journal_entry.total_credit_amount IS '대변 합계 - 저장 후 산출. 차변 합계와 일치해야 함(확인 필요)';

COMMENT ON COLUMN journal_entry.summary IS '적요 - (가정) 길이 500';

COMMENT ON COLUMN journal_entry.evidence_detail IS '증빙내역 - (가정) 길이 1000. 증빙내역 일괄 변경 대상';

COMMENT ON COLUMN journal_entry.created_at IS '생성 일시';

COMMENT ON COLUMN journal_entry.updated_at IS '수정 일시';

CREATE TABLE journal_entry_line (
    journal_entry_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    journal_entry_id BIGINT NOT NULL,
    account_subject_id BIGINT NOT NULL,
    partner_id BIGINT,
    project_id BIGINT,
    budget_account_id BIGINT,
    line_no INTEGER NOT NULL,
    debit_amount NUMERIC(18,2) NOT NULL,
    credit_amount NUMERIC(18,2) NOT NULL,
    management_item_value VARCHAR(500),
    summary VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_journal_entry_line PRIMARY KEY (journal_entry_line_id),
    CONSTRAINT uq_journal_entry_line_journal_entry_id_line_no UNIQUE (journal_entry_id, line_no),
    CONSTRAINT ck_journal_entry_line_debit_amount_ge_0 CHECK (debit_amount >= 0),
    CONSTRAINT ck_journal_entry_line_credit_amount_ge_0 CHECK (credit_amount >= 0)
);

COMMENT ON TABLE journal_entry_line IS '전표 분개 라인 - 한 행=전표의 분개 1줄. 계정과목·거래처·프로젝트·예산과목 참조.';

COMMENT ON COLUMN journal_entry_line.journal_entry_line_id IS '전표 분개 라인 ID - 대리키';

COMMENT ON COLUMN journal_entry_line.journal_entry_id IS '전표 ID';

COMMENT ON COLUMN journal_entry_line.account_subject_id IS '계정과목 ID';

COMMENT ON COLUMN journal_entry_line.partner_id IS '거래처 ID - (가정) 계정과목에 따라 선택';

COMMENT ON COLUMN journal_entry_line.project_id IS '프로젝트 ID - (가정) 선택';

COMMENT ON COLUMN journal_entry_line.budget_account_id IS '예산과목 ID - (가정) 선택';

COMMENT ON COLUMN journal_entry_line.line_no IS '라인 순번 - 전표 내 분개 순번, 삽입 시 공급';

COMMENT ON COLUMN journal_entry_line.debit_amount IS '차변 금액 - 입력 시 공급, 대변 라인은 0 (가정)';

COMMENT ON COLUMN journal_entry_line.credit_amount IS '대변 금액 - 입력 시 공급, 차변 라인은 0 (가정)';

COMMENT ON COLUMN journal_entry_line.management_item_value IS '관리항목 값 - (가정) 계정과목별 관리항목 값, 항목 구조는 확인 필요';

COMMENT ON COLUMN journal_entry_line.summary IS '적요 - (가정) 길이 500';

COMMENT ON COLUMN journal_entry_line.created_at IS '생성 일시';

COMMENT ON COLUMN journal_entry_line.updated_at IS '수정 일시';

CREATE TABLE attendance_request (
    attendance_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    attendance_type VARCHAR(20) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    reason VARCHAR(1000),
    changed_work_time VARCHAR(100),
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attendance_request PRIMARY KEY (attendance_request_id),
    CONSTRAINT ck_attendance_request_attendance_type CHECK (attendance_type IN ('연차', '반차', '보상휴가', '병가', '예비군', '출장', '외근', '교육')),
    CONSTRAINT ck_attendance_request_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_attendance_request_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE attendance_request IS '근태 - 한 행=근태 신청 1건. 근태 유형 속성, 승인 처리 상태.';

COMMENT ON COLUMN attendance_request.attendance_request_id IS '근태 ID - 대리키';

COMMENT ON COLUMN attendance_request.employee_id IS '신청자 ID';

COMMENT ON COLUMN attendance_request.approval_document_id IS '전자결재 문서 ID - 결재 연계 사용 여부는 환경설정에 따르므로 선택 (가정)';

COMMENT ON COLUMN attendance_request.attendance_type IS '근태 유형';

COMMENT ON COLUMN attendance_request.start_date IS '시작일';

COMMENT ON COLUMN attendance_request.end_date IS '종료일';

COMMENT ON COLUMN attendance_request.reason IS '사유 - (가정) 길이 1000, 선택';

COMMENT ON COLUMN attendance_request.changed_work_time IS '변경 근무시간 - (가정) 근무변경 신청 시에만 입력, 형식 확인 필요';

COMMENT ON COLUMN attendance_request.approval_status IS '승인 처리 상태 - 신청 시 ''신청''으로 시작';

COMMENT ON COLUMN attendance_request.created_at IS '생성 일시';

COMMENT ON COLUMN attendance_request.updated_at IS '수정 일시';

CREATE TABLE payroll (
    payroll_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    pay_date DATE NOT NULL,
    total_payment_amount_enc VARCHAR(500),
    total_deduction_amount_enc VARCHAR(500),
    net_pay_amount_enc VARCHAR(500),
    closing_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll PRIMARY KEY (payroll_id),
    CONSTRAINT ck_payroll_closing_status CHECK (closing_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT uq_payroll_employee_id_pay_date UNIQUE (employee_id, pay_date)
);

COMMENT ON TABLE payroll IS '급여 - 한 행=임직원·지급일별 급여 1건. 암호화 저장.';

COMMENT ON COLUMN payroll.payroll_id IS '급여 ID - 대리키';

COMMENT ON COLUMN payroll.employee_id IS '임직원 ID';

COMMENT ON COLUMN payroll.pay_date IS '급여 지급일 - 입력 시 공급';

COMMENT ON COLUMN payroll.total_payment_amount_enc IS '총 지급액(암호문) - 암호화 저장. 저장 후 산출';

COMMENT ON COLUMN payroll.total_deduction_amount_enc IS '총 공제액(암호문) - 암호화 저장. 저장 후 산출';

COMMENT ON COLUMN payroll.net_pay_amount_enc IS '실지급액(암호문) - 암호화 저장. 저장 후 산출';

COMMENT ON COLUMN payroll.closing_status IS '마감 상태 - (가정) 승인 처리 상태 도메인 사용, 급여 생성 시 ''신청''. 마감 승인 요청은 결재 연계';

COMMENT ON COLUMN payroll.created_at IS '생성 일시';

COMMENT ON COLUMN payroll.updated_at IS '수정 일시';

CREATE TABLE asset (
    asset_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_code VARCHAR(50) NOT NULL,
    asset_no VARCHAR(50) NOT NULL,
    asset_name VARCHAR(200) NOT NULL,
    asset_type VARCHAR(50),
    asset_category VARCHAR(50),
    location VARCHAR(200),
    manager_id BIGINT,
    project_id BIGINT,
    account_subject_id BIGINT,
    partner_id BIGINT,
    rfid_tag_value VARCHAR(100),
    is_depreciable BOOLEAN NOT NULL,
    depreciation_method VARCHAR(30),
    useful_life_months INTEGER,
    acquisition_amount NUMERIC(18,2),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset PRIMARY KEY (asset_id),
    CONSTRAINT uq_asset_rfid_tag_value UNIQUE (rfid_tag_value),
    CONSTRAINT uq_asset_asset_code_asset_no UNIQUE (asset_code, asset_no),
    CONSTRAINT ck_asset_depreciation_method_req CHECK (is_depreciable NOT IN ('true') OR depreciation_method IS NOT NULL),
    CONSTRAINT ck_asset_useful_life_months_req CHECK (is_depreciable NOT IN ('true') OR useful_life_months IS NOT NULL),
    CONSTRAINT ck_asset_acquisition_amount_req CHECK (is_depreciable NOT IN ('true') OR acquisition_amount IS NOT NULL),
    CONSTRAINT ck_asset_acquisition_amount_ge_0 CHECK (acquisition_amount >= 0),
    CONSTRAINT ck_asset_useful_life_months_gt_0 CHECK (useful_life_months > 0)
);

COMMENT ON TABLE asset IS '자산 - 한 행=자산 1건. 자산코드·번호 유일.';

COMMENT ON COLUMN asset.asset_id IS '자산 ID - 대리키';

COMMENT ON COLUMN asset.asset_code IS '자산코드 - 길이 (가정)';

COMMENT ON COLUMN asset.asset_no IS '자산번호 - 자산코드별 유일';

COMMENT ON COLUMN asset.asset_name IS '자산명';

COMMENT ON COLUMN asset.asset_type IS '자산 유형 - 전체 분류 미확정 (확인 필요)';

COMMENT ON COLUMN asset.asset_category IS '자산 분류 - 전체 분류 미확정 (확인 필요)';

COMMENT ON COLUMN asset.location IS '위치';

COMMENT ON COLUMN asset.manager_id IS '담당자';

COMMENT ON COLUMN asset.project_id IS '프로젝트';

COMMENT ON COLUMN asset.account_subject_id IS '계정과목';

COMMENT ON COLUMN asset.partner_id IS '거래처';

COMMENT ON COLUMN asset.rfid_tag_value IS 'RFID 태그 식별값 - 태그 미부착 자산은 NULL (가정)';

COMMENT ON COLUMN asset.is_depreciable IS '상각 여부 - 등록 시 입력';

COMMENT ON COLUMN asset.depreciation_method IS '상각 방법 - 상각 자산일 때 필수. 방법 목록 미확정 (확인 필요)';

COMMENT ON COLUMN asset.useful_life_months IS '내용연수(월) - 상각 자산일 때 필수';

COMMENT ON COLUMN asset.acquisition_amount IS '취득원가 - 고정자산 등록 시 필수(0 이상), 일반 자산은 선택 (가정)';

COMMENT ON COLUMN asset.created_at IS '생성 일시';

COMMENT ON COLUMN asset.updated_at IS '수정 일시';

CREATE TABLE personal_info_access_log (
    personal_info_access_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    target_employee_id BIGINT,
    target_info_type VARCHAR(50) NOT NULL,
    access_type VARCHAR(50),
    accessed_at TIMESTAMPTZ NOT NULL,
    access_ip VARCHAR(45),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_personal_info_access_log PRIMARY KEY (personal_info_access_log_id)
);

COMMENT ON TABLE personal_info_access_log IS '개인정보 열람 이력 - 한 행=개인정보 열람·접근 1건.';

COMMENT ON COLUMN personal_info_access_log.personal_info_access_log_id IS '개인정보 열람 이력 ID - 대리키';

COMMENT ON COLUMN personal_info_access_log.employee_id IS '열람자 - 개인정보를 열람·접근한 임직원(계정). 기록 시점에 공급';

COMMENT ON COLUMN personal_info_access_log.target_employee_id IS '열람 대상 임직원 - (가정) 열람된 개인정보의 주체 임직원. 카탈로그 parents에는 employee 1개만 있어 역할별 FK 추가 시 (카탈로그 수정 필요)';

COMMENT ON COLUMN personal_info_access_log.target_info_type IS '열람 대상 정보 구분 - (확인 필요) 대상 정보 구분(주민번호, 급여, 인사정보 등)의 전체 코드 목록이 확정되지 않아 allowed_values 생략. 길이는 (가정)';

COMMENT ON COLUMN personal_info_access_log.access_type IS '접근 유형 - (가정) 열람·접근 행위 구분. 코드 체계 미확정으로 allowed_values 생략 (확인 필요)';

COMMENT ON COLUMN personal_info_access_log.accessed_at IS '열람일시 - 열람·접근 발생 시각. 기록 시 시스템이 공급하며 감사 컬럼과 별도. 추가 전용 이력';

COMMENT ON COLUMN personal_info_access_log.access_ip IS '접속 IP - (가정) IPv6까지 수용하는 길이. 필수 여부 미확정';

COMMENT ON COLUMN personal_info_access_log.created_at IS '생성 일시';

COMMENT ON COLUMN personal_info_access_log.updated_at IS '수정 일시';

CREATE TABLE login_history (
    login_history_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    login_at TIMESTAMPTZ NOT NULL,
    login_ip VARCHAR(45) NOT NULL,
    login_type VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_login_history PRIMARY KEY (login_history_id),
    CONSTRAINT ck_login_history_login_type CHECK (login_type IN ('웹', '메신저', '모바일 앱'))
);

COMMENT ON TABLE login_history IS '로그인 내역 - 한 행=로그인 성공 1건. 로그인 구분(웹/메신저/모바일 앱).';

COMMENT ON COLUMN login_history.login_history_id IS '로그인 내역 ID - 대리키';

COMMENT ON COLUMN login_history.employee_id IS '사용자 - 로그인한 임직원. 사용자명과 ID는 임직원에서 조회하므로 중복 저장하지 않음';

COMMENT ON COLUMN login_history.login_at IS '접속일시 - 로그인 성공 시 시스템이 자동 기록하여 INSERT 시 공급';

COMMENT ON COLUMN login_history.login_ip IS '로그인 IP - (가정) IPv6까지 수용하는 길이. 조회 항목이므로 로그인 시 항상 공급';

COMMENT ON COLUMN login_history.login_type IS '로그인 구분 - 확정 결정: 웹, 메신저, 모바일 앱 값만 사용. 로그인 성공 시 공급';

COMMENT ON COLUMN login_history.created_at IS '생성 일시';

COMMENT ON COLUMN login_history.updated_at IS '수정 일시';

CREATE TABLE system_setting (
    system_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    category VARCHAR(50) NOT NULL,
    setting_key VARCHAR(100) NOT NULL,
    setting_name VARCHAR(200),
    setting_value VARCHAR(1000),
    description VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_system_setting PRIMARY KEY (system_setting_id),
    CONSTRAINT uq_system_setting_category_setting_key UNIQUE (category, setting_key)
);

COMMENT ON TABLE system_setting IS '환경설정 - 한 행=환경설정 항목 1개(분류+키+값). 예산·승인번호·전자결재 사용·근태·급여·자산·연령구간 등 설정. 변경은 이후 업무부터 적용. 설정 항목 구성은 (가정).';

COMMENT ON COLUMN system_setting.system_setting_id IS '환경설정 ID - 대리키';

COMMENT ON COLUMN system_setting.category IS '설정 분류 - 예산·승인번호·전자결재·근태·급여·자산·연령구간 등 설정 분류. 분류 전체 목록 미확정이라 allowed_values 생략 (가정)';

COMMENT ON COLUMN system_setting.setting_key IS '설정 키 - 분류 내 설정 항목 키 (가정)';

COMMENT ON COLUMN system_setting.setting_name IS '설정 항목명 - 화면 표시용 항목명 (가정)';

COMMENT ON COLUMN system_setting.setting_value IS '설정 값 - 설정 값. 항목별 값 형식이 달라 문자열로 저장하며 값 도메인은 항목별 정의 필요 (확인 필요). 값이 미설정인 항목이 있을 수 있어 NULL 허용 (가정)';

COMMENT ON COLUMN system_setting.description IS '설명 - 설정 항목 설명 (가정)';

COMMENT ON COLUMN system_setting.created_at IS '생성 일시';

COMMENT ON COLUMN system_setting.updated_at IS '수정 일시';

CREATE TABLE accounting_unit (
    accounting_unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    unit_code VARCHAR(20) NOT NULL,
    unit_name VARCHAR(200) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    description VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_accounting_unit PRIMARY KEY (accounting_unit_id),
    CONSTRAINT uq_accounting_unit_unit_code UNIQUE (unit_code),
    CONSTRAINT ck_accounting_unit_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE accounting_unit IS '회계단위 - 한 행=회계단위 1개. 회계단위 코드 기준. 결산·재무제표 구분 기준.';

COMMENT ON COLUMN accounting_unit.accounting_unit_id IS '회계단위 ID - 대리키';

COMMENT ON COLUMN accounting_unit.unit_code IS '회계단위 코드 - 회계단위 코드 기준으로 유일. 식별용 번호라 선행 0 보존 (가정)';

COMMENT ON COLUMN accounting_unit.unit_name IS '회계단위명 - 길이 (가정)';

COMMENT ON COLUMN accounting_unit.use_yn IS '사용 여부 - 공통 사용 여부 도메인. 초기값은 사용 (가정)';

COMMENT ON COLUMN accounting_unit.description IS '설명 - 결산·재무제표 구분 기준 설명 (가정)';

COMMENT ON COLUMN accounting_unit.created_at IS '생성 일시';

COMMENT ON COLUMN accounting_unit.updated_at IS '수정 일시';

CREATE TABLE budget_closing_period (
    budget_closing_period_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    closing_type VARCHAR(20) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_closing_period PRIMARY KEY (budget_closing_period_id),
    CONSTRAINT ck_budget_closing_period_closing_type CHECK (closing_type IN ('결의서', '출납')),
    CONSTRAINT ck_budget_closing_period_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE budget_closing_period IS '예산 폐쇄기간 - 한 행=폐쇄기간 1건. 구분(결의서/출납), 시작일·종료일(종료일>=시작일).';

COMMENT ON COLUMN budget_closing_period.budget_closing_period_id IS '예산 폐쇄기간 ID - 대리키';

COMMENT ON COLUMN budget_closing_period.closing_type IS '폐쇄 구분 - 폐쇄기간 구분(결의서/출납). 원문 기준 전체 집합';

COMMENT ON COLUMN budget_closing_period.start_date IS '시작일';

COMMENT ON COLUMN budget_closing_period.end_date IS '종료일 - 시작일 이상이어야 함';

COMMENT ON COLUMN budget_closing_period.created_at IS '생성 일시';

COMMENT ON COLUMN budget_closing_period.updated_at IS '수정 일시';

CREATE TABLE budget_carryover (
    budget_carryover_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    carryover_amount NUMERIC(18,2) NOT NULL,
    is_initial_carryover BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_carryover PRIMARY KEY (budget_carryover_id),
    CONSTRAINT uq_budget_carryover_project_id_budget_account_id_is_in_cc6439c0 UNIQUE (project_id, budget_account_id, is_initial_carryover),
    CONSTRAINT ck_budget_carryover_carryover_amount_ge_0 CHECK (carryover_amount >= 0)
);

COMMENT ON TABLE budget_carryover IS '예산 이월 - 한 행=프로젝트·예산과목별 이월 대상 금액 1건. 초기 이월 여부 구분 속성. 프로젝트 N:1 필수, 예산과목 N:1 필수.';

COMMENT ON COLUMN budget_carryover.budget_carryover_id IS '예산 이월 ID - 대리키';

COMMENT ON COLUMN budget_carryover.project_id IS '프로젝트';

COMMENT ON COLUMN budget_carryover.budget_account_id IS '예산과목';

COMMENT ON COLUMN budget_carryover.carryover_amount IS '이월 대상 금액 - 입력 필수값으로 간주 (가정). 정밀도는 금액 표준 따름 (확인 필요)';

COMMENT ON COLUMN budget_carryover.is_initial_carryover IS '초기 이월 여부 - 초기 이월 구분. 등록 시 지정 (가정)';

COMMENT ON COLUMN budget_carryover.created_at IS '생성 일시';

COMMENT ON COLUMN budget_carryover.updated_at IS '수정 일시';

CREATE TABLE account_carryover (
    account_carryover_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fiscal_year INTEGER NOT NULL,
    account_subject_id BIGINT NOT NULL,
    partner_id BIGINT,
    project_id BIGINT,
    carryover_amount NUMERIC(18,2) NOT NULL,
    closing_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_account_carryover PRIMARY KEY (account_carryover_id),
    CONSTRAINT ck_account_carryover_closing_status CHECK (closing_status IN ('미마감', '마감')),
    CONSTRAINT uq_account_carryover_fiscal_year_account_subject_id_pa_c0d23d0d UNIQUE (fiscal_year, account_subject_id, partner_id, project_id)
);

COMMENT ON TABLE account_carryover IS '계정별 초기이월 - 한 행=회계연도·계정과목·거래처(·프로젝트)별 이월내역 1건. 이월 금액, 마감 여부. 계정과목 필수, 거래처·프로젝트 선택.';

COMMENT ON COLUMN account_carryover.account_carryover_id IS '계정별 초기이월 ID - 대리키';

COMMENT ON COLUMN account_carryover.fiscal_year IS '회계연도 - 예: 2025 (가정)';

COMMENT ON COLUMN account_carryover.account_subject_id IS '계정과목';

COMMENT ON COLUMN account_carryover.partner_id IS '거래처 - 선택';

COMMENT ON COLUMN account_carryover.project_id IS '프로젝트 - 선택';

COMMENT ON COLUMN account_carryover.carryover_amount IS '이월 금액 - 등록 시 입력 필수 (가정). 차변/대변 부호 처리는 확인 필요';

COMMENT ON COLUMN account_carryover.closing_status IS '마감 여부 - (가정) 등록 시 미마감으로 시작. 공통 승인 처리 상태의 ''마감''과 동일 의미로 사용, 미마감은 신규 값이므로 (확인 필요) 공통 도메인 조정: 마감 전 상태 표현';

COMMENT ON COLUMN account_carryover.created_at IS '생성 일시';

COMMENT ON COLUMN account_carryover.updated_at IS '수정 일시';

CREATE TABLE upload_history (
    upload_history_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    uploader_id BIGINT NOT NULL,
    target_business VARCHAR(50) NOT NULL,
    file_name VARCHAR(255) NOT NULL,
    uploaded_at TIMESTAMPTZ NOT NULL,
    total_count INTEGER,
    success_count INTEGER,
    error_count INTEGER,
    error_detail TEXT,
    process_mode VARCHAR(30),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_upload_history PRIMARY KEY (upload_history_id),
    CONSTRAINT ck_upload_history_target_business CHECK (target_business IN ('PARTNER', 'PERSONNEL_RECORD', 'ANNUAL_LEAVE', 'PAYROLL', 'ASSET', 'ATTENDANCE', 'CARRYOVER', 'COMMUTE_RECORD', 'EDUCATION_ATTENDEE', 'DAILY_WORKER_PAYMENT')),
    CONSTRAINT ck_upload_history_process_mode CHECK (process_mode IN ('EXCLUDE_ERROR', 'CANCEL_ALL')),
    CONSTRAINT ck_upload_history_total_count_ge_0 CHECK (total_count >= 0),
    CONSTRAINT ck_upload_history_success_count_ge_0 CHECK (success_count >= 0),
    CONSTRAINT ck_upload_history_error_count_ge_0 CHECK (error_count >= 0)
);

COMMENT ON TABLE upload_history IS '엑셀 업로드 이력 - 한 행=엑셀 업로드 1회. 대상 업무, 처리 건수, 오류 내역, 업로더(임직원 필수).';

COMMENT ON COLUMN upload_history.upload_history_id IS '엑셀 업로드 이력 ID - 대리키';

COMMENT ON COLUMN upload_history.uploader_id IS '업로더 - 엑셀을 업로드한 임직원(업로드는 사람 수행, 필수)';

COMMENT ON COLUMN upload_history.target_business IS '업로드 대상 업무 - (가정) 관련 기능에서 확인된 대상 업무를 모은 추천 집합이며 대상 업무 추가 시 조정 필요(확인 필요)';

COMMENT ON COLUMN upload_history.file_name IS '파일명 - (가정) 업로드 원본 파일명. 파일 자체는 ECM 저장';

COMMENT ON COLUMN upload_history.uploaded_at IS '업로드 일시 - 업로드 수행 시각, INSERT 시 공급(가정)';

COMMENT ON COLUMN upload_history.total_count IS '전체 건수 - 저장 후 산출(검증 완료 후 채움)';

COMMENT ON COLUMN upload_history.success_count IS '정상 반영 건수 - 저장 후 산출';

COMMENT ON COLUMN upload_history.error_count IS '오류 건수 - 저장 후 산출. 오류 건은 반영하지 않음';

COMMENT ON COLUMN upload_history.error_detail IS '오류 내역 - 오류 건별 사유. 오류 없으면 생략. (확인 필요) 건별 개별 조회가 필요하면 별도 엔티티 필요';

COMMENT ON COLUMN upload_history.process_mode IS '오류 처리 방식 - (가정) 잠정 추천 EXCLUDE_ERROR(오류 건 제외 후 정상 반영). 최종 확정 전 (확인 필요)';

COMMENT ON COLUMN upload_history.created_at IS '생성 일시';

COMMENT ON COLUMN upload_history.updated_at IS '수정 일시';

CREATE TABLE change_history (
    change_history_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    changer_id BIGINT NOT NULL,
    target_type VARCHAR(100) NOT NULL,
    target_id BIGINT NOT NULL,
    change_type VARCHAR(50),
    changed_at TIMESTAMPTZ NOT NULL,
    change_content TEXT NOT NULL,
    change_reason VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_change_history PRIMARY KEY (change_history_id)
);

COMMENT ON TABLE change_history IS '변경 이력 - 한 행=업무 대상 변경 1건. 대상유형+대상ID(가정), 변경일시·수정자(임직원)·변경 내용. 승인 후 변경·마감 취소·설정 변경 이력 공통.';

COMMENT ON COLUMN change_history.change_history_id IS '변경 이력 ID - 대리키';

COMMENT ON COLUMN change_history.changer_id IS '수정자 - 변경을 수행한 임직원(필수)';

COMMENT ON COLUMN change_history.target_type IS '대상 유형 - (가정) 변경 대상 엔티티명/업무 유형. 대상이 다수 엔티티라 FK 불가, 허용값 전체 미확정이라 allowed_values 생략';

COMMENT ON COLUMN change_history.target_id IS '대상 ID - (가정) 대상 엔티티 PK. 다형 참조로 FK 아님';

COMMENT ON COLUMN change_history.change_type IS '변경 구분 - (가정) 승인 후 변경·마감 취소·설정 변경·일괄 변경 등 변경 사유 구분. 코드 체계 미확정(확인 필요)';

COMMENT ON COLUMN change_history.changed_at IS '변경 일시 - 변경 발생 시각(INSERT 시 공급, 감사 컬럼과 별도)';

COMMENT ON COLUMN change_history.change_content IS '변경 내용 - 변경 항목·전후 값 요약. 개인정보는 마스킹/암호화 필요(확인 필요)';

COMMENT ON COLUMN change_history.change_reason IS '변경 사유 - (가정) 조정·승인 취소 등의 사유, 선택';

COMMENT ON COLUMN change_history.created_at IS '생성 일시';

COMMENT ON COLUMN change_history.updated_at IS '수정 일시';

CREATE TABLE link_log (
    link_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requester_id BIGINT,
    link_target VARCHAR(50) NOT NULL,
    link_type VARCHAR(100),
    status VARCHAR(20) NOT NULL,
    requested_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ,
    failure_reason TEXT,
    request_summary VARCHAR(1000),
    processed_count INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_link_log PRIMARY KEY (link_log_id),
    CONSTRAINT ck_link_log_link_target CHECK (link_target IN ('E_NARA_DOUM', 'NTS_HOMETAX', 'NTS_EFILING', 'BANK_CMS', 'CARD_COMPANY', 'LEGACY_ERP', 'ASSET_INSPECTION', 'COMMUTE_SYSTEM', 'ECM')),
    CONSTRAINT ck_link_log_status CHECK (status IN ('REQUESTED', 'SUCCESS', 'FAILED')),
    CONSTRAINT ck_link_log_failure_reason_req CHECK (status NOT IN ('FAILED') OR failure_reason IS NOT NULL),
    CONSTRAINT ck_link_log_completed_at_req CHECK (status NOT IN ('SUCCESS', 'FAILED') OR completed_at IS NOT NULL),
    CONSTRAINT ck_link_log_processed_count_ge_0 CHECK (processed_count >= 0),
    CONSTRAINT ck_link_log_completed_at_ge_requested_at CHECK (completed_at >= requested_at)
);

COMMENT ON TABLE link_log IS '외부 연계 이력 - 한 행=외부 시스템 연계 처리 1건. 연계 대상, 상태, 실패 사유. 요청자는 선택(자동 실행 시 없음).';

COMMENT ON COLUMN link_log.link_log_id IS '외부 연계 이력 ID - 대리키';

COMMENT ON COLUMN link_log.requester_id IS '요청자 - 사람이 요청한 경우만 입력, 자동 실행 시 NULL. 사람 요청 시 필수 조건은 구조로 표현 불가(확인 필요)';

COMMENT ON COLUMN link_log.link_target IS '연계 대상 - (가정) 관련 기능에서 확인된 외부 시스템 집합';

COMMENT ON COLUMN link_log.link_type IS '연계 구분 - (가정) 수집·발행·신고·조회 등 연계 업무 구분. 값 체계 미확정';

COMMENT ON COLUMN link_log.status IS '연계 상태 - (가정) 연계 요청 시 REQUESTED로 시작, 완료 후 SUCCESS/FAILED. 비동기·분할 처리 반영';

COMMENT ON COLUMN link_log.requested_at IS '요청 일시 - 연계 시작 시각(INSERT 시 공급)';

COMMENT ON COLUMN link_log.completed_at IS '완료 일시 - 저장 후 처리 완료 시 채움';

COMMENT ON COLUMN link_log.failure_reason IS '실패 사유 - 실패 시 필수';

COMMENT ON COLUMN link_log.request_summary IS '요청 조건 - (가정) 연계 기간·조회 조건 요약';

COMMENT ON COLUMN link_log.processed_count IS '처리 건수 - 저장 후 산출';

COMMENT ON COLUMN link_log.created_at IS '생성 일시';

COMMENT ON COLUMN link_log.updated_at IS '수정 일시';

CREATE TABLE auto_journal_setting (
    auto_journal_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    evidence_type VARCHAR(50) NOT NULL,
    evidence_item_name VARCHAR(200) NOT NULL,
    collect_enabled BOOLEAN NOT NULL,
    auto_journal_enabled BOOLEAN NOT NULL,
    collect_condition VARCHAR(1000),
    journal_condition VARCHAR(1000),
    account_subject_id BIGINT NOT NULL,
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_auto_journal_setting PRIMARY KEY (auto_journal_setting_id),
    CONSTRAINT ck_auto_journal_setting_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT uq_auto_journal_setting_evidence_type_evidence_item_name UNIQUE (evidence_type, evidence_item_name)
);

COMMENT ON TABLE auto_journal_setting IS '자동전표 증빙설정 - 한 행=증빙유형·증빙항목 1건. 자료수집·자동분개 설정, 사용 여부. 분개 계정과목 참조.';

COMMENT ON COLUMN auto_journal_setting.auto_journal_setting_id IS '자동전표 증빙설정 ID - 대리키';

COMMENT ON COLUMN auto_journal_setting.evidence_type IS '증빙유형 - (가정) 세금계산서·카드·현금영수증·은행거래 등. 전체 목록 미확정이라 allowed_values 생략';

COMMENT ON COLUMN auto_journal_setting.evidence_item_name IS '증빙항목명';

COMMENT ON COLUMN auto_journal_setting.collect_enabled IS '자료수집 사용 여부 - (가정) 자료수집 설정, 기본 INSERT 시 공급';

COMMENT ON COLUMN auto_journal_setting.auto_journal_enabled IS '자동분개 사용 여부 - (가정) 자동분개 처리 설정, INSERT 시 공급';

COMMENT ON COLUMN auto_journal_setting.collect_condition IS '자료수집 조건 - (가정) 수집 조건 자유 입력';

COMMENT ON COLUMN auto_journal_setting.journal_condition IS '자동분개 조건 - (가정) 분개 일치 기준';

COMMENT ON COLUMN auto_journal_setting.account_subject_id IS '분개 계정과목 - (가정) 분개 시 사용할 계정과목, 필수';

COMMENT ON COLUMN auto_journal_setting.use_status IS '사용 여부 - (가정) 공통 사용 여부 도메인. 신규 등록 시 사용으로 시작. 미사용은 수집·분개 제외';

COMMENT ON COLUMN auto_journal_setting.created_at IS '생성 일시';

COMMENT ON COLUMN auto_journal_setting.updated_at IS '수정 일시';

CREATE TABLE tax_invoice (
    tax_invoice_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    partner_id BIGINT NOT NULL,
    expense_resolution_id BIGINT,
    journal_entry_id BIGINT,
    direction VARCHAR(20) NOT NULL,
    tax_type VARCHAR(20) NOT NULL,
    issue_date DATE NOT NULL,
    supply_amount NUMERIC(18,2) NOT NULL,
    tax_amount NUMERIC(18,2) NOT NULL,
    issue_status VARCHAR(20) NOT NULL,
    journal_status VARCHAR(20) NOT NULL,
    approval_number VARCHAR(50),
    item_description VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_tax_invoice PRIMARY KEY (tax_invoice_id),
    CONSTRAINT ck_tax_invoice_direction CHECK (direction IN ('ISSUE', 'RECEIVE')),
    CONSTRAINT ck_tax_invoice_tax_type CHECK (tax_type IN ('TAXABLE', 'EXEMPT')),
    CONSTRAINT ck_tax_invoice_issue_status CHECK (issue_status IN ('NOT_ISSUED', 'ISSUED')),
    CONSTRAINT ck_tax_invoice_journal_status CHECK (journal_status IN ('UNPROCESSED', 'PROCESSED')),
    CONSTRAINT uq_tax_invoice_approval_number UNIQUE (approval_number),
    CONSTRAINT ck_tax_invoice_journal_entry_id_req CHECK (journal_status NOT IN ('PROCESSED') OR journal_entry_id IS NOT NULL),
    CONSTRAINT ck_tax_invoice_supply_amount_ge_0 CHECK (supply_amount >= 0),
    CONSTRAINT ck_tax_invoice_tax_amount_ge_0 CHECK (tax_amount >= 0)
);

COMMENT ON TABLE tax_invoice IS '전자세금계산서 - 한 행=세금계산서 1건. 발행/수취, 과세·면세, 공급가액·세액, 발행 여부, 전표처리 상태. 거래처 필수, 결의서·전표 선택(중복 처리 불가).';

COMMENT ON COLUMN tax_invoice.tax_invoice_id IS '전자세금계산서 ID - 대리키';

COMMENT ON COLUMN tax_invoice.partner_id IS '거래처 - 거래처 필수';

COMMENT ON COLUMN tax_invoice.expense_resolution_id IS '결의서 - 결의서 작성 후 연결. 중복 작성 불가이므로 unique';

COMMENT ON COLUMN tax_invoice.journal_entry_id IS '전표 - 전표처리 후 연결. 중복 처리 불가이므로 unique';

COMMENT ON COLUMN tax_invoice.direction IS '발행/수취 구분 - (가정) 발행/수취';

COMMENT ON COLUMN tax_invoice.tax_type IS '과세·면세 구분 - (가정) 과세/면세';

COMMENT ON COLUMN tax_invoice.issue_date IS '작성일자';

COMMENT ON COLUMN tax_invoice.supply_amount IS '공급가액 - (가정) 입력 필수';

COMMENT ON COLUMN tax_invoice.tax_amount IS '세액 - (가정) 입력 필수, 면세는 0';

COMMENT ON COLUMN tax_invoice.issue_status IS '발행 여부 - (가정) 발행 요청 전 NOT_ISSUED. 수취 건은 수집 시 ISSUED. 초기값: 발행 건→NOT_ISSUED, 수취 건→ISSUED. 연계 실패 시 ISSUED로 처리하지 않음';

COMMENT ON COLUMN tax_invoice.journal_status IS '전표처리 상태 - (가정) 미처리로 시작, 전표처리 완료 시 PROCESSED. 완료 건은 발행 여부 변경 불가';

COMMENT ON COLUMN tax_invoice.approval_number IS '국세청 승인번호 - (가정) 발행·수집 후 부여되는 승인번호, 선택';

COMMENT ON COLUMN tax_invoice.item_description IS '품목 - (가정) 품목 요약. 다수 품목 개별 관리 필요 시 별도 엔티티 (확인 필요)';

COMMENT ON COLUMN tax_invoice.created_at IS '생성 일시';

COMMENT ON COLUMN tax_invoice.updated_at IS '수정 일시';

CREATE TABLE bank_transaction (
    bank_transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    partner_account_id BIGINT NOT NULL,
    journal_entry_id BIGINT,
    transaction_at TIMESTAMPTZ NOT NULL,
    deposit_amount NUMERIC(18,2),
    withdrawal_amount NUMERIC(18,2),
    balance_amount NUMERIC(18,2),
    summary VARCHAR(500),
    counterparty_name VARCHAR(200),
    external_transaction_no VARCHAR(100),
    is_exception BOOLEAN NOT NULL,
    is_journalized BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_bank_transaction PRIMARY KEY (bank_transaction_id),
    CONSTRAINT uq_bank_transaction_partner_account_id_external_transaction_no UNIQUE (partner_account_id, external_transaction_no),
    CONSTRAINT ck_bank_transaction_deposit_amount_ge_0 CHECK (deposit_amount >= 0),
    CONSTRAINT ck_bank_transaction_withdrawal_amount_ge_0 CHECK (withdrawal_amount >= 0)
);

COMMENT ON TABLE bank_transaction IS '은행계좌 거래내역 - 한 행=계좌 거래내역 1건. 예외 거래 여부, 전표처리 여부. 계좌 필수, 전표 선택.';

COMMENT ON COLUMN bank_transaction.bank_transaction_id IS '은행계좌 거래내역 ID - 대리키';

COMMENT ON COLUMN bank_transaction.partner_account_id IS '거래처 계좌 ID - 계좌 필수. 수집 시 계좌 기준으로 적재';

COMMENT ON COLUMN bank_transaction.journal_entry_id IS '전표 ID - 전표 처리 후 연결(저장 후 산출). 전표 처리 전에는 NULL';

COMMENT ON COLUMN bank_transaction.transaction_at IS '거래일시 - 금융기관 API 수집값 (가정: 수집 시 항상 제공, 시간대 정책 확인 필요)';

COMMENT ON COLUMN bank_transaction.deposit_amount IS '입금액 - (가정) 입금 거래에서만 값. 정밀도 18,2 (확인 필요)';

COMMENT ON COLUMN bank_transaction.withdrawal_amount IS '출금액 - (가정) 출금 거래에서만 값. 정밀도 18,2 (확인 필요)';

COMMENT ON COLUMN bank_transaction.balance_amount IS '거래 후 잔액 - 금융기관 API 제공 시에만 저장 (가정)';

COMMENT ON COLUMN bank_transaction.summary IS '적요 - (가정) 길이 500';

COMMENT ON COLUMN bank_transaction.counterparty_name IS '거래상대 표시명 - (가정) 금융기관 제공 상대방 표기. 길이 200';

COMMENT ON COLUMN bank_transaction.external_transaction_no IS '외부 거래 식별번호 - (가정) 금융기관 API 거래 고유번호. 중복 수집 방지용. 제공 여부 확인 필요';

COMMENT ON COLUMN bank_transaction.is_exception IS '예외 거래 여부 - 자동분개 기준 불일치 시 true. 수집·분류 시점에 공급 (가정: 기본 false)';

COMMENT ON COLUMN bank_transaction.is_journalized IS '전표처리 여부 - 전표 처리 완료 시 true. 수집 시 false로 공급 (가정). 이미 처리된 건은 중복 전표 처리 불가';

COMMENT ON COLUMN bank_transaction.created_at IS '생성 일시';

COMMENT ON COLUMN bank_transaction.updated_at IS '수정 일시';

CREATE TABLE card_approval (
    card_approval_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    credit_card_id BIGINT NOT NULL,
    expense_resolution_id BIGINT,
    journal_entry_id BIGINT,
    approval_no VARCHAR(50) NOT NULL,
    approved_at TIMESTAMPTZ NOT NULL,
    approval_amount NUMERIC(18,2) NOT NULL,
    vat_amount NUMERIC(18,2),
    merchant_name VARCHAR(200),
    merchant_business_no VARCHAR(10),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_card_approval PRIMARY KEY (card_approval_id),
    CONSTRAINT uq_card_approval_credit_card_id_approval_no_approved_at UNIQUE (credit_card_id, approval_no, approved_at)
);

COMMENT ON TABLE card_approval IS '신용카드 승인내역 - 한 행=카드 승인내역 1건. 카드 필수, 결의서·전표 선택(중복 작성 불가).';

COMMENT ON COLUMN card_approval.card_approval_id IS '신용카드 승인내역 ID - 대리키';

COMMENT ON COLUMN card_approval.credit_card_id IS '신용카드 ID - 카드 필수';

COMMENT ON COLUMN card_approval.expense_resolution_id IS '결의서 ID - 결의서 작성 후 연결(저장 후 산출). 중복 작성 불가: 1:1 (확인 필요: 한 결의서에 여러 승인내역 가능 여부)';

COMMENT ON COLUMN card_approval.journal_entry_id IS '전표 ID - 전표 처리 후 연결(저장 후 산출)';

COMMENT ON COLUMN card_approval.approval_no IS '승인번호 - (가정) 카드사 API 제공 승인번호. 길이 50';

COMMENT ON COLUMN card_approval.approved_at IS '승인일시 - 카드사 API 수집값';

COMMENT ON COLUMN card_approval.approval_amount IS '승인금액 - 카드사 API 수집값. 정밀도 18,2 (확인 필요)';

COMMENT ON COLUMN card_approval.vat_amount IS '부가세액 - 카드사 제공 시에만 저장 (가정)';

COMMENT ON COLUMN card_approval.merchant_name IS '가맹점명 - (가정) 길이 200';

COMMENT ON COLUMN card_approval.merchant_business_no IS '가맹점 사업자번호 - 선행 0 보존. 하이픈 제외 10자리 (가정)';

COMMENT ON COLUMN card_approval.created_at IS '생성 일시';

COMMENT ON COLUMN card_approval.updated_at IS '수정 일시';

CREATE TABLE cash_receipt (
    cash_receipt_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    expense_resolution_id BIGINT,
    journal_entry_id BIGINT,
    approval_no VARCHAR(50) NOT NULL,
    issued_at TIMESTAMPTZ NOT NULL,
    supply_amount NUMERIC(18,2),
    vat_amount NUMERIC(18,2),
    total_amount NUMERIC(18,2) NOT NULL,
    merchant_name VARCHAR(200),
    merchant_business_no VARCHAR(10),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_cash_receipt PRIMARY KEY (cash_receipt_id),
    CONSTRAINT uq_cash_receipt_approval_no_issued_at UNIQUE (approval_no, issued_at)
);

COMMENT ON TABLE cash_receipt IS '현금영수증 - 한 행=현금영수증 1건. 결의서·전표 선택(중복 작성 불가).';

COMMENT ON COLUMN cash_receipt.cash_receipt_id IS '현금영수증 ID - 대리키';

COMMENT ON COLUMN cash_receipt.expense_resolution_id IS '결의서 ID - 결의서 작성 후 연결(저장 후 산출). 중복 작성 불가';

COMMENT ON COLUMN cash_receipt.journal_entry_id IS '전표 ID - 전표 처리 후 연결(저장 후 산출)';

COMMENT ON COLUMN cash_receipt.approval_no IS '승인번호 - (가정) 국세청 연계 승인번호. 길이 50';

COMMENT ON COLUMN cash_receipt.issued_at IS '발행일시 - 연계 수집값';

COMMENT ON COLUMN cash_receipt.supply_amount IS '공급가액 - 연계 제공 시에만 저장 (가정)';

COMMENT ON COLUMN cash_receipt.vat_amount IS '부가세액 - 연계 제공 시에만 저장 (가정)';

COMMENT ON COLUMN cash_receipt.total_amount IS '합계금액 - 연계 수집값(삽입 전 공급). 정밀도 18,2 (확인 필요)';

COMMENT ON COLUMN cash_receipt.merchant_name IS '가맹점명 - (가정) 길이 200';

COMMENT ON COLUMN cash_receipt.merchant_business_no IS '가맹점 사업자번호 - 선행 0 보존 (가정)';

COMMENT ON COLUMN cash_receipt.created_at IS '생성 일시';

COMMENT ON COLUMN cash_receipt.updated_at IS '수정 일시';

CREATE TABLE journal_settlement (
    journal_settlement_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    receivable_line_id BIGINT NOT NULL,
    payable_line_id BIGINT NOT NULL,
    partner_id BIGINT NOT NULL,
    settled_by_id BIGINT NOT NULL,
    settled_at TIMESTAMPTZ NOT NULL,
    settlement_amount NUMERIC(18,2) NOT NULL,
    memo VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_journal_settlement PRIMARY KEY (journal_settlement_id),
    CONSTRAINT ck_journal_settlement_settlement_amount_gt_0 CHECK (settlement_amount > 0),
    CONSTRAINT ck_journal_settlement_payable_line_id_ne_receivable_line_id CHECK (payable_line_id <> receivable_line_id)
);

COMMENT ON TABLE journal_settlement IS '반제·상계 처리 - 한 행=채권 분개라인과 채무 분개라인 간 반제·상계 1건. 동일 거래처만, 금액<=잔액, 처리자·일시.';

COMMENT ON COLUMN journal_settlement.journal_settlement_id IS '반제·상계 처리 ID - 대리키';

COMMENT ON COLUMN journal_settlement.receivable_line_id IS '채권 분개라인 ID - 반제 대상 채권 분개라인';

COMMENT ON COLUMN journal_settlement.payable_line_id IS '채무 분개라인 ID - 반제 대상 채무 분개라인. 채권 라인과 다른 라인';

COMMENT ON COLUMN journal_settlement.partner_id IS '거래처 ID - 동일 거래처만 가능 (양쪽 라인의 거래처와 일치 여부는 CHECK로 표현 불가: 확인 필요)';

COMMENT ON COLUMN journal_settlement.settled_by_id IS '처리자 ID - 처리 요청 시 공급되는 계정 FK (가정)';

COMMENT ON COLUMN journal_settlement.settled_at IS '처리일시 - 처리 시점에 기록 (삽입 시 공급, 가정)';

COMMENT ON COLUMN journal_settlement.settlement_amount IS '반제·상계 금액 - 잔액 이하여야 함(잔액 대비 검증은 다른 행 집계 필요: 확인 필요). 정밀도 18,2 (확인 필요)';

COMMENT ON COLUMN journal_settlement.memo IS '처리 내용 - (가정) 상계 처리 이력 내용. 길이 500';

COMMENT ON COLUMN journal_settlement.created_at IS '생성 일시';

COMMENT ON COLUMN journal_settlement.updated_at IS '수정 일시';

CREATE TABLE management_item (
    management_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code VARCHAR(50) NOT NULL,
    name VARCHAR(100) NOT NULL,
    value_type VARCHAR(20),
    use_status VARCHAR(10) NOT NULL,
    description VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_management_item PRIMARY KEY (management_item_id),
    CONSTRAINT uq_management_item_code UNIQUE (code),
    CONSTRAINT ck_management_item_value_type CHECK (value_type IN ('TEXT', 'NUMBER', 'DATE', 'CODE')),
    CONSTRAINT ck_management_item_use_status CHECK (use_status IN ('사용', '미사용'))
);

COMMENT ON TABLE management_item IS '관리항목 - 한 행=관리항목 정의 1개. 관리자가 관리하는 코드.';

COMMENT ON COLUMN management_item.management_item_id IS '관리항목 ID - 대리키';

COMMENT ON COLUMN management_item.code IS '관리항목 코드 - (가정) 관리자가 부여하는 코드. 길이 50';

COMMENT ON COLUMN management_item.name IS '관리항목명 - (가정) 길이 100';

COMMENT ON COLUMN management_item.value_type IS '값 유형 - (가정) 분개라인 관리항목값의 입력 유형. 확정 목록 아님, 확인 필요';

COMMENT ON COLUMN management_item.use_status IS '사용 여부 - 공통 결정 ''사용 여부'' 도메인. 초기값: 사용 (가정)';

COMMENT ON COLUMN management_item.description IS '설명 - (가정) 길이 500';

COMMENT ON COLUMN management_item.created_at IS '생성 일시';

COMMENT ON COLUMN management_item.updated_at IS '수정 일시';

CREATE TABLE journal_line_management_value (
    journal_line_management_value_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    journal_entry_line_id BIGINT NOT NULL,
    management_item_id BIGINT NOT NULL,
    item_value VARCHAR(200),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_journal_line_management_value PRIMARY KEY (journal_line_management_value_id),
    CONSTRAINT uq_journal_line_management_value_journal_entry_line_id_43f1ed22 UNIQUE (journal_entry_line_id, management_item_id)
);

COMMENT ON TABLE journal_line_management_value IS '분개라인 관리항목값 - 한 행=분개라인·관리항목별 값 1건(N:M 해소).';

COMMENT ON COLUMN journal_line_management_value.journal_line_management_value_id IS '분개라인 관리항목값 ID - 대리키';

COMMENT ON COLUMN journal_line_management_value.journal_entry_line_id IS '전표 분개 라인';

COMMENT ON COLUMN journal_line_management_value.management_item_id IS '관리항목';

COMMENT ON COLUMN journal_line_management_value.item_value IS '관리항목 값 - (가정) 관리항목 값은 문자열로 저장하며 길이는 가정이다. 값이 없는 행은 허용한다. (확인 필요) 관리항목별 값 유형(코드·금액·날짜 등)과 참조 대상은 명세에 없다.';

COMMENT ON COLUMN journal_line_management_value.created_at IS '생성 일시';

COMMENT ON COLUMN journal_line_management_value.updated_at IS '수정 일시';

CREATE TABLE fund_subject (
    fund_subject_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    subject_type VARCHAR(20) NOT NULL,
    use_status VARCHAR(10) NOT NULL,
    account_subject_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fund_subject PRIMARY KEY (fund_subject_id),
    CONSTRAINT ck_fund_subject_subject_type CHECK (subject_type IN ('INFLOW', 'OUTFLOW')),
    CONSTRAINT ck_fund_subject_use_status CHECK (use_status IN ('사용', '미사용'))
);

COMMENT ON TABLE fund_subject IS '자금과목 - 한 행=자금과목 1개. 구분, 사용 여부(사용된 과목은 삭제 불가), 연결 계정과목.';

COMMENT ON COLUMN fund_subject.fund_subject_id IS '자금과목 ID - 대리키';

COMMENT ON COLUMN fund_subject.name IS '자금과목명 - (가정) 길이 100';

COMMENT ON COLUMN fund_subject.subject_type IS '자금과목 구분 - (가정) 자금과목 구분의 전체 값이 명세에 없어 수입/지출 최소 집합을 추천한다. (확인 필요) 실제 구분 체계';

COMMENT ON COLUMN fund_subject.use_status IS '사용 여부 - 공통 결정 ''사용 여부'' 도메인. 초기값은 사용(가정). 사용된 과목은 삭제하지 않고 미사용으로만 전환한다.';

COMMENT ON COLUMN fund_subject.account_subject_id IS '연결 계정과목 - (가정) 연결은 선택값으로 둔다.';

COMMENT ON COLUMN fund_subject.created_at IS '생성 일시';

COMMENT ON COLUMN fund_subject.updated_at IS '수정 일시';

CREATE TABLE fund_pl_form_item (
    fund_pl_form_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fund_subject_id BIGINT NOT NULL,
    sort_order INTEGER NOT NULL,
    item_name VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fund_pl_form_item PRIMARY KEY (fund_pl_form_item_id),
    CONSTRAINT ck_fund_pl_form_item_sort_order_gt_0 CHECK (sort_order > 0)
);

COMMENT ON TABLE fund_pl_form_item IS '자금 손익 양식 항목 - 한 행=자금 손익 양식 항목 1개(순서, 자금과목 구성).';

COMMENT ON COLUMN fund_pl_form_item.fund_pl_form_item_id IS '자금 손익 양식 항목 ID - 대리키';

COMMENT ON COLUMN fund_pl_form_item.fund_subject_id IS '자금과목';

COMMENT ON COLUMN fund_pl_form_item.sort_order IS '순서 - 양식 내 표시 순서';

COMMENT ON COLUMN fund_pl_form_item.item_name IS '항목명 - (가정) 양식 항목 표시명. 미입력 시 자금과목명을 사용한다.';

COMMENT ON COLUMN fund_pl_form_item.created_at IS '생성 일시';

COMMENT ON COLUMN fund_pl_form_item.updated_at IS '수정 일시';

CREATE TABLE fixed_fund (
    fixed_fund_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fund_subject_id BIGINT NOT NULL,
    partner_id BIGINT,
    project_id BIGINT,
    budget_account_id BIGINT,
    amount NUMERIC(18,2) NOT NULL,
    cycle VARCHAR(20) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fixed_fund PRIMARY KEY (fixed_fund_id),
    CONSTRAINT ck_fixed_fund_cycle CHECK (cycle IN ('월', '분기', '연')),
    CONSTRAINT ck_fixed_fund_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT ck_fixed_fund_amount_gt_0 CHECK (amount > 0),
    CONSTRAINT ck_fixed_fund_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE fixed_fund IS '고정자금 - 한 행=고정자금 1건. 금액, 발생 주기, 적용기간(종료>=시작), 사용 여부.';

COMMENT ON COLUMN fixed_fund.fixed_fund_id IS '고정자금 ID - 대리키';

COMMENT ON COLUMN fixed_fund.fund_subject_id IS '자금과목';

COMMENT ON COLUMN fixed_fund.partner_id IS '거래처 - (가정) 거래처 없는 고정자금 허용';

COMMENT ON COLUMN fixed_fund.project_id IS '프로젝트 - (가정) 선택값';

COMMENT ON COLUMN fixed_fund.budget_account_id IS '예산과목 - (가정) 선택값';

COMMENT ON COLUMN fixed_fund.amount IS '금액';

COMMENT ON COLUMN fixed_fund.cycle IS '발생 주기 - (가정) 예산 통제 주기 값을 재사용. (확인 필요) 공통 도메인 조정: 일·주 등 다른 주기가 필요하면 확장';

COMMENT ON COLUMN fixed_fund.start_date IS '적용 시작일';

COMMENT ON COLUMN fixed_fund.end_date IS '적용 종료일 - (가정) 종료일 미정 허용';

COMMENT ON COLUMN fixed_fund.use_status IS '사용 여부 - 미사용 고정자금은 계획에 반영하지 않는다. 초기값은 사용(가정).';

COMMENT ON COLUMN fixed_fund.created_at IS '생성 일시';

COMMENT ON COLUMN fixed_fund.updated_at IS '수정 일시';

CREATE TABLE fund_plan (
    fund_plan_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fund_subject_id BIGINT NOT NULL,
    plan_start_date DATE NOT NULL,
    plan_end_date DATE NOT NULL,
    income_amount NUMERIC(18,2),
    expense_amount NUMERIC(18,2),
    remark TEXT,
    closing_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fund_plan PRIMARY KEY (fund_plan_id),
    CONSTRAINT ck_fund_plan_closing_status CHECK (closing_status IN ('마감 취소', '마감')),
    CONSTRAINT uq_fund_plan_fund_subject_id_plan_start_date_plan_end_date UNIQUE (fund_subject_id, plan_start_date, plan_end_date),
    CONSTRAINT ck_fund_plan_plan_end_date_ge_plan_start_date CHECK (plan_end_date >= plan_start_date),
    CONSTRAINT ck_fund_plan_income_amount_ge_0 CHECK (income_amount >= 0),
    CONSTRAINT ck_fund_plan_expense_amount_ge_0 CHECK (expense_amount >= 0)
);

COMMENT ON TABLE fund_plan IS '자금수지계획 - 한 행=계획기간·자금과목별 수입/지출 계획 1건. 마감 후 수정 불가.';

COMMENT ON COLUMN fund_plan.fund_plan_id IS '자금수지계획 ID - 대리키';

COMMENT ON COLUMN fund_plan.fund_subject_id IS '자금과목';

COMMENT ON COLUMN fund_plan.plan_start_date IS '계획 시작일 - (가정) 계획 기간 시작';

COMMENT ON COLUMN fund_plan.plan_end_date IS '계획 종료일 - (가정) 계획 기간 종료';

COMMENT ON COLUMN fund_plan.income_amount IS '수입 계획 금액 - (가정) 지출 전용 과목은 NULL 허용';

COMMENT ON COLUMN fund_plan.expense_amount IS '지출 계획 금액 - (가정) 수입 전용 과목은 NULL 허용';

COMMENT ON COLUMN fund_plan.remark IS '비고';

COMMENT ON COLUMN fund_plan.closing_status IS '마감 상태 - (가정) 마감 후 수정 불가. 승인 처리 상태 도메인의 마감/마감 취소 값을 사용하며 최초 상태는 마감 취소(미마감 의미)로 둔다. (확인 필요) 공통 도메인 조정: 미마감 상태를 별도 코드로 둘지 확인. 마감 중 수정 금지는 애플리케이션에서 검증한다.';

COMMENT ON COLUMN fund_plan.created_at IS '생성 일시';

COMMENT ON COLUMN fund_plan.updated_at IS '수정 일시';

CREATE TABLE financial_instrument (
    financial_instrument_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    partner_id BIGINT,
    instrument_type VARCHAR(20) NOT NULL,
    instrument_name VARCHAR(200) NOT NULL,
    instrument_number VARCHAR(50),
    currency_code VARCHAR(3),
    face_amount NUMERIC(18,2),
    issue_date DATE,
    maturity_date DATE,
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_financial_instrument PRIMARY KEY (financial_instrument_id),
    CONSTRAINT ck_financial_instrument_instrument_type CHECK (instrument_type IN ('BILL', 'DEPOSIT', 'SAVINGS', 'SECURITIES', 'FOREIGN_CURRENCY')),
    CONSTRAINT ck_financial_instrument_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT ck_financial_instrument_maturity_date_ge_issue_date CHECK (maturity_date >= issue_date),
    CONSTRAINT ck_financial_instrument_face_amount_ge_0 CHECK (face_amount >= 0)
);

COMMENT ON TABLE financial_instrument IS '금융자산(어음·예적금·유가증권·외화) - 한 행=어음/예·적금/유가증권/외화 1건. 유형 속성(가정), 금융거래처 선택.';

COMMENT ON COLUMN financial_instrument.financial_instrument_id IS '금융자산(어음·예적금·유가증권·외화) ID - 대리키';

COMMENT ON COLUMN financial_instrument.partner_id IS '금융거래처 - 금융거래처 선택. 선택값이므로 NULL 허용(가정)';

COMMENT ON COLUMN financial_instrument.instrument_type IS '금융자산 유형 - (가정) 어음/예금/적금/유가증권/외화. 명세에 유형 전체 코드가 없어 추천안';

COMMENT ON COLUMN financial_instrument.instrument_name IS '금융자산명 - (가정) 길이 200';

COMMENT ON COLUMN financial_instrument.instrument_number IS '식별번호 - 어음번호·계좌번호·증권번호 등 식별용 번호(선행 0 보존). (가정) 길이 50. 계좌번호는 개인정보 암호화 대상 여부 확인 필요(확인 필요)';

COMMENT ON COLUMN financial_instrument.currency_code IS '통화코드 - 외화 등에서 사용. (가정) ISO 4217 3자리';

COMMENT ON COLUMN financial_instrument.face_amount IS '액면·잔액 - (가정) 액면금액 또는 잔액. 정밀도 18,2(확인 필요)';

COMMENT ON COLUMN financial_instrument.issue_date IS '발행·개설일';

COMMENT ON COLUMN financial_instrument.maturity_date IS '만기일';

COMMENT ON COLUMN financial_instrument.use_status IS '사용 여부 - 공통 결정 사용 여부 도메인. 초기값(가정): 등록 시 사용';

COMMENT ON COLUMN financial_instrument.created_at IS '생성 일시';

COMMENT ON COLUMN financial_instrument.updated_at IS '수정 일시';

CREATE TABLE loan (
    loan_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    partner_id BIGINT NOT NULL,
    account_subject_id BIGINT NOT NULL,
    loan_type VARCHAR(20) NOT NULL,
    principal_amount NUMERIC(18,2) NOT NULL,
    interest_rate NUMERIC(18,2),
    loan_date DATE NOT NULL,
    maturity_date DATE,
    voucher_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_loan PRIMARY KEY (loan_id),
    CONSTRAINT ck_loan_loan_type CHECK (loan_type IN ('BORROWING', 'LENDING')),
    CONSTRAINT ck_loan_voucher_status CHECK (voucher_status IN ('미처리', '처리완료')),
    CONSTRAINT ck_loan_principal_amount_gt_0 CHECK (principal_amount > 0),
    CONSTRAINT ck_loan_maturity_date_ge_loan_date CHECK (maturity_date >= loan_date)
);

COMMENT ON TABLE loan IS '차입금·대여금 - 한 행=차입/대여 1건. 구분, 거래처 필수, 계정과목, 전표처리 상태.';

COMMENT ON COLUMN loan.loan_id IS '차입금·대여금 ID - 대리키';

COMMENT ON COLUMN loan.partner_id IS '거래처 - 거래처 필수';

COMMENT ON COLUMN loan.account_subject_id IS '계정과목 - (가정) 등록 시 지정';

COMMENT ON COLUMN loan.loan_type IS '구분 - 차입금/대여금 구분. (가정) 두 값';

COMMENT ON COLUMN loan.principal_amount IS '원금 - (가정) 등록 시 입력. 정밀도 18,2(확인 필요)';

COMMENT ON COLUMN loan.interest_rate IS '이율 - (가정) 연이율 %';

COMMENT ON COLUMN loan.loan_date IS '거래일 - (가정) 등록 시 입력';

COMMENT ON COLUMN loan.maturity_date IS '만기일';

COMMENT ON COLUMN loan.voucher_status IS '전표처리 상태 - (가정) 등록 시 미처리, 전표처리 후 처리완료. 이미 처리된 건은 중복 전표처리 불가(여러 행 규칙은 확인 필요)';

COMMENT ON COLUMN loan.created_at IS '생성 일시';

COMMENT ON COLUMN loan.updated_at IS '수정 일시';

CREATE TABLE loan_transaction (
    loan_transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    loan_id BIGINT NOT NULL,
    journal_entry_id BIGINT,
    transaction_type VARCHAR(20) NOT NULL,
    transaction_date DATE NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    balance_after NUMERIC(18,2),
    memo VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_loan_transaction PRIMARY KEY (loan_transaction_id),
    CONSTRAINT ck_loan_transaction_transaction_type CHECK (transaction_type IN ('OCCURRENCE', 'REPAYMENT', 'INTEREST')),
    CONSTRAINT ck_loan_transaction_amount_gt_0 CHECK (amount > 0)
);

COMMENT ON TABLE loan_transaction IS '차입금·대여금 원장 - 한 행=차입금·대여금의 거래(원장) 1건. 전표 선택.';

COMMENT ON COLUMN loan_transaction.loan_transaction_id IS '차입금·대여금 원장 ID - 대리키';

COMMENT ON COLUMN loan_transaction.loan_id IS '차입금·대여금';

COMMENT ON COLUMN loan_transaction.journal_entry_id IS '전표 - 전표 선택. 전표처리 전 거래는 NULL';

COMMENT ON COLUMN loan_transaction.transaction_type IS '거래 유형 - (가정) 발생/상환/이자';

COMMENT ON COLUMN loan_transaction.transaction_date IS '거래일';

COMMENT ON COLUMN loan_transaction.amount IS '거래금액 - 정밀도 18,2(확인 필요)';

COMMENT ON COLUMN loan_transaction.balance_after IS '거래 후 잔액 - 저장 후 산출';

COMMENT ON COLUMN loan_transaction.memo IS '적요 - (가정) 길이 500';

COMMENT ON COLUMN loan_transaction.created_at IS '생성 일시';

COMMENT ON COLUMN loan_transaction.updated_at IS '수정 일시';

CREATE TABLE closing_data (
    closing_data_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    accounting_unit_id BIGINT NOT NULL,
    account_subject_id BIGINT NOT NULL,
    project_id BIGINT,
    department_id BIGINT,
    closing_period VARCHAR(7) NOT NULL,
    closing_amount NUMERIC(18,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_closing_data PRIMARY KEY (closing_data_id),
    CONSTRAINT uq_closing_data_accounting_unit_id_account_subject_id__ce099082 UNIQUE (accounting_unit_id, account_subject_id, project_id, department_id, closing_period)
);

COMMENT ON TABLE closing_data IS '결산자료 - 한 행=결산기간·회계단위·계정과목(·프로젝트·부서)별 결산금액 1건. 마감 후 수정 불가.';

COMMENT ON COLUMN closing_data.closing_data_id IS '결산자료 ID - 대리키';

COMMENT ON COLUMN closing_data.accounting_unit_id IS '회계단위';

COMMENT ON COLUMN closing_data.account_subject_id IS '계정과목';

COMMENT ON COLUMN closing_data.project_id IS '프로젝트';

COMMENT ON COLUMN closing_data.department_id IS '부서';

COMMENT ON COLUMN closing_data.closing_period IS '결산 기간 - (가정) YYYY-MM 형식. 기간 표현 방식 확인 필요';

COMMENT ON COLUMN closing_data.closing_amount IS '결산 금액 - 필수 입력값. 정밀도 18,2(확인 필요). 마감된 기간 수정 불가는 다른 테이블 규칙이라 (확인 필요)';

COMMENT ON COLUMN closing_data.created_at IS '생성 일시';

COMMENT ON COLUMN closing_data.updated_at IS '수정 일시';

CREATE TABLE allocation_rule (
    allocation_rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id BIGINT,
    department_id BIGINT,
    rule_name VARCHAR(200) NOT NULL,
    allocation_method VARCHAR(20) NOT NULL,
    allocation_ratio NUMERIC(18,2),
    allocation_amount NUMERIC(18,2),
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_allocation_rule PRIMARY KEY (allocation_rule_id),
    CONSTRAINT ck_allocation_rule_allocation_method CHECK (allocation_method IN ('RATIO', 'FIXED_AMOUNT')),
    CONSTRAINT ck_allocation_rule_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT ck_allocation_rule_allocation_ratio_req CHECK (allocation_method NOT IN ('RATIO') OR allocation_ratio IS NOT NULL),
    CONSTRAINT ck_allocation_rule_allocation_amount_req CHECK (allocation_method NOT IN ('FIXED_AMOUNT') OR allocation_amount IS NOT NULL),
    CONSTRAINT ck_allocation_rule_allocation_ratio_gt_0 CHECK (allocation_ratio > 0),
    CONSTRAINT ck_allocation_rule_allocation_ratio_le_100 CHECK (allocation_ratio <= 100)
);

COMMENT ON TABLE allocation_rule IS '안분 설정 - 한 행=손익 안분 기준 1건(비율·방식, 가정).';

COMMENT ON COLUMN allocation_rule.allocation_rule_id IS '안분 설정 ID - 대리키';

COMMENT ON COLUMN allocation_rule.project_id IS '프로젝트 - (가정) 안분 대상 프로젝트, 선택';

COMMENT ON COLUMN allocation_rule.department_id IS '부서 - (가정) 안분 대상 부서, 선택';

COMMENT ON COLUMN allocation_rule.rule_name IS '안분 기준명 - (가정) 길이 200';

COMMENT ON COLUMN allocation_rule.allocation_method IS '안분 방식 - (가정) 비율/정액. 원문에 방식 목록이 없어 추천안';

COMMENT ON COLUMN allocation_rule.allocation_ratio IS '안분 비율 - 방식이 RATIO일 때 필요. 0 초과 100 이하 %';

COMMENT ON COLUMN allocation_rule.allocation_amount IS '안분 금액 - 방식이 FIXED_AMOUNT일 때 필요';

COMMENT ON COLUMN allocation_rule.use_status IS '사용 여부 - 공통 결정 사용 여부 도메인. 초기값(가정): 등록 시 사용';

COMMENT ON COLUMN allocation_rule.created_at IS '생성 일시';

COMMENT ON COLUMN allocation_rule.updated_at IS '수정 일시';

CREATE TABLE vat_form (
    vat_form_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    tax_period_start DATE NOT NULL,
    tax_period_end DATE NOT NULL,
    form_type VARCHAR(30) NOT NULL,
    form_content TEXT,
    is_closed BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_vat_form PRIMARY KEY (vat_form_id),
    CONSTRAINT ck_vat_form_form_type CHECK (form_type IN ('기본장부', '주요', '영세율첨부', '업종별첨부', '기타')),
    CONSTRAINT uq_vat_form_tax_period_start_tax_period_end_form_type UNIQUE (tax_period_start, tax_period_end, form_type),
    CONSTRAINT ck_vat_form_tax_period_end_ge_tax_period_start CHECK (tax_period_end >= tax_period_start)
);

COMMENT ON TABLE vat_form IS '부가가치세 서식 - 한 행=과세기간·서식구분별 서식 1건. 서식구분(기본장부/주요/영세율첨부/업종별첨부/기타). 마감 후 수정 불가.';

COMMENT ON COLUMN vat_form.vat_form_id IS '부가가치세 서식 ID - 대리키';

COMMENT ON COLUMN vat_form.tax_period_start IS '과세기간 시작일 - 과세기간 입력 필수 (가정)';

COMMENT ON COLUMN vat_form.tax_period_end IS '과세기간 종료일 - 과세기간 입력 필수 (가정)';

COMMENT ON COLUMN vat_form.form_type IS '서식구분 - 서식 구분은 입력 시 필수 선택 (가정: 저장 코드는 명세 표기 그대로 사용)';

COMMENT ON COLUMN vat_form.form_content IS '서식 입력 내용 - 서식 입력 내용. 기본장부는 전표·세금계산서에서 작성하므로 입력이 없을 수 있음 (가정)';

COMMENT ON COLUMN vat_form.is_closed IS '마감 여부 - 마감 후 수정 불가. 마감 취소 전 수정 금지는 애플리케이션 규칙 (확인 필요). 삽입 시 false로 공급 (가정)';

COMMENT ON COLUMN vat_form.created_at IS '생성 일시';

COMMENT ON COLUMN vat_form.updated_at IS '수정 일시';

CREATE TABLE asset_depreciation (
    asset_depreciation_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_id BIGINT NOT NULL,
    account_subject_id BIGINT NOT NULL,
    acquisition_date DATE NOT NULL,
    acquisition_cost NUMERIC(18,2) NOT NULL,
    depreciation_method VARCHAR(50) NOT NULL,
    useful_life_months INTEGER NOT NULL,
    salvage_value NUMERIC(18,2),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset_depreciation PRIMARY KEY (asset_depreciation_id),
    CONSTRAINT uq_asset_depreciation_asset_id UNIQUE (asset_id),
    CONSTRAINT ck_asset_depreciation_acquisition_cost_ge_0 CHECK (acquisition_cost >= 0),
    CONSTRAINT ck_asset_depreciation_useful_life_months_gt_0 CHECK (useful_life_months > 0),
    CONSTRAINT ck_asset_depreciation_salvage_value_ge_0 CHECK (salvage_value >= 0),
    CONSTRAINT ck_asset_depreciation_salvage_value_le_acquisition_cost CHECK (salvage_value <= acquisition_cost)
);

COMMENT ON TABLE asset_depreciation IS '고정자산 감가상각 정보 - 한 행=자산 1건의 취득일·취득원가(>=0)·감가상각 정보(자산과 1:1, 자산 필수).';

COMMENT ON COLUMN asset_depreciation.asset_depreciation_id IS '고정자산 감가상각 정보 ID - 대리키';

COMMENT ON COLUMN asset_depreciation.asset_id IS '자산 - 자산과 1:1, 자산 필수';

COMMENT ON COLUMN asset_depreciation.account_subject_id IS '계정과목 - 고정자산 계정과목 (가정: 등록 시 필수)';

COMMENT ON COLUMN asset_depreciation.acquisition_date IS '취득일 - 등록 시 필수';

COMMENT ON COLUMN asset_depreciation.acquisition_cost IS '취득원가 - 0 이상 금액, 등록 시 필수 (정밀도 확인 필요)';

COMMENT ON COLUMN asset_depreciation.depreciation_method IS '감가상각 방법 - 감가상각 정보 등록 시 필수. 허용 값 목록 미확정 (확인 필요)';

COMMENT ON COLUMN asset_depreciation.useful_life_months IS '내용연수(개월) - 감가상각 정보 필수 (가정)';

COMMENT ON COLUMN asset_depreciation.salvage_value IS '잔존가액 - 선택 입력 (가정)';

COMMENT ON COLUMN asset_depreciation.created_at IS '생성 일시';

COMMENT ON COLUMN asset_depreciation.updated_at IS '수정 일시';

CREATE TABLE budget_commitment (
    budget_commitment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(200) NOT NULL,
    project_id BIGINT NOT NULL,
    budget_account_id BIGINT NOT NULL,
    partner_id BIGINT,
    amount NUMERIC(18,2) NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_budget_commitment PRIMARY KEY (budget_commitment_id),
    CONSTRAINT ck_budget_commitment_approval_status CHECK (approval_status IN ('신청', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_budget_commitment_amount_gt_0 CHECK (amount > 0)
);

COMMENT ON TABLE budget_commitment IS '원인행위 - 한 행=원인행위 1건. 명칭, 금액(예산잔액 범위), 프로젝트·예산과목 필수, 거래처 선택, 승인 상태.';

COMMENT ON COLUMN budget_commitment.budget_commitment_id IS '원인행위 ID - 대리키';

COMMENT ON COLUMN budget_commitment.name IS '원인행위 명칭 - 길이 가정';

COMMENT ON COLUMN budget_commitment.project_id IS '프로젝트';

COMMENT ON COLUMN budget_commitment.budget_account_id IS '예산과목';

COMMENT ON COLUMN budget_commitment.partner_id IS '거래처 - 선택';

COMMENT ON COLUMN budget_commitment.amount IS '원인행위 금액 - 예산잔액 범위 내 관리. 잔액 초과 검증은 여러 행 규칙이라 애플리케이션에서 처리 (확인 필요)';

COMMENT ON COLUMN budget_commitment.approval_status IS '승인 상태 - (가정) 공통 승인 처리 상태의 부분집합. 최초 저장 시 신청. 마감·마감 취소는 흐름에 없어 제외';

COMMENT ON COLUMN budget_commitment.created_at IS '생성 일시';

COMMENT ON COLUMN budget_commitment.updated_at IS '수정 일시';

CREATE TABLE personnel_record (
    personnel_record_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
