    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_personnel_record PRIMARY KEY (personnel_record_id),
    CONSTRAINT uq_personnel_record_employee_id UNIQUE (employee_id),
    CONSTRAINT ck_personnel_record_employment_status CHECK (employment_status IN ('재직자', '퇴직자')),
    CONSTRAINT ck_personnel_record_resignation_date_req CHECK (employment_status NOT IN ('퇴직자') OR resignation_date IS NOT NULL),
    CONSTRAINT ck_personnel_record_resignation_date_ge_hire_date CHECK (resignation_date >= hire_date)
);

COMMENT ON TABLE personnel_record IS '인사기록카드 - 한 행=임직원 1명의 인사기록(임직원과 1:1). 입사일, 채용·거주·보훈·병역·재직정보. 개인정보 암호화.';

COMMENT ON COLUMN personnel_record.personnel_record_id IS '인사기록카드 ID - 대리키';

COMMENT ON COLUMN personnel_record.employee_id IS '임직원 - 임직원과 1:1';

COMMENT ON COLUMN personnel_record.hire_date IS '입사일 - 근속연수·연차 산정 기준 (가정: 필수)';

COMMENT ON COLUMN personnel_record.recruitment_type IS '채용 구분 - 채용 정보. 허용 값 미확정 (확인 필요)';

COMMENT ON COLUMN personnel_record.recruitment_note IS '채용 정보 비고';

COMMENT ON COLUMN personnel_record.resident_number_enc IS '주민등록번호(암호화) - 고유식별정보 암호화 저장. 암호문 길이 수용. 필수 여부 미확정 (가정)';

COMMENT ON COLUMN personnel_record.address_enc IS '주소(암호화) - 거주 정보. 개인정보 암호화 저장';

COMMENT ON COLUMN personnel_record.veteran_info IS '보훈 정보 - 해당 없으면 생략';

COMMENT ON COLUMN personnel_record.military_service_info IS '병역 정보 - 해당 없으면 생략';

COMMENT ON COLUMN personnel_record.employment_status IS '재직 구분 - 공통 재직 구분. 신규 등록 시 재직자 (가정). 휴직·단축근무 승인 결과 반영은 별도 확인 필요';

COMMENT ON COLUMN personnel_record.resignation_date IS '퇴사일 - 퇴직자일 때 필요 (가정)';

COMMENT ON COLUMN personnel_record.created_at IS '생성 일시';

COMMENT ON COLUMN personnel_record.updated_at IS '수정 일시';

CREATE TABLE employee_family (
