    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_family PRIMARY KEY (employee_family_id)
);

COMMENT ON TABLE employee_family IS '가족 정보 - 한 행=임직원 가족 1명. 부양가족 여부. 암호화.';

COMMENT ON COLUMN employee_family.employee_family_id IS '가족 정보 ID - 대리키';

