COMMENT ON COLUMN employee_language.employee_id IS '임직원';

COMMENT ON COLUMN employee_language.language_name IS '외국어명';

COMMENT ON COLUMN employee_language.test_name IS '시험명';

COMMENT ON COLUMN employee_language.score IS '점수 - (가정) 시험 점수';

COMMENT ON COLUMN employee_language.grade IS '등급';

COMMENT ON COLUMN employee_language.test_date IS '취득일';

COMMENT ON COLUMN employee_language.expiry_date IS '유효기간 만료일';

COMMENT ON COLUMN employee_language.created_at IS '생성 일시';

COMMENT ON COLUMN employee_language.updated_at IS '수정 일시';

CREATE TABLE employee_evaluation (
