    evaluation_score NUMERIC(18,2),
    evaluator_name VARCHAR(100),
    comment TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_evaluation PRIMARY KEY (employee_evaluation_id),
    CONSTRAINT uq_employee_evaluation_employee_id_period_start_date_p_ca17a1da UNIQUE (employee_id, period_start_date, period_end_date),
    CONSTRAINT ck_employee_evaluation_period_end_date_ge_period_start_date CHECK (period_end_date >= period_start_date),
    CONSTRAINT ck_employee_evaluation_evaluation_score_ge_0 CHECK (evaluation_score >= 0)
);

COMMENT ON TABLE employee_evaluation IS '인사고과 - 한 행=임직원 인사고과 1건(대상기간별).';

COMMENT ON COLUMN employee_evaluation.employee_evaluation_id IS '인사고과 ID - 대리키';

COMMENT ON COLUMN employee_evaluation.employee_id IS '임직원';

COMMENT ON COLUMN employee_evaluation.period_start_date IS '대상기간 시작일';

COMMENT ON COLUMN employee_evaluation.period_end_date IS '대상기간 종료일';

COMMENT ON COLUMN employee_evaluation.evaluation_grade IS '고과 등급 - (가정) 등급 체계 전체 목록 미확인으로 자유 입력';

COMMENT ON COLUMN employee_evaluation.evaluation_score IS '고과 점수';

COMMENT ON COLUMN employee_evaluation.evaluator_name IS '평가자 - (확인 필요) 평가자가 계정 임직원인 경우 FK 전환 검토';

COMMENT ON COLUMN employee_evaluation.comment IS '평가 의견';

COMMENT ON COLUMN employee_evaluation.created_at IS '생성 일시';

COMMENT ON COLUMN employee_evaluation.updated_at IS '수정 일시';

CREATE TABLE employee_reward_penalty (
    employee_reward_penalty_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    reward_penalty_type VARCHAR(50) NOT NULL,
    title VARCHAR(200) NOT NULL,
    awarded_date DATE NOT NULL,
    issuer VARCHAR(200),
    content TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_reward_penalty PRIMARY KEY (employee_reward_penalty_id)
);

COMMENT ON TABLE employee_reward_penalty IS '상벌 - 한 행=임직원 상벌 1건.';

COMMENT ON COLUMN employee_reward_penalty.employee_reward_penalty_id IS '상벌 ID - 대리키';

COMMENT ON COLUMN employee_reward_penalty.employee_id IS '임직원';

COMMENT ON COLUMN employee_reward_penalty.reward_penalty_type IS '상벌 구분 - (가정) 상/벌 구분 값 체계가 확정되지 않아 허용값을 정하지 않음 (확인 필요)';

COMMENT ON COLUMN employee_reward_penalty.title IS '상벌명 - (가정) 길이·필수 여부';

COMMENT ON COLUMN employee_reward_penalty.awarded_date IS '상벌 일자 - (가정) 등록 시 필수';

COMMENT ON COLUMN employee_reward_penalty.issuer IS '수여·시행 기관 - (가정)';

COMMENT ON COLUMN employee_reward_penalty.content IS '상벌 내용';

COMMENT ON COLUMN employee_reward_penalty.created_at IS '생성 일시';

COMMENT ON COLUMN employee_reward_penalty.updated_at IS '수정 일시';

CREATE TABLE employee_business_trip (
    employee_business_trip_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    destination VARCHAR(200) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    purpose VARCHAR(500),
    remark TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_business_trip PRIMARY KEY (employee_business_trip_id),
    CONSTRAINT ck_employee_business_trip_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE employee_business_trip IS '인사기록 출장 - 한 행=인사기록카드의 출장 기록 1건(근태 출장과 별도).';

COMMENT ON COLUMN employee_business_trip.employee_business_trip_id IS '인사기록 출장 ID - 대리키';

COMMENT ON COLUMN employee_business_trip.employee_id IS '임직원';

COMMENT ON COLUMN employee_business_trip.destination IS '출장지 - (가정) 길이·필수 여부';

COMMENT ON COLUMN employee_business_trip.start_date IS '출장 시작일 - (가정) 등록 시 필수';

COMMENT ON COLUMN employee_business_trip.end_date IS '출장 종료일 - (가정) 등록 시 필수';

COMMENT ON COLUMN employee_business_trip.purpose IS '출장 목적 - (가정)';

COMMENT ON COLUMN employee_business_trip.remark IS '비고';

COMMENT ON COLUMN employee_business_trip.created_at IS '생성 일시';

COMMENT ON COLUMN employee_business_trip.updated_at IS '수정 일시';

CREATE TABLE personnel_change_request (
    personnel_change_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    change_item VARCHAR(100) NOT NULL,
    before_value_enc TEXT,
    after_value_enc TEXT NOT NULL,
    request_reason TEXT,
    status VARCHAR(20) NOT NULL,
    reviewer_id BIGINT,
    reviewed_at TIMESTAMPTZ,
    reject_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_personnel_change_request PRIMARY KEY (personnel_change_request_id),
    CONSTRAINT ck_personnel_change_request_status CHECK (status IN ('신청', '승인', '반려')),
    CONSTRAINT ck_personnel_change_request_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL),
    CONSTRAINT ck_personnel_change_request_reviewer_id_req CHECK (status NOT IN ('승인', '반려') OR reviewer_id IS NOT NULL),
    CONSTRAINT ck_personnel_change_request_reviewed_at_req CHECK (status NOT IN ('승인', '반려') OR reviewed_at IS NOT NULL)
);

COMMENT ON TABLE personnel_change_request IS '인사정보 변경 신청 - 한 행=변경 신청 1건. 상태(신청/승인/반려), 반려사유 필수.';

COMMENT ON COLUMN personnel_change_request.personnel_change_request_id IS '인사정보 변경 신청 ID - 대리키';

COMMENT ON COLUMN personnel_change_request.employee_id IS '신청 임직원';

COMMENT ON COLUMN personnel_change_request.change_item IS '변경 항목 - (가정) 변경 대상 인사정보 항목명';

COMMENT ON COLUMN personnel_change_request.before_value_enc IS '변경 전 값(암호화) - (가정) 개인정보 포함 가능하여 암호화 저장';

COMMENT ON COLUMN personnel_change_request.after_value_enc IS '변경 후 값(암호화) - (가정) 신청 시 필수, 암호화 저장';

COMMENT ON COLUMN personnel_change_request.request_reason IS '신청 사유';

COMMENT ON COLUMN personnel_change_request.status IS '승인 처리 상태 - FN-SFR-012-02 확정 값. 초기값: 신청 생성→신청';

COMMENT ON COLUMN personnel_change_request.reviewer_id IS '검토자 - 저장 후 검토 시 채워짐 (인사 담당자)';

COMMENT ON COLUMN personnel_change_request.reviewed_at IS '검토 일시 - 저장 후 처리 시 산출';

COMMENT ON COLUMN personnel_change_request.reject_reason IS '반려 사유 - 반려 시 필수';

COMMENT ON COLUMN personnel_change_request.created_at IS '생성 일시';

COMMENT ON COLUMN personnel_change_request.updated_at IS '수정 일시';

CREATE TABLE leave_of_absence_request (
    leave_of_absence_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    request_type VARCHAR(50) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    reason TEXT,
    status VARCHAR(20) NOT NULL,
    reviewer_id BIGINT,
    reviewed_at TIMESTAMPTZ,
    reject_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_leave_of_absence_request PRIMARY KEY (leave_of_absence_request_id),
    CONSTRAINT ck_leave_of_absence_request_status CHECK (status IN ('신청', '승인', '반려')),
    CONSTRAINT ck_leave_of_absence_request_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL),
    CONSTRAINT ck_leave_of_absence_request_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE leave_of_absence_request IS '휴직·단축근무 신청 - 한 행=신청 1건. 구분, 기간(종료>=시작), 상태.';

COMMENT ON COLUMN leave_of_absence_request.leave_of_absence_request_id IS '휴직·단축근무 신청 ID - 대리키';

COMMENT ON COLUMN leave_of_absence_request.employee_id IS '신청 임직원';

COMMENT ON COLUMN leave_of_absence_request.approval_document_id IS '전자결재 문서 - 결재 연계 사용 시에만 존재 (환경설정에 따름)';

COMMENT ON COLUMN leave_of_absence_request.request_type IS '신청 구분 - 휴직/단축근무 등 구분 값 체계 미확정 (확인 필요)';

COMMENT ON COLUMN leave_of_absence_request.start_date IS '시작일';

COMMENT ON COLUMN leave_of_absence_request.end_date IS '종료일 - (가정) 종료일 미정 휴직 가능 여부 확인 필요';

COMMENT ON COLUMN leave_of_absence_request.reason IS '신청 사유';

COMMENT ON COLUMN leave_of_absence_request.status IS '승인 처리 상태 - FN-SFR-012-07 확정 값. 초기값: 신청 생성→신청';

COMMENT ON COLUMN leave_of_absence_request.reviewer_id IS '검토자 - 저장 후 검토 시 채워짐 (결재 연계 시 결재 결과 반영)';

COMMENT ON COLUMN leave_of_absence_request.reviewed_at IS '검토 일시 - 저장 후 처리 시 산출';

COMMENT ON COLUMN leave_of_absence_request.reject_reason IS '반려 사유 - (가정) 반려 시 필수';

COMMENT ON COLUMN leave_of_absence_request.created_at IS '생성 일시';

COMMENT ON COLUMN leave_of_absence_request.updated_at IS '수정 일시';

CREATE TABLE personnel_appointment (
    personnel_appointment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    department_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    appointment_type VARCHAR(50) NOT NULL,
    appointment_date DATE NOT NULL,
    position_after VARCHAR(100),
    status VARCHAR(20) NOT NULL,
    reject_reason TEXT,
    processed_by BIGINT,
    processed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_personnel_appointment PRIMARY KEY (personnel_appointment_id),
    CONSTRAINT ck_personnel_appointment_status CHECK (status IN ('신청', '승인', '반려', '마감', '마감 취소', '승인 취소')),
    CONSTRAINT ck_personnel_appointment_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL)
);

COMMENT ON TABLE personnel_appointment IS '인사발령 - 한 행=임직원 발령 1건. 구분, 발령일, 발령 후 부서·직위, 상태. 처리 후 이력으로 누적.';

COMMENT ON COLUMN personnel_appointment.personnel_appointment_id IS '인사발령 ID - 대리키';

COMMENT ON COLUMN personnel_appointment.employee_id IS '발령 대상 임직원';

COMMENT ON COLUMN personnel_appointment.department_id IS '발령 후 부서 - (가정) 발령 시 필수';

COMMENT ON COLUMN personnel_appointment.approval_document_id IS '전자결재 문서 - 결재 연계 사용 시에만 존재 (환경설정에 따름)';

COMMENT ON COLUMN personnel_appointment.appointment_type IS '발령 구분 - 승진 등 구분 값 체계 미확정 (확인 필요), 승진현황 보고서는 승진 값 기준';

COMMENT ON COLUMN personnel_appointment.appointment_date IS '발령일자';

COMMENT ON COLUMN personnel_appointment.position_after IS '발령 후 직위·직책 - (가정) 부서만 바뀌는 발령 가능';

COMMENT ON COLUMN personnel_appointment.status IS '발령 상태 - (확인 필요) FN-SFR-013-01 승인 처리 상태 값 사용. 013-02는 발령상태 값을 인사 담당자 관리값으로 시작한다고 하며, 처리 완료 상태 표현이 없음 공통 도메인 조정: 발령 처리 완료 상태 추가 여부 확인. 초기값: 신청 등록→신청';

COMMENT ON COLUMN personnel_appointment.reject_reason IS '반려 사유 - 반려 시 필수';

COMMENT ON COLUMN personnel_appointment.processed_by IS '처리자 - (가정) 저장 후 발령 처리 시 채워짐. 부서 FK와 별도 역할 FK (카탈로그 parents에 없음, 카탈로그 수정 필요)';

COMMENT ON COLUMN personnel_appointment.processed_at IS '처리 일시 - 저장 후 처리 시 산출';

COMMENT ON COLUMN personnel_appointment.created_at IS '생성 일시';

COMMENT ON COLUMN personnel_appointment.updated_at IS '수정 일시';

CREATE TABLE education_code (
    education_code_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code_type VARCHAR(20) NOT NULL,
    code VARCHAR(50) NOT NULL,
    code_name VARCHAR(100) NOT NULL,
    sort_order INTEGER,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_code PRIMARY KEY (education_code_id),
    CONSTRAINT ck_education_code_code_type CHECK (code_type IN ('EDU_TYPE', 'EDU_METHOD')),
    CONSTRAINT ck_education_code_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT uq_education_code_code_type_code UNIQUE (code_type, code)
);

COMMENT ON TABLE education_code IS '교육 기준코드 - 한 행=교육유형/교육방법 코드. 관리자 관리.';

COMMENT ON COLUMN education_code.education_code_id IS '교육 기준코드 ID - 대리키';

COMMENT ON COLUMN education_code.code_type IS '코드 구분 - 교육유형/교육방법 구분 (명세상 두 가지 구분 기준)';

COMMENT ON COLUMN education_code.code IS '코드 - (가정) 구분 내 코드값. 허용값은 관리자가 관리하므로 allowed_values 생략';

COMMENT ON COLUMN education_code.code_name IS '코드명';

COMMENT ON COLUMN education_code.sort_order IS '정렬순서';

COMMENT ON COLUMN education_code.use_yn IS '사용 여부 - (가정) 등록 시 기본 사용';

COMMENT ON COLUMN education_code.created_at IS '생성 일시';

COMMENT ON COLUMN education_code.updated_at IS '수정 일시';

CREATE TABLE education_course (
    education_course_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    course_name VARCHAR(200) NOT NULL,
    education_type_id BIGINT NOT NULL,
    education_method_id BIGINT NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_course PRIMARY KEY (education_course_id)
);

COMMENT ON TABLE education_course IS '교육과정 - 한 행=교육과정 1개. 교육유형·방법 지정.';

COMMENT ON COLUMN education_course.education_course_id IS '교육과정 ID - 대리키';

COMMENT ON COLUMN education_course.course_name IS '교육과정명';

COMMENT ON COLUMN education_course.education_type_id IS '교육유형 - code_type이 EDU_TYPE인 education_code 참조 (확인 필요: 코드 구분 일치는 구조로 표현 불가)';

COMMENT ON COLUMN education_course.education_method_id IS '교육방법 - code_type이 EDU_METHOD인 education_code 참조 (확인 필요: 코드 구분 일치는 구조로 표현 불가). 교육유형과 교육방법 지정 필수';

COMMENT ON COLUMN education_course.description IS '과정 설명';

COMMENT ON COLUMN education_course.created_at IS '생성 일시';

COMMENT ON COLUMN education_course.updated_at IS '수정 일시';

CREATE TABLE education_session (
    education_session_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    education_course_id BIGINT NOT NULL,
    session_no INTEGER NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_session PRIMARY KEY (education_session_id),
    CONSTRAINT uq_education_session_education_course_id_session_no UNIQUE (education_course_id, session_no),
    CONSTRAINT ck_education_session_session_no_gt_0 CHECK (session_no > 0),
    CONSTRAINT ck_education_session_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE education_session IS '교육차수 - 한 행=과정의 차수 1건. 기간.';

COMMENT ON COLUMN education_session.education_session_id IS '교육차수 ID - 대리키';

COMMENT ON COLUMN education_session.education_course_id IS '교육과정';

COMMENT ON COLUMN education_session.session_no IS '차수 - 과정 내 차수 번호';

COMMENT ON COLUMN education_session.start_date IS '교육 시작일 - (가정) 교육 기간 필수';

COMMENT ON COLUMN education_session.end_date IS '교육 종료일 - (가정) 교육 기간 필수';

COMMENT ON COLUMN education_session.created_at IS '생성 일시';

COMMENT ON COLUMN education_session.updated_at IS '수정 일시';

CREATE TABLE education_attendee (
    education_attendee_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    education_session_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_attendee PRIMARY KEY (education_attendee_id),
    CONSTRAINT uq_education_attendee_education_session_id_employee_id UNIQUE (education_session_id, employee_id)
);

COMMENT ON TABLE education_attendee IS '교육대상자 - 한 행=차수·임직원 1건. 동일 조합 유일.';

COMMENT ON COLUMN education_attendee.education_attendee_id IS '교육대상자 ID - 대리키';

COMMENT ON COLUMN education_attendee.education_session_id IS '교육차수';

COMMENT ON COLUMN education_attendee.employee_id IS '임직원';

COMMENT ON COLUMN education_attendee.created_at IS '생성 일시';

COMMENT ON COLUMN education_attendee.updated_at IS '수정 일시';

CREATE TABLE education_application (
    education_application_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    education_session_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    status VARCHAR(20) NOT NULL,
    application_reason TEXT,
    reject_reason TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_application PRIMARY KEY (education_application_id),
    CONSTRAINT ck_education_application_status CHECK (status IN ('신청', '승인', '승인 취소', '반려')),
    CONSTRAINT uq_education_application_education_session_id_employee_id UNIQUE (education_session_id, employee_id),
    CONSTRAINT ck_education_application_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL)
);

COMMENT ON TABLE education_application IS '교육신청 - 한 행=차수·임직원 신청 1건. 상태(신청/승인/승인 취소/반려). 중복 신청 불가.';

COMMENT ON COLUMN education_application.education_application_id IS '교육신청 ID - 대리키';

COMMENT ON COLUMN education_application.education_session_id IS '교육차수';

COMMENT ON COLUMN education_application.employee_id IS '신청자';

COMMENT ON COLUMN education_application.approval_document_id IS '전자결재 문서 - 전자결재 연계 여부는 환경설정에 따르므로 연계 시에만 값 존재';

COMMENT ON COLUMN education_application.status IS '처리 상태 - 승인 처리 상태 중 명세상 허용 부분집합. 초기값: 신청 생성 시→신청';

COMMENT ON COLUMN education_application.application_reason IS '신청 사유 - (가정) 선택 입력';

COMMENT ON COLUMN education_application.reject_reason IS '반려 사유 - 반려 처리 시 저장 후 입력';

COMMENT ON COLUMN education_application.created_at IS '생성 일시';

COMMENT ON COLUMN education_application.updated_at IS '수정 일시';

CREATE TABLE education_result_report (
    education_result_report_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    education_session_id BIGINT NOT NULL,
    title VARCHAR(200),
    report_content TEXT NOT NULL,
    reported_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_result_report PRIMARY KEY (education_result_report_id)
);

COMMENT ON TABLE education_result_report IS '교육결과 보고 - 한 행=차수 결과보고 1건.';

COMMENT ON COLUMN education_result_report.education_result_report_id IS '교육결과 보고 ID - 대리키';

COMMENT ON COLUMN education_result_report.education_session_id IS '교육차수 ID - 결과보고 대상 차수. 차수당 1건 여부는 명세에 없어 유일 제약을 두지 않음(가정)';

COMMENT ON COLUMN education_result_report.title IS '보고 제목 - (가정) 길이 200, 선택값';

COMMENT ON COLUMN education_result_report.report_content IS '결과보고 내용 - 교육결과 보고 내용(입력 항목)';

COMMENT ON COLUMN education_result_report.reported_at IS '보고 일시 - (가정) 보고 등록 시각. 감사 컬럼과 별도';

COMMENT ON COLUMN education_result_report.created_at IS '생성 일시';

COMMENT ON COLUMN education_result_report.updated_at IS '수정 일시';

CREATE TABLE education_evaluation (
    education_evaluation_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    education_attendee_id BIGINT NOT NULL,
    evaluation_item VARCHAR(200),
    score NUMERIC(18,2),
    completed BOOLEAN,
    evaluated_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_education_evaluation PRIMARY KEY (education_evaluation_id),
    CONSTRAINT uq_education_evaluation_education_attendee_id_evaluation_item UNIQUE (education_attendee_id, evaluation_item),
    CONSTRAINT ck_education_evaluation_score_ge_0 CHECK (score >= 0)
);

COMMENT ON TABLE education_evaluation IS '교육평가 - 한 행=교육대상자 평가 1건. 점수, 수료 여부.';

COMMENT ON COLUMN education_evaluation.education_evaluation_id IS '교육평가 ID - 대리키';

COMMENT ON COLUMN education_evaluation.education_attendee_id IS '교육대상자 ID - 평가 대상 교육대상자. 차수는 교육대상자를 통해 연결됨';

COMMENT ON COLUMN education_evaluation.evaluation_item IS '평가 항목 - (가정) 평가 항목명. 항목별 개별 관리가 필요하면 별도 엔티티 필요 (확인 필요)';

COMMENT ON COLUMN education_evaluation.score IS '점수 - 평가 점수. 정밀도는 명세에 없음 (확인 필요). 평가 등록 시 입력 여부 불명확하여 선택값(가정)';

COMMENT ON COLUMN education_evaluation.completed IS '수료 여부 - 수료 여부. 입력 시점 불명확하여 선택값(가정)';

COMMENT ON COLUMN education_evaluation.evaluated_at IS '평가 일시 - (가정) 교육 종료 이후 평가 등록 시각. 교육 종료 이후라는 규칙은 여러 테이블 규칙이라 제약으로 표현 불가 (확인 필요)';

COMMENT ON COLUMN education_evaluation.created_at IS '생성 일시';

COMMENT ON COLUMN education_evaluation.updated_at IS '수정 일시';

CREATE TABLE certificate_type (
    certificate_type_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    form_body TEXT NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    approval_required BOOLEAN NOT NULL,
    numbering_prefix VARCHAR(20),
    numbering_digits INTEGER,
    numbering_reset_cycle VARCHAR(10),
    last_sequence INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_certificate_type PRIMARY KEY (certificate_type_id),
    CONSTRAINT uq_certificate_type_name UNIQUE (name),
    CONSTRAINT ck_certificate_type_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT ck_certificate_type_numbering_reset_cycle CHECK (numbering_reset_cycle IN ('연', '없음')),
    CONSTRAINT ck_certificate_type_numbering_digits_gt_0 CHECK (numbering_digits > 0)
);

COMMENT ON TABLE certificate_type IS '증명서 종류 - 한 행=증명서 양식 1종. 양식 본문, 사용 여부, 승인 필요 여부, 채번 규칙(종류별 독립).';

COMMENT ON COLUMN certificate_type.certificate_type_id IS '증명서 종류 ID - 대리키';

COMMENT ON COLUMN certificate_type.name IS '증명서 종류명 - (가정) 길이 100. 종류명 유일 여부는 근거 없으나 양식 1종 식별용으로 유일 가정 (확인 필요)';

COMMENT ON COLUMN certificate_type.form_body IS '양식 본문 - 증명서 양식 본문';

COMMENT ON COLUMN certificate_type.use_yn IS '사용 여부 - 공통 사용 여부 도메인. 초기값 사용(가정). 미사용은 신규 신청 제외';

COMMENT ON COLUMN certificate_type.approval_required IS '승인 필요 여부 - true면 전자결재 연계. 등록 시 입력값으로 공급(가정)';

COMMENT ON COLUMN certificate_type.numbering_prefix IS '채번 접두어 - (가정) 채번 규칙 구성요소. 종류별 독립 관리';

COMMENT ON COLUMN certificate_type.numbering_digits IS '채번 자릿수 - (가정) 일련번호 자릿수';

COMMENT ON COLUMN certificate_type.numbering_reset_cycle IS '채번 초기화 주기 - (가정) 채번 일련번호 초기화 주기. 명세에 없는 추천안 (확인 필요)';

COMMENT ON COLUMN certificate_type.last_sequence IS '마지막 일련번호 - 발급 시 증가시키는 현재 번호. 저장 후 갱신값 (확인 필요: 동시성 처리)';

COMMENT ON COLUMN certificate_type.created_at IS '생성 일시';

COMMENT ON COLUMN certificate_type.updated_at IS '수정 일시';

CREATE TABLE certificate_request (
    certificate_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    certificate_type_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    purpose VARCHAR(200) NOT NULL,
    submission_to VARCHAR(200),
    copies INTEGER NOT NULL,
    status VARCHAR(10) NOT NULL,
    reject_reason TEXT,
    issue_number VARCHAR(50),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_certificate_request PRIMARY KEY (certificate_request_id),
    CONSTRAINT ck_certificate_request_status CHECK (status IN ('신청', '승인', '반려')),
    CONSTRAINT uq_certificate_request_certificate_type_id_issue_number UNIQUE (certificate_type_id, issue_number),
    CONSTRAINT ck_certificate_request_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL),
    CONSTRAINT ck_certificate_request_issue_number_req CHECK (status NOT IN ('승인') OR issue_number IS NOT NULL),
    CONSTRAINT ck_certificate_request_copies_gt_0 CHECK (copies > 0)
);

COMMENT ON TABLE certificate_request IS '증명서 신청 - 한 행=신청 1건. 용도, 부수, 상태(신청/승인/반려), 발급번호(종류 내 유일).';

COMMENT ON COLUMN certificate_request.certificate_request_id IS '증명서 신청 ID - 대리키';

COMMENT ON COLUMN certificate_request.certificate_type_id IS '증명서 종류 ID';

COMMENT ON COLUMN certificate_request.employee_id IS '신청자 ID - 본인에 대해서만 신청 가능(여러 테이블 규칙으로 제약 표현 불가, 확인 필요)';

COMMENT ON COLUMN certificate_request.approval_document_id IS '전자결재 문서 ID - 승인 필요 증명서에서만 연계. 결재 연계 사용 시 필수 (확인 필요)';

COMMENT ON COLUMN certificate_request.purpose IS '용도 - (가정) 길이 200';

COMMENT ON COLUMN certificate_request.submission_to IS '제출처 - (가정) 길이 200, 선택값';

COMMENT ON COLUMN certificate_request.copies IS '부수 - 신청 부수. 입력값으로 공급';

COMMENT ON COLUMN certificate_request.status IS '처리 상태 - 명세의 신청·승인·반려 상태. 초기값 신청';

COMMENT ON COLUMN certificate_request.reject_reason IS '반려 사유 - 반려 시 필수';

COMMENT ON COLUMN certificate_request.issue_number IS '발급번호 - 승인 시 채번 규칙으로 자동 부여, 저장 후 산출. 종류 내 유일';

COMMENT ON COLUMN certificate_request.created_at IS '생성 일시';

COMMENT ON COLUMN certificate_request.updated_at IS '수정 일시';

CREATE TABLE attendance_item (
    attendance_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    deduct_yn BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attendance_item PRIMARY KEY (attendance_item_id),
    CONSTRAINT uq_attendance_item_name UNIQUE (name),
    CONSTRAINT ck_attendance_item_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE attendance_item IS '근태항목 - 한 행=근태항목 1개(연차/반차/보상휴가/병가/예비군 등). 사용 여부, 차감 여부. 사용된 항목은 미사용 처리.';

COMMENT ON COLUMN attendance_item.attendance_item_id IS '근태항목 ID - 대리키';

COMMENT ON COLUMN attendance_item.name IS '근태항목명 - (가정) 길이 100. 항목 식별용으로 유일 가정 (확인 필요)';

COMMENT ON COLUMN attendance_item.use_yn IS '사용 여부 - 공통 사용 여부 도메인. 초기값 사용(가정). 사용된 항목은 삭제하지 않고 미사용 처리';

COMMENT ON COLUMN attendance_item.deduct_yn IS '차감 여부 - 연차 등 차감 여부. 등록 시 입력값으로 공급';

COMMENT ON COLUMN attendance_item.created_at IS '생성 일시';

COMMENT ON COLUMN attendance_item.updated_at IS '수정 일시';

CREATE TABLE attendance_standard (
    attendance_standard_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    standard_type VARCHAR(20) NOT NULL,
    item_name VARCHAR(100) NOT NULL,
    standard_value VARCHAR(200),
    unit VARCHAR(30),
    use_yn VARCHAR(10) NOT NULL,
    apply_start_date DATE,
    apply_end_date DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attendance_standard PRIMARY KEY (attendance_standard_id),
    CONSTRAINT ck_attendance_standard_standard_type CHECK (standard_type IN ('기본근태', '근무시간', '시간외근무')),
    CONSTRAINT ck_attendance_standard_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT uq_attendance_standard_standard_type_item_name_apply_start_date UNIQUE (standard_type, item_name, apply_start_date),
    CONSTRAINT ck_attendance_standard_apply_end_date_ge_apply_start_date CHECK (apply_end_date >= apply_start_date)
);

COMMENT ON TABLE attendance_standard IS '근태·시간외근무 기준정보 - 한 행=기준정보 1건(구분: 기본근태/근무시간/시간외근무, 항목·값은 담당자 정의).';

COMMENT ON COLUMN attendance_standard.attendance_standard_id IS '근태·시간외근무 기준정보 ID - 대리키';

COMMENT ON COLUMN attendance_standard.standard_type IS '기준 구분 - 기준정보 구분(명세 확정 3종)';

COMMENT ON COLUMN attendance_standard.item_name IS '기준 항목명 - (가정) 항목 구성은 근태 담당자가 정의하는 값이며 길이는 가정';

COMMENT ON COLUMN attendance_standard.standard_value IS '기준 값 - (가정) 값과 단위는 담당자 정의. 항목별 값 형식이 달라 문자열로 보관 (확인 필요) 단위 정의 방식';

COMMENT ON COLUMN attendance_standard.unit IS '단위 - (가정) 담당자가 정의하는 값 단위';

COMMENT ON COLUMN attendance_standard.use_yn IS '사용 여부 - 초기값: 등록 시 사용 (가정)';

COMMENT ON COLUMN attendance_standard.apply_start_date IS '적용 시작일 - (가정) 마감 기간 수정 제한 판단용. 마감 기간 수정 금지는 다중 행 규칙이라 (확인 필요)';

COMMENT ON COLUMN attendance_standard.apply_end_date IS '적용 종료일 - (가정) 미지정이면 계속 적용';

COMMENT ON COLUMN attendance_standard.created_at IS '생성 일시';

COMMENT ON COLUMN attendance_standard.updated_at IS '수정 일시';

CREATE TABLE employee_attendance_setting (
    employee_attendance_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    attendance_item_id BIGINT NOT NULL,
    apply_start_date DATE NOT NULL,
    apply_standard VARCHAR(200),
    apply_end_date DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_attendance_setting PRIMARY KEY (employee_attendance_setting_id),
    CONSTRAINT uq_employee_attendance_setting_employee_id_attendance__86eeedbc UNIQUE (employee_id, attendance_item_id, apply_start_date),
    CONSTRAINT ck_employee_attendance_setting_apply_end_date_ge_apply_a6cfae0c CHECK (apply_end_date >= apply_start_date)
);

COMMENT ON TABLE employee_attendance_setting IS '임직원별 근태 적용 설정 - 한 행=임직원·근태항목·적용시작일 1건. 임직원·근태항목 필수.';

COMMENT ON COLUMN employee_attendance_setting.employee_attendance_setting_id IS '임직원별 근태 적용 설정 ID - 대리키';

COMMENT ON COLUMN employee_attendance_setting.employee_id IS '임직원';

COMMENT ON COLUMN employee_attendance_setting.attendance_item_id IS '근태항목 - 미사용 근태항목은 적용 불가 (확인 필요) 다른 행 참조 규칙이라 스키마로 표현 불가';

COMMENT ON COLUMN employee_attendance_setting.apply_start_date IS '적용 시작일';

COMMENT ON COLUMN employee_attendance_setting.apply_standard IS '적용 근태 기준 - (가정) 담당자 정의 기준 값';

COMMENT ON COLUMN employee_attendance_setting.apply_end_date IS '적용 종료일 - (가정) 미지정이면 계속 적용';

COMMENT ON COLUMN employee_attendance_setting.created_at IS '생성 일시';

COMMENT ON COLUMN employee_attendance_setting.updated_at IS '수정 일시';

CREATE TABLE commute_check_setting (
    commute_check_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    apply_unit VARCHAR(20) NOT NULL,
    department_id BIGINT,
    employee_id BIGINT,
    check_type VARCHAR(50) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_commute_check_setting PRIMARY KEY (commute_check_setting_id),
    CONSTRAINT ck_commute_check_setting_apply_unit CHECK (apply_unit IN ('법인', '부서', '사원')),
    CONSTRAINT ck_commute_check_setting_department_id_req CHECK (apply_unit NOT IN ('부서') OR department_id IS NOT NULL),
    CONSTRAINT ck_commute_check_setting_employee_id_req CHECK (apply_unit NOT IN ('사원') OR employee_id IS NOT NULL)
);

COMMENT ON TABLE commute_check_setting IS '출퇴근 체크 유형 설정 - 한 행=적용단위(법인/부서/사원)별 체크유형. 부서·사원 단위는 대상 필수, 우선순위 사원>부서>법인.';

COMMENT ON COLUMN commute_check_setting.commute_check_setting_id IS '출퇴근 체크 유형 설정 ID - 대리키';

COMMENT ON COLUMN commute_check_setting.apply_unit IS '적용 단위 - 우선순위 사원>부서>법인';

COMMENT ON COLUMN commute_check_setting.department_id IS '대상 부서 - 적용 단위가 부서일 때 필수';

COMMENT ON COLUMN commute_check_setting.employee_id IS '대상 사원 - 적용 단위가 사원일 때 필수';

COMMENT ON COLUMN commute_check_setting.check_type IS '출퇴근 체크 유형 - (확인 필요) 체크 유형 전체 목록이 명세에 없어 허용값 미정';

COMMENT ON COLUMN commute_check_setting.created_at IS '생성 일시';

COMMENT ON COLUMN commute_check_setting.updated_at IS '수정 일시';

CREATE TABLE allowed_ip (
    allowed_ip_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    ip_address VARCHAR(45) NOT NULL,
    description VARCHAR(200),
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_allowed_ip PRIMARY KEY (allowed_ip_id),
    CONSTRAINT uq_allowed_ip_ip_address UNIQUE (ip_address),
    CONSTRAINT ck_allowed_ip_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE allowed_ip IS '접근 허용 IP - 한 행=허용 IP 1개(유일). 사용 여부, 출퇴근 체크 한정.';

COMMENT ON COLUMN allowed_ip.allowed_ip_id IS '접근 허용 IP ID - 대리키';

COMMENT ON COLUMN allowed_ip.ip_address IS '허용 IP 주소 - IPv6 수용 길이(가정). 중복 등록 불가';

COMMENT ON COLUMN allowed_ip.description IS '설명';

COMMENT ON COLUMN allowed_ip.use_yn IS '사용 여부 - 초기값: 등록 시 사용 (가정). 미사용 IP는 판단에서 제외';

COMMENT ON COLUMN allowed_ip.created_at IS '생성 일시';

COMMENT ON COLUMN allowed_ip.updated_at IS '수정 일시';

CREATE TABLE annual_leave_plan (
    annual_leave_plan_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    plan_month VARCHAR(7) NOT NULL,
    plan_dates DATE,
    plan_days NUMERIC(18,2) NOT NULL,
    approval_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_annual_leave_plan PRIMARY KEY (annual_leave_plan_id),
    CONSTRAINT ck_annual_leave_plan_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT uq_annual_leave_plan_employee_id_plan_month UNIQUE (employee_id, plan_month),
    CONSTRAINT ck_annual_leave_plan_plan_days_gt_0 CHECK (plan_days > 0)
);

COMMENT ON TABLE annual_leave_plan IS '월별 연차계획 - 한 행=임직원·계획월 연차계획 1건. 일자, 승인 상태. 합계<=잔여.';

COMMENT ON COLUMN annual_leave_plan.annual_leave_plan_id IS '월별 연차계획 ID - 대리키';

COMMENT ON COLUMN annual_leave_plan.employee_id IS '임직원';

COMMENT ON COLUMN annual_leave_plan.approval_document_id IS '전자결재 문서 - 상신 후 연결되므로 선택값';

COMMENT ON COLUMN annual_leave_plan.plan_month IS '계획월 - YYYY-MM 형식(가정)';

COMMENT ON COLUMN annual_leave_plan.plan_dates IS '계획 일자 - (확인 필요) 월별 복수 일자는 개별 관리가 필요해 별도 엔티티 필요(카탈로그 수정 필요)';

COMMENT ON COLUMN annual_leave_plan.plan_days IS '계획 일수 합계 - 입력 시 공급(가정). 반차 허용을 위해 소수. 합계<=잔여 연차는 다른 엔티티 비교라 (확인 필요)';

COMMENT ON COLUMN annual_leave_plan.approval_status IS '승인 처리 상태 - 공통 승인 처리 상태 도메인. 초기값: 작성·상신 시 신청 (가정)';

COMMENT ON COLUMN annual_leave_plan.created_at IS '생성 일시';

COMMENT ON COLUMN annual_leave_plan.updated_at IS '수정 일시';

CREATE TABLE leave_promotion (
    leave_promotion_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    notification_id BIGINT,
    promotion_year INTEGER NOT NULL,
    promotion_stage VARCHAR(50) NOT NULL,
    scheduled_date DATE NOT NULL,
    notified_at TIMESTAMPTZ,
    remaining_days NUMERIC(18,2),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_leave_promotion PRIMARY KEY (leave_promotion_id),
    CONSTRAINT uq_leave_promotion_employee_id_promotion_year_promotion_stage UNIQUE (employee_id, promotion_year, promotion_stage)
);

COMMENT ON TABLE leave_promotion IS '연차사용촉진계획 - 한 행=대상 임직원별 촉진 1건. 촉진 구분·일정·통지.';

COMMENT ON COLUMN leave_promotion.leave_promotion_id IS '연차사용촉진계획 ID - 대리키';

COMMENT ON COLUMN leave_promotion.employee_id IS '대상 임직원';

COMMENT ON COLUMN leave_promotion.notification_id IS '통지 알림 - 촉진 통지 발송 후 연계되므로 NULL 허용 (가정)';

COMMENT ON COLUMN leave_promotion.promotion_year IS '기준연도 - (가정) 촉진 대상 연차의 기준연도';

COMMENT ON COLUMN leave_promotion.promotion_stage IS '촉진 구분 - (가정) 촉진 단계와 통지 시점은 환경설정에서 정하므로 코드 목록 미확정 (확인 필요)';

COMMENT ON COLUMN leave_promotion.scheduled_date IS '통지 예정일 - 근태 담당자가 지정한 일정';

COMMENT ON COLUMN leave_promotion.notified_at IS '통지 일시 - 저장 후 통지 발송 시 채워짐';

COMMENT ON COLUMN leave_promotion.remaining_days IS '촉진 시점 잔여일수 - (가정) 통지 시점 잔여 연차 스냅샷, 저장 후 산출';

COMMENT ON COLUMN leave_promotion.created_at IS '생성 일시';

COMMENT ON COLUMN leave_promotion.updated_at IS '수정 일시';

CREATE TABLE commute_record (
    commute_record_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    work_date DATE NOT NULL,
    check_in_at TIMESTAMPTZ,
    check_out_at TIMESTAMPTZ,
    is_linked BOOLEAN NOT NULL,
    is_closed BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_commute_record PRIMARY KEY (commute_record_id),
    CONSTRAINT uq_commute_record_employee_id_work_date UNIQUE (employee_id, work_date),
    CONSTRAINT ck_commute_record_check_out_at_ge_check_in_at CHECK (check_out_at >= check_in_at)
);

COMMENT ON TABLE commute_record IS '출퇴근 기록 - 한 행=임직원·일자 출퇴근 1건. 출·퇴근시각, 연동 여부. 마감 후 수정 불가.';

COMMENT ON COLUMN commute_record.commute_record_id IS '출퇴근 기록 ID - 대리키';

COMMENT ON COLUMN commute_record.employee_id IS '임직원';

COMMENT ON COLUMN commute_record.work_date IS '근무일자';

COMMENT ON COLUMN commute_record.check_in_at IS '출근시각 - 퇴근만 먼저 입력되는 경우 대비 (가정)';

COMMENT ON COLUMN commute_record.check_out_at IS '퇴근시각 - 저장 후 퇴근 시 채워짐';

COMMENT ON COLUMN commute_record.is_linked IS '연동 여부 - 외부 출퇴근 연동 데이터 여부';

COMMENT ON COLUMN commute_record.is_closed IS '마감 여부 - (가정) 마감 시 수정 불가 판단용. 신규 행은 false, 근태 마감 처리에서 true로 갱신. 마감 기간 수정 금지는 여러 행 규칙이므로 (확인 필요)';

COMMENT ON COLUMN commute_record.created_at IS '생성 일시';

COMMENT ON COLUMN commute_record.updated_at IS '수정 일시';

CREATE TABLE attendance_closing (
    attendance_closing_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_document_id BIGINT,
    closing_unit VARCHAR(10) NOT NULL,
    closing_date DATE NOT NULL,
    status VARCHAR(20) NOT NULL,
    closed_at TIMESTAMPTZ,
    cancelled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attendance_closing PRIMARY KEY (attendance_closing_id),
    CONSTRAINT ck_attendance_closing_closing_unit CHECK (closing_unit IN ('일', '월')),
    CONSTRAINT ck_attendance_closing_status CHECK (status IN ('마감', '마감 취소')),
    CONSTRAINT uq_attendance_closing_closing_unit_closing_date UNIQUE (closing_unit, closing_date),
    CONSTRAINT ck_attendance_closing_cancelled_at_req CHECK (status NOT IN ('마감 취소') OR cancelled_at IS NOT NULL)
);

COMMENT ON TABLE attendance_closing IS '근태 마감 - 한 행=마감 단위(일/월) 1건. 마감·마감 취소 상태. 법인 공통(가정).';

COMMENT ON COLUMN attendance_closing.attendance_closing_id IS '근태 마감 ID - 대리키';

COMMENT ON COLUMN attendance_closing.approval_document_id IS '전자결재 문서 - 결재 연계 사용 시에만 필요';

COMMENT ON COLUMN attendance_closing.closing_unit IS '마감 단위';

COMMENT ON COLUMN attendance_closing.closing_date IS '마감 대상 일자 - 일 마감은 해당 일자, 월 마감은 해당 월 1일 (가정)';

COMMENT ON COLUMN attendance_closing.status IS '마감 상태 - (가정) 승인 처리 상태 도메인의 부분집합. 생성 시 마감으로 시작. 결재 연계 시 신청·승인·반려 필요하면 (확인 필요) 공통 도메인 조정: 신청/승인/반려 추가 검토';

COMMENT ON COLUMN attendance_closing.closed_at IS '마감 일시 - 저장 후 마감 처리 시 채워짐';

COMMENT ON COLUMN attendance_closing.cancelled_at IS '마감 취소 일시 - 마감 취소 시 채워짐';

COMMENT ON COLUMN attendance_closing.created_at IS '생성 일시';

COMMENT ON COLUMN attendance_closing.updated_at IS '수정 일시';

CREATE TABLE leave_grant_rule (
    leave_grant_rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    base_days NUMERIC(18,2) NOT NULL,
    additional_days NUMERIC(18,2),
    additional_condition VARCHAR(500),
    use_status VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_leave_grant_rule PRIMARY KEY (leave_grant_rule_id),
    CONSTRAINT ck_leave_grant_rule_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT ck_leave_grant_rule_base_days_ge_0 CHECK (base_days >= 0),
    CONSTRAINT ck_leave_grant_rule_additional_days_ge_0 CHECK (additional_days >= 0)
);

COMMENT ON TABLE leave_grant_rule IS '연차 생성 기준 - 한 행=기준 1건(기본일수, 가산일수·조건, 사용 여부). 이후 생성분부터 적용.';

COMMENT ON COLUMN leave_grant_rule.leave_grant_rule_id IS '연차 생성 기준 ID - 대리키';

COMMENT ON COLUMN leave_grant_rule.name IS '기준명 - (가정) 길이';

COMMENT ON COLUMN leave_grant_rule.base_days IS '기본일수';

COMMENT ON COLUMN leave_grant_rule.additional_days IS '가산일수 - 가산 없는 기준은 NULL';

COMMENT ON COLUMN leave_grant_rule.additional_condition IS '가산 조건 - (가정) 근무연수 등 조건 서술. 구조화 여부 (확인 필요)';

COMMENT ON COLUMN leave_grant_rule.use_status IS '사용 여부 - (가정) 신규 기준은 사용으로 시작';

COMMENT ON COLUMN leave_grant_rule.created_at IS '생성 일시';

COMMENT ON COLUMN leave_grant_rule.updated_at IS '수정 일시';

CREATE TABLE annual_leave (
    annual_leave_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    leave_grant_rule_id BIGINT,
    base_year INTEGER NOT NULL,
    granted_days NUMERIC(18,2) NOT NULL,
    is_confirmed BOOLEAN NOT NULL,
    confirmed_at TIMESTAMPTZ,
    used_days NUMERIC(18,2),
    remaining_days NUMERIC(18,2),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_annual_leave PRIMARY KEY (annual_leave_id),
    CONSTRAINT uq_annual_leave_employee_id_base_year UNIQUE (employee_id, base_year),
    CONSTRAINT ck_annual_leave_confirmed_at_req CHECK (is_confirmed NOT IN ('true') OR confirmed_at IS NOT NULL),
    CONSTRAINT ck_annual_leave_granted_days_ge_0 CHECK (granted_days >= 0),
    CONSTRAINT ck_annual_leave_used_days_ge_0 CHECK (used_days >= 0)
);

COMMENT ON TABLE annual_leave IS '연차 - 한 행=임직원·기준연도 연차 1건. 생성일수, 확정 여부, 사용·잔여.';

COMMENT ON COLUMN annual_leave.annual_leave_id IS '연차 ID - 대리키';

COMMENT ON COLUMN annual_leave.employee_id IS '임직원';

COMMENT ON COLUMN annual_leave.leave_grant_rule_id IS '연차 생성 기준 - 엑셀 업로드·수동 생성 시 기준 없을 수 있음 (가정)';

COMMENT ON COLUMN annual_leave.base_year IS '기준연도';

COMMENT ON COLUMN annual_leave.granted_days IS '생성일수 - 삽입 시 입력·생성 로직으로 공급';

COMMENT ON COLUMN annual_leave.is_confirmed IS '확정 여부 - 생성 시 false, 확정 시 true (가정)';

COMMENT ON COLUMN annual_leave.confirmed_at IS '확정 일시 - 확정 시 채워짐';

COMMENT ON COLUMN annual_leave.used_days IS '사용일수 - 저장 후 산출, 사용 내역 합계 저장 요구 (가정)';

COMMENT ON COLUMN annual_leave.remaining_days IS '잔여일수 - 저장 후 산출. 마이너스 연차 허용 시 음수 가능';

COMMENT ON COLUMN annual_leave.created_at IS '생성 일시';

COMMENT ON COLUMN annual_leave.updated_at IS '수정 일시';

CREATE TABLE leave_usage (
    leave_usage_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    annual_leave_id BIGINT NOT NULL,
    attendance_request_id BIGINT NOT NULL,
    used_days NUMERIC(18,2) NOT NULL,
    used_date DATE NOT NULL,
    deducted_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_leave_usage PRIMARY KEY (leave_usage_id),
    CONSTRAINT uq_leave_usage_attendance_request_id_annual_leave_id_used_date UNIQUE (attendance_request_id, annual_leave_id, used_date),
    CONSTRAINT ck_leave_usage_used_days_gt_0 CHECK (used_days > 0)
);

COMMENT ON TABLE leave_usage IS '연차 사용 내역 - 한 행=승인된 연차 근태의 차감 1건.';

COMMENT ON COLUMN leave_usage.leave_usage_id IS '연차 사용 내역 ID - 대리키';

COMMENT ON COLUMN leave_usage.annual_leave_id IS '연차 ID';

COMMENT ON COLUMN leave_usage.attendance_request_id IS '근태 ID - 승인된 연차·반차 등 근태 건. 승인 시 사용 내역이 기록되므로 삽입 시 공급(가정)';

COMMENT ON COLUMN leave_usage.used_days IS '차감 일수 - 차감된 연차 일수(반차 0.5 등). 정밀도 (확인 필요), 승인 시 산출하여 삽입 시 공급(가정)';

COMMENT ON COLUMN leave_usage.used_date IS '사용일 - 연차 사용일. 다중 일정 일괄 기안 시 일자별 1건 여부 (확인 필요)';

COMMENT ON COLUMN leave_usage.deducted_at IS '차감 처리 시각 - 차감 기록 시각, 삽입 시 공급(가정)';

COMMENT ON COLUMN leave_usage.created_at IS '생성 일시';

COMMENT ON COLUMN leave_usage.updated_at IS '수정 일시';

CREATE TABLE annual_leave_settlement (
    annual_leave_settlement_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    annual_leave_id BIGINT NOT NULL,
    settlement_base_date DATE NOT NULL,
    unused_days NUMERIC(18,2),
    unused_allowance NUMERIC(18,2),
    settled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_annual_leave_settlement PRIMARY KEY (annual_leave_settlement_id),
    CONSTRAINT uq_annual_leave_settlement_annual_leave_id_settlement_base_date UNIQUE (annual_leave_id, settlement_base_date),
    CONSTRAINT ck_annual_leave_settlement_unused_days_ge_0 CHECK (unused_days >= 0),
    CONSTRAINT ck_annual_leave_settlement_unused_allowance_ge_0 CHECK (unused_allowance >= 0)
);

COMMENT ON TABLE annual_leave_settlement IS '연차 정산 - 한 행=연차 정산 1건. 정산기준일, 미사용 수당.';

COMMENT ON COLUMN annual_leave_settlement.annual_leave_settlement_id IS '연차 정산 ID - 대리키';

COMMENT ON COLUMN annual_leave_settlement.annual_leave_id IS '연차 ID';

COMMENT ON COLUMN annual_leave_settlement.settlement_base_date IS '정산기준일 - 근태 담당자가 입력';

COMMENT ON COLUMN annual_leave_settlement.unused_days IS '미사용 일수 - 저장 후 산출(가정)';

COMMENT ON COLUMN annual_leave_settlement.unused_allowance IS '미사용 수당 - 저장 후 산출. 급여 반영에 이용(가정)';

COMMENT ON COLUMN annual_leave_settlement.settled_at IS '정산 처리 시각 - 정산 완료 후 채움(가정)';

COMMENT ON COLUMN annual_leave_settlement.created_at IS '생성 일시';

COMMENT ON COLUMN annual_leave_settlement.updated_at IS '수정 일시';

CREATE TABLE attendance_trip_traveler (
    attendance_trip_traveler_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    attendance_request_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    transport VARCHAR(100),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_attendance_trip_traveler PRIMARY KEY (attendance_trip_traveler_id),
    CONSTRAINT uq_attendance_trip_traveler_attendance_request_id_employee_id UNIQUE (attendance_request_id, employee_id)
);

COMMENT ON TABLE attendance_trip_traveler IS '출장자·이동수단 - 한 행=출장 근태의 출장자 1명. 이동수단(가정).';

COMMENT ON COLUMN attendance_trip_traveler.attendance_trip_traveler_id IS '출장자·이동수단 ID - 대리키';

COMMENT ON COLUMN attendance_trip_traveler.attendance_request_id IS '근태 ID - 출장 유형 근태';

COMMENT ON COLUMN attendance_trip_traveler.employee_id IS '출장자 ID';

COMMENT ON COLUMN attendance_trip_traveler.transport IS '이동수단 - (가정) 이동수단 목록 미확정으로 자유 입력, 선택값';

COMMENT ON COLUMN attendance_trip_traveler.created_at IS '생성 일시';

COMMENT ON COLUMN attendance_trip_traveler.updated_at IS '수정 일시';

CREATE TABLE payroll_code (
    payroll_code_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code_category VARCHAR(30) NOT NULL,
    code VARCHAR(20) NOT NULL,
    code_name VARCHAR(100) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    remark VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll_code PRIMARY KEY (payroll_code_id),
    CONSTRAINT ck_payroll_code_code_category CHECK (code_category IN ('근로소득', '퇴직소득', '소득공제', '농특세', '지방소득세', '사회보험정산', '학자금상환')),
    CONSTRAINT ck_payroll_code_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT uq_payroll_code_code_category_code UNIQUE (code_category, code)
);

COMMENT ON TABLE payroll_code IS '급여 기초코드 - 한 행=코드구분(근로소득/퇴직소득/소득공제/농특세/지방소득세/사회보험정산/학자금상환)별 코드 1개. 구분 내 유일, 사용 여부.';

COMMENT ON COLUMN payroll_code.payroll_code_id IS '급여 기초코드 ID - 대리키';

COMMENT ON COLUMN payroll_code.code_category IS '코드구분 - (확인 필요) FN-020-01은 5가지, 020-03 및 엔티티 정의는 사회보험정산·학자금상환 포함 7가지. 농어촌특별세는 농특세로 표기 통일';

COMMENT ON COLUMN payroll_code.code IS '코드 - 구분 내 유일. 길이 (가정)';

COMMENT ON COLUMN payroll_code.code_name IS '코드명 - 길이 (가정)';

COMMENT ON COLUMN payroll_code.use_yn IS '사용 여부 - 초기값 사용(가정). 계산에 쓰인 코드는 삭제 대신 미사용 처리';

COMMENT ON COLUMN payroll_code.remark IS '비고 - 길이 (가정)';

COMMENT ON COLUMN payroll_code.created_at IS '생성 일시';

COMMENT ON COLUMN payroll_code.updated_at IS '수정 일시';

CREATE TABLE payroll_item (
    payroll_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    item_type VARCHAR(10) NOT NULL,
    item_name VARCHAR(100) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll_item PRIMARY KEY (payroll_item_id),
    CONSTRAINT ck_payroll_item_item_type CHECK (item_type IN ('지급', '공제')),
    CONSTRAINT ck_payroll_item_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE payroll_item IS '지급공제항목 - 한 행=지급 또는 공제 항목 1개. 사용 여부.';

COMMENT ON COLUMN payroll_item.payroll_item_id IS '지급공제항목 ID - 대리키';

COMMENT ON COLUMN payroll_item.item_type IS '지급공제 구분';

COMMENT ON COLUMN payroll_item.item_name IS '항목명 - 길이 (가정). 항목명 유일성 근거 없음';

COMMENT ON COLUMN payroll_item.use_yn IS '사용 여부 - 초기값 사용(가정). 미사용은 급여 계산 적용 제외';

COMMENT ON COLUMN payroll_item.created_at IS '생성 일시';

COMMENT ON COLUMN payroll_item.updated_at IS '수정 일시';

CREATE TABLE payroll_account_mapping (
    payroll_account_mapping_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    account_subject_id BIGINT NOT NULL,
    payroll_type VARCHAR(30) NOT NULL,
    is_active VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll_account_mapping PRIMARY KEY (payroll_account_mapping_id),
    CONSTRAINT ck_payroll_account_mapping_payroll_type CHECK (payroll_type IN ('상용직', '일용직', '퇴직금')),
    CONSTRAINT ck_payroll_account_mapping_is_active CHECK (is_active IN ('사용', '미사용')),
    CONSTRAINT uq_payroll_account_mapping_payroll_type_account_subject_id UNIQUE (payroll_type, account_subject_id)
);

COMMENT ON TABLE payroll_account_mapping IS '급여 전표 계정 설정 - 한 행=급여구분별 전표처리 계정과목 1건.';

COMMENT ON COLUMN payroll_account_mapping.payroll_account_mapping_id IS '급여 전표 계정 설정 ID - 대리키';

COMMENT ON COLUMN payroll_account_mapping.account_subject_id IS '계정과목';

COMMENT ON COLUMN payroll_account_mapping.payroll_type IS '급여 구분 - 예시(상용직·일용직·퇴직금 등) 기반 (가정). 지급·공제 등 항목 구분 컬럼은 항목 구분 코드 미확정으로 추가하지 않음 (확인 필요)';

COMMENT ON COLUMN payroll_account_mapping.is_active IS '사용 여부 - 초기값: 사용 (가정)';

COMMENT ON COLUMN payroll_account_mapping.created_at IS '생성 일시';

COMMENT ON COLUMN payroll_account_mapping.updated_at IS '수정 일시';

CREATE TABLE withholding_adjustment_request (
    withholding_adjustment_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    tax_year INTEGER NOT NULL,
    adjustment_rate NUMERIC(18,2),
    adjustment_amount_enc TEXT,
    reason TEXT,
    approval_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_withholding_adjustment_request PRIMARY KEY (withholding_adjustment_request_id),
    CONSTRAINT ck_withholding_adjustment_request_approval_status CHECK (approval_status IN ('신청', '마감', '마감 취소', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_withholding_adjustment_request_adjustment_rate_ge_0 CHECK (adjustment_rate >= 0)
);

COMMENT ON TABLE withholding_adjustment_request IS '원천징수세액 조정 신청 - 한 행=신청 1건. 승인 상태, 개인정보 열람 이력 대상.';

COMMENT ON COLUMN withholding_adjustment_request.withholding_adjustment_request_id IS '원천징수세액 조정 신청 ID - 대리키';

COMMENT ON COLUMN withholding_adjustment_request.employee_id IS '신청 임직원';

COMMENT ON COLUMN withholding_adjustment_request.approval_document_id IS '전자결재 문서 - 결재 연계 사용 여부는 환경설정에 따르므로 선택 (가정)';

COMMENT ON COLUMN withholding_adjustment_request.tax_year IS '조정 대상 연도 - (가정) 신청 시 입력';

COMMENT ON COLUMN withholding_adjustment_request.adjustment_rate IS '조정 세율(%) - (가정) 세액 조정 비율 입력. 비율 또는 금액 중 하나 사용 (확인 필요)';

COMMENT ON COLUMN withholding_adjustment_request.adjustment_amount_enc IS '조정 금액(암호화) - 급여 개인정보로 암호화 저장 (가정). 비율 또는 금액 중 하나 사용 (확인 필요)';

COMMENT ON COLUMN withholding_adjustment_request.reason IS '신청 사유 - (가정)';

COMMENT ON COLUMN withholding_adjustment_request.approval_status IS '승인 상태 - 공통 결정의 승인 처리 상태 도메인. 초기값 신청 (가정)';

COMMENT ON COLUMN withholding_adjustment_request.created_at IS '생성 일시';

COMMENT ON COLUMN withholding_adjustment_request.updated_at IS '수정 일시';

CREATE TABLE salary_step (
    salary_step_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    step_grade VARCHAR(20) NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    is_active VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_salary_step PRIMARY KEY (salary_step_id),
    CONSTRAINT uq_salary_step_step_grade UNIQUE (step_grade),
    CONSTRAINT ck_salary_step_is_active CHECK (is_active IN ('사용', '미사용')),
    CONSTRAINT ck_salary_step_amount_ge_0 CHECK (amount >= 0)
);

COMMENT ON TABLE salary_step IS '호봉테이블 - 한 행=호봉 등급 1개와 금액.';

COMMENT ON COLUMN salary_step.salary_step_id IS '호봉테이블 ID - 대리키';

COMMENT ON COLUMN salary_step.step_grade IS '호봉 등급 - 호봉 등급 1개당 1행. 길이 (가정)';

COMMENT ON COLUMN salary_step.amount IS '호봉별 금액 - 금액이므로 decimal. 호봉 등록 시 입력';

COMMENT ON COLUMN salary_step.is_active IS '사용 여부 - (가정) 초기값 사용';

COMMENT ON COLUMN salary_step.created_at IS '생성 일시';

COMMENT ON COLUMN salary_step.updated_at IS '수정 일시';

CREATE TABLE employee_wage (
    employee_wage_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    salary_step_id BIGINT,
    effective_date DATE NOT NULL,
    wage_amount_enc TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_wage PRIMARY KEY (employee_wage_id),
    CONSTRAINT uq_employee_wage_employee_id_effective_date UNIQUE (employee_id, effective_date)
);

COMMENT ON TABLE employee_wage IS '임직원 책정임금·호봉 - 한 행=임직원·적용일별 책정임금(암호화)과 호봉 1건.';

COMMENT ON COLUMN employee_wage.employee_wage_id IS '임직원 책정임금·호봉 ID - 대리키';

COMMENT ON COLUMN employee_wage.employee_id IS '임직원';

COMMENT ON COLUMN employee_wage.salary_step_id IS '호봉 - 호봉 미적용 임직원이 있을 수 있어 선택 (가정). 지정 시 호봉테이블 등록 등급만 가능';

COMMENT ON COLUMN employee_wage.effective_date IS '적용일';

COMMENT ON COLUMN employee_wage.wage_amount_enc IS '책정임금(암호화) - 급여 개인정보로 암호화 저장. 입력 또는 일괄 변경 계산 후 삽입 (가정)';

COMMENT ON COLUMN employee_wage.created_at IS '생성 일시';

COMMENT ON COLUMN employee_wage.updated_at IS '수정 일시';

CREATE TABLE payroll_run (
    payroll_run_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    journal_entry_id BIGINT,
    pay_date DATE NOT NULL,
    payroll_type VARCHAR(20) NOT NULL,
    is_closed BOOLEAN NOT NULL,
    journal_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll_run PRIMARY KEY (payroll_run_id),
    CONSTRAINT ck_payroll_run_payroll_type CHECK (payroll_type IN ('REGULAR', 'DAILY', 'SEVERANCE')),
    CONSTRAINT ck_payroll_run_journal_status CHECK (journal_status IN ('UNPROCESSED', 'PROCESSED')),
    CONSTRAINT uq_payroll_run_pay_date_payroll_type UNIQUE (pay_date, payroll_type),
    CONSTRAINT ck_payroll_run_journal_entry_id_req CHECK (journal_status NOT IN ('PROCESSED') OR journal_entry_id IS NOT NULL)
);

COMMENT ON TABLE payroll_run IS '급여 지급일 - 한 행=지급일·급여구분 1건. 마감 여부, 전표처리 상태. 급여는 지급일로 연결(가정).';

COMMENT ON COLUMN payroll_run.payroll_run_id IS '급여 지급일 ID - 대리키';

COMMENT ON COLUMN payroll_run.journal_entry_id IS '급여 전표 - 전표처리 후 연결되므로 저장 후 채움';

COMMENT ON COLUMN payroll_run.pay_date IS '지급일';

COMMENT ON COLUMN payroll_run.payroll_type IS '급여구분 - payroll_account_mapping.payroll_type과 동일 도메인 (가정)';

COMMENT ON COLUMN payroll_run.is_closed IS '마감 여부 - 신규 등록 시 false로 시작 (가정). 마감 전 급여는 전표처리·발송 불가';

COMMENT ON COLUMN payroll_run.journal_status IS '전표처리 상태 - (가정) 최소 상태 집합. 초기값 UNPROCESSED, 전표처리 완료 시 PROCESSED. 중복 전표처리 불가';

COMMENT ON COLUMN payroll_run.created_at IS '생성 일시';

COMMENT ON COLUMN payroll_run.updated_at IS '수정 일시';

CREATE TABLE payroll_detail (
    payroll_detail_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    payroll_id BIGINT NOT NULL,
    payroll_item_id BIGINT NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_payroll_detail PRIMARY KEY (payroll_detail_id),
    CONSTRAINT uq_payroll_detail_payroll_id_payroll_item_id UNIQUE (payroll_id, payroll_item_id),
    CONSTRAINT ck_payroll_detail_amount_ge_0 CHECK (amount >= 0)
);

COMMENT ON TABLE payroll_detail IS '급여 항목 상세 - 한 행=급여 1건의 지급·공제항목별 금액. 암호화.';

COMMENT ON COLUMN payroll_detail.payroll_detail_id IS '급여 항목 상세 ID - 대리키';

COMMENT ON COLUMN payroll_detail.payroll_id IS '급여 ID';

COMMENT ON COLUMN payroll_detail.payroll_item_id IS '지급공제항목 ID';

COMMENT ON COLUMN payroll_detail.amount IS '금액 - (가정) 항목별 금액은 행 생성 시 공급된다. 급여 개인정보로 암호화 저장 대상이다. (확인 필요) 컬럼 단위 암호화(*_enc) 적용 방식은 데이터 표준 협의 후 확정한다.';

COMMENT ON COLUMN payroll_detail.created_at IS '생성 일시';

COMMENT ON COLUMN payroll_detail.updated_at IS '수정 일시';

CREATE TABLE daily_worker (
    daily_worker_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    resident_registration_no_enc VARCHAR(500) NOT NULL,
    daily_wage NUMERIC(18,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_daily_worker PRIMARY KEY (daily_worker_id),
    CONSTRAINT ck_daily_worker_daily_wage_ge_0 CHECK (daily_wage >= 0)
);

COMMENT ON TABLE daily_worker IS '일용직 사원 - 한 행=일용직 1명. 성명, 주민번호 암호화, 일급.';

COMMENT ON COLUMN daily_worker.daily_worker_id IS '일용직 사원 ID - 대리키';

COMMENT ON COLUMN daily_worker.name IS '성명 - (가정) 길이 100';

COMMENT ON COLUMN daily_worker.resident_registration_no_enc IS '주민등록번호(암호화) - 고유식별정보로 암호화 저장하며 평문은 저장하지 않는다. (가정) 길이 500';

COMMENT ON COLUMN daily_worker.daily_wage IS '일급 - (가정) 일용직 등록 시 입력 필수';

COMMENT ON COLUMN daily_worker.created_at IS '생성 일시';

COMMENT ON COLUMN daily_worker.updated_at IS '수정 일시';

CREATE TABLE daily_worker_payment (
    daily_worker_payment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    daily_worker_id BIGINT NOT NULL,
    payment_date DATE NOT NULL,
    work_days INTEGER NOT NULL,
    payment_amount NUMERIC(18,2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_daily_worker_payment PRIMARY KEY (daily_worker_payment_id),
    CONSTRAINT uq_daily_worker_payment_daily_worker_id_payment_date UNIQUE (daily_worker_id, payment_date),
    CONSTRAINT ck_daily_worker_payment_work_days_gt_0 CHECK (work_days > 0),
    CONSTRAINT ck_daily_worker_payment_payment_amount_ge_0 CHECK (payment_amount >= 0)
);

COMMENT ON TABLE daily_worker_payment IS '일용직 급여 지급 - 한 행=일용직·지급일 1건. 근무일수, 지급액.';

COMMENT ON COLUMN daily_worker_payment.daily_worker_payment_id IS '일용직 급여 지급 ID - 대리키';

COMMENT ON COLUMN daily_worker_payment.daily_worker_id IS '일용직 사원 ID';

COMMENT ON COLUMN daily_worker_payment.payment_date IS '지급일';

COMMENT ON COLUMN daily_worker_payment.work_days IS '근무일수 - (가정) 입력 필수';

COMMENT ON COLUMN daily_worker_payment.payment_amount IS '지급액 - (가정) 지급액은 일괄 입력 시 함께 입력된다. 삽입 전 공급';

COMMENT ON COLUMN daily_worker_payment.created_at IS '생성 일시';

COMMENT ON COLUMN daily_worker_payment.updated_at IS '수정 일시';

CREATE TABLE severance_calculation (
    severance_calculation_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    retirement_date DATE NOT NULL,
    severance_amount_enc TEXT,
    estimated_amount_enc TEXT,
    retirement_basis VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_severance_calculation PRIMARY KEY (severance_calculation_id)
);

COMMENT ON TABLE severance_calculation IS '퇴직금 산정 - 한 행=퇴직 임직원 1건의 산정 결과·추계액. 암호화.';

COMMENT ON COLUMN severance_calculation.severance_calculation_id IS '퇴직금 산정 ID - 대리키';

COMMENT ON COLUMN severance_calculation.employee_id IS '퇴직 임직원 ID';

COMMENT ON COLUMN severance_calculation.retirement_date IS '퇴직일 - 입력값으로 공급';

COMMENT ON COLUMN severance_calculation.severance_amount_enc IS '퇴직금 산정액(암호화) - 급여 개인정보로 암호화 저장. 저장 후 산출 (산정 처리 결과)';

COMMENT ON COLUMN severance_calculation.estimated_amount_enc IS '퇴직금 추계액(암호화) - 급여 개인정보로 암호화 저장. 저장 후 산출';

COMMENT ON COLUMN severance_calculation.retirement_basis IS '퇴직기준 - (가정) 산정에 적용한 퇴직기준 설명. (확인 필요) 퇴직기준 설정의 별도 엔티티 필요 여부는 카탈로그에 없음';

COMMENT ON COLUMN severance_calculation.created_at IS '생성 일시';

COMMENT ON COLUMN severance_calculation.updated_at IS '수정 일시';

CREATE TABLE social_insurance_enrollment (
    social_insurance_enrollment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    insurance_type VARCHAR(50) NOT NULL,
    report_type VARCHAR(50) NOT NULL,
    acquisition_date DATE,
    loss_date DATE,
    loss_reason VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_social_insurance_enrollment PRIMARY KEY (social_insurance_enrollment_id),
    CONSTRAINT ck_social_insurance_enrollment_insurance_type CHECK (insurance_type IN ('국민연금', '건강보험', '고용보험', '산재보험')),
    CONSTRAINT ck_social_insurance_enrollment_report_type CHECK (report_type IN ('취득', '상실')),
    CONSTRAINT uq_social_insurance_enrollment_employee_id_insurance_t_5c0dd913 UNIQUE (employee_id, insurance_type, report_type),
    CONSTRAINT ck_social_insurance_enrollment_acquisition_date_req CHECK (report_type NOT IN ('취득') OR acquisition_date IS NOT NULL),
    CONSTRAINT ck_social_insurance_enrollment_loss_date_req CHECK (report_type NOT IN ('상실') OR loss_date IS NOT NULL),
    CONSTRAINT ck_social_insurance_enrollment_loss_reason_req CHECK (report_type NOT IN ('상실') OR loss_reason IS NOT NULL)
);

COMMENT ON TABLE social_insurance_enrollment IS '사회보험 취득·상실 대상자 - 한 행=임직원·보험종류·신고구분 1건. 취득일/상실일, 상실사유(상실 시만).';

COMMENT ON COLUMN social_insurance_enrollment.social_insurance_enrollment_id IS '사회보험 취득·상실 대상자 ID - 대리키';

COMMENT ON COLUMN social_insurance_enrollment.employee_id IS '임직원 ID';

COMMENT ON COLUMN social_insurance_enrollment.insurance_type IS '보험 종류 - (가정) 4대보험 기준 전체 집합';

COMMENT ON COLUMN social_insurance_enrollment.report_type IS '신고 구분 - 자격취득/자격상실 신고 구분';

COMMENT ON COLUMN social_insurance_enrollment.acquisition_date IS '취득일 - 취득 신고일 때 필수';

COMMENT ON COLUMN social_insurance_enrollment.loss_date IS '상실일 - 상실 신고일 때 필수';

COMMENT ON COLUMN social_insurance_enrollment.loss_reason IS '상실 사유 - 자격상실 신고에서만 입력. (가정) 길이 500';

COMMENT ON COLUMN social_insurance_enrollment.created_at IS '생성 일시';

COMMENT ON COLUMN social_insurance_enrollment.updated_at IS '수정 일시';

CREATE TABLE social_insurance_grade (
    social_insurance_grade_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    insurance_type VARCHAR(30) NOT NULL,
    apply_start_month VARCHAR(6) NOT NULL,
    grade VARCHAR(20) NOT NULL,
    standard_monthly_amount NUMERIC(18,2),
    changed_by_id BIGINT,
    changed_at TIMESTAMPTZ,
    change_content VARCHAR(1000),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_social_insurance_grade PRIMARY KEY (social_insurance_grade_id),
    CONSTRAINT ck_social_insurance_grade_insurance_type CHECK (insurance_type IN ('NATIONAL_PENSION', 'HEALTH', 'EMPLOYMENT', 'INDUSTRIAL_ACCIDENT')),
    CONSTRAINT uq_social_insurance_grade_employee_id_insurance_type_a_af3d0169 UNIQUE (employee_id, insurance_type, apply_start_month),
    CONSTRAINT ck_social_insurance_grade_standard_monthly_amount_ge_0 CHECK (standard_monthly_amount >= 0)
);

COMMENT ON TABLE social_insurance_grade IS '사회보험 등급 - 한 행=임직원·보험종류·적용시작월별 등급 1건(변경 이력 누적).';

COMMENT ON COLUMN social_insurance_grade.social_insurance_grade_id IS '사회보험 등급 ID - 대리키';

COMMENT ON COLUMN social_insurance_grade.employee_id IS '임직원';

COMMENT ON COLUMN social_insurance_grade.insurance_type IS '보험 종류 - (가정) 4대보험 기준 전체 집합. 장기요양은 건강보험에 포함하는 것으로 가정(확인 필요)';

COMMENT ON COLUMN social_insurance_grade.apply_start_month IS '적용 시작월 - YYYYMM 형식. 해당 월부터 공제내역 산정에 반영';

COMMENT ON COLUMN social_insurance_grade.grade IS '등급 - (가정) 보험별 등급 표기가 달라 문자열로 저장. 길이는 가정';

COMMENT ON COLUMN social_insurance_grade.standard_monthly_amount IS '기준소득월액 - (가정) 등급에 대응하는 금액을 저장할 경우에만 사용';

COMMENT ON COLUMN social_insurance_grade.changed_by_id IS '변경자 - 등급 변경 처리자(수정자). 시스템 일괄 생성 시 NULL 가능(가정)';

COMMENT ON COLUMN social_insurance_grade.changed_at IS '변경 일시 - 등급 변경 처리 시각(P8 변경 이력 일시)';

COMMENT ON COLUMN social_insurance_grade.change_content IS '변경 내용 - (가정) 변경 전후 등급 등 변경 내용 요약. 길이는 가정';

COMMENT ON COLUMN social_insurance_grade.created_at IS '생성 일시';

COMMENT ON COLUMN social_insurance_grade.updated_at IS '수정 일시';

CREATE TABLE social_insurance_report (
    social_insurance_report_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT,
    social_insurance_enrollment_id BIGINT,
    report_type VARCHAR(30) NOT NULL,
    insurance_type VARCHAR(30),
    period_start DATE,
    period_end DATE,
    event_date DATE,
    loss_reason VARCHAR(200),
    total_amount NUMERIC(18,2),
    resident_number_enc VARCHAR(500),
    created_by_id BIGINT,
    printed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_social_insurance_report PRIMARY KEY (social_insurance_report_id),
    CONSTRAINT ck_social_insurance_report_report_type CHECK (report_type IN ('QUALIFICATION_ACQUISITION', 'QUALIFICATION_LOSS', 'TOTAL_REMUNERATION', 'EMPLOYMENT_INDUSTRIAL', 'SEPARATION_CONFIRMATION', 'WORK_CONTENT_CONFIRMATION')),
    CONSTRAINT ck_social_insurance_report_insurance_type CHECK (insurance_type IN ('NATIONAL_PENSION', 'HEALTH', 'EMPLOYMENT', 'INDUSTRIAL_ACCIDENT')),
    CONSTRAINT ck_social_insurance_report_event_date_req CHECK (report_type NOT IN ('QUALIFICATION_ACQUISITION', 'QUALIFICATION_LOSS') OR event_date IS NOT NULL),
    CONSTRAINT ck_social_insurance_report_loss_reason_req CHECK (report_type NOT IN ('QUALIFICATION_LOSS') OR loss_reason IS NOT NULL),
    CONSTRAINT ck_social_insurance_report_social_insurance_enrollment_id_req CHECK (report_type NOT IN ('QUALIFICATION_ACQUISITION', 'QUALIFICATION_LOSS') OR social_insurance_enrollment_id IS NOT NULL),
    CONSTRAINT ck_social_insurance_report_period_end_ge_period_start CHECK (period_end >= period_start)
);

COMMENT ON TABLE social_insurance_report IS '사회보험 신고서 - 한 행=신고서 1건(종류·기간). 작성·출력 이력 관리, 전자신고 없음.';

COMMENT ON COLUMN social_insurance_report.social_insurance_report_id IS '사회보험 신고서 ID - 대리키';

COMMENT ON COLUMN social_insurance_report.employee_id IS '대상 임직원 - (가정) 보수총액 등 전체 대상 신고서는 특정 임직원이 없을 수 있어 NULL 허용';

COMMENT ON COLUMN social_insurance_report.social_insurance_enrollment_id IS '취득·상실 대상자 - 취득·상실 신고서일 때 필요';

COMMENT ON COLUMN social_insurance_report.report_type IS '신고서 종류 - (가정) 명세에 언급된 신고서 종류를 기반으로 한 추천 집합';

COMMENT ON COLUMN social_insurance_report.insurance_type IS '보험 종류 - (가정) 도메인은 social_insurance_grade와 동일하게 맞춤';

COMMENT ON COLUMN social_insurance_report.period_start IS '대상 기간 시작일 - 기간형 신고서에서 사용';

COMMENT ON COLUMN social_insurance_report.period_end IS '대상 기간 종료일';

COMMENT ON COLUMN social_insurance_report.event_date IS '취득일 또는 상실일 - 취득·상실 신고서에서 사용';

COMMENT ON COLUMN social_insurance_report.loss_reason IS '상실 사유 - 자격상실 신고에서만 입력. 길이는 가정';

COMMENT ON COLUMN social_insurance_report.total_amount IS '보수총액 - 급여 데이터를 참조해 저장 후 산출(작성 시)';

COMMENT ON COLUMN social_insurance_report.resident_number_enc IS '주민등록번호(암호화) - 고유식별정보 암호화 저장. 대상자 인사정보 자동 반영';

COMMENT ON COLUMN social_insurance_report.created_by_id IS '작성자 - (가정) 인사 담당자 계정. 상위 엔티티에 없어 카탈로그 수정 필요';

COMMENT ON COLUMN social_insurance_report.printed_at IS '최종 출력 일시 - 출력 시 갱신. 출력 이력 전체는 별도 이력으로 관리(확인 필요)';

COMMENT ON COLUMN social_insurance_report.created_at IS '생성 일시';

COMMENT ON COLUMN social_insurance_report.updated_at IS '수정 일시';

CREATE TABLE tax_filing (
    tax_filing_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    filing_type VARCHAR(40) NOT NULL,
    attribution_month VARCHAR(6),
    payment_month VARCHAR(6),
    submission_year VARCHAR(4),
    income_category VARCHAR(30),
    filing_status VARCHAR(20) NOT NULL,
    total_amount NUMERIC(18,2),
    filed_at TIMESTAMPTZ,
    result_message VARCHAR(1000),
    receipt_number VARCHAR(50),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_tax_filing PRIMARY KEY (tax_filing_id),
    CONSTRAINT ck_tax_filing_filing_type CHECK (filing_type IN ('WITHHOLDING_STATUS', 'TUITION_REPAYMENT', 'LOCAL_INCOME_TAX', 'RESIDENT_TAX_EMPLOYEE', 'SIMPLIFIED_PAYMENT', 'SUBMISSION_SUMMARY', 'PAYMENT_MEDIA')),
    CONSTRAINT ck_tax_filing_filing_status CHECK (filing_status IN ('DRAFT', 'SUCCESS', 'FAILURE')),
    CONSTRAINT ck_tax_filing_filed_at_req CHECK (filing_status NOT IN ('SUCCESS', 'FAILURE') OR filed_at IS NOT NULL)
);

COMMENT ON TABLE tax_filing IS '세무 신고서 - 한 행=신고서·명세서 1건. 유형(원천징수이행상황/학자금상환/지방세/간이지급명세서/제출집계표 등), 귀속·지급연월, 전자신고 결과(접수 성공·실패).';

COMMENT ON COLUMN tax_filing.tax_filing_id IS '세무 신고서 ID - 대리키';

COMMENT ON COLUMN tax_filing.filing_type IS '신고서 유형 - (가정) 명세 예시 기반 추천 집합. 법인지방소득세 등 추가 유형은 확인 필요';

COMMENT ON COLUMN tax_filing.attribution_month IS '귀속연월 - YYYYMM';

COMMENT ON COLUMN tax_filing.payment_month IS '지급연월 - YYYYMM';

COMMENT ON COLUMN tax_filing.submission_year IS '제출 대상 연도 - 제출집계표·전산매체용';

COMMENT ON COLUMN tax_filing.income_category IS '소득 구분 - (가정) 소득 구분 전체 집합 미확정으로 허용값 생략';

COMMENT ON COLUMN tax_filing.filing_status IS '신고 상태 - (가정) 작성 중 DRAFT에서 시작. 전자신고 접수 성공·실패 결과 반영. 초기값: 모든 경로→DRAFT';

COMMENT ON COLUMN tax_filing.total_amount IS '집계 금액 - 급여 집계 후 저장 후 산출';

COMMENT ON COLUMN tax_filing.filed_at IS '전자신고 일시';

COMMENT ON COLUMN tax_filing.result_message IS '전자신고 결과 메시지 - 실패 사유 등. 길이는 가정';

COMMENT ON COLUMN tax_filing.receipt_number IS '접수번호 - (가정) 접수 성공 시 외부 접수번호';

COMMENT ON COLUMN tax_filing.created_at IS '생성 일시';

COMMENT ON COLUMN tax_filing.updated_at IS '수정 일시';

CREATE TABLE income_certificate (
    income_certificate_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT,
    daily_worker_id BIGINT,
    certificate_category VARCHAR(30) NOT NULL,
    document_type VARCHAR(30) NOT NULL,
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    total_payment_amount NUMERIC(18,2),
    withheld_tax_amount NUMERIC(18,2),
    resident_number_enc VARCHAR(500),
    issued_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_income_certificate PRIMARY KEY (income_certificate_id),
    CONSTRAINT ck_income_certificate_certificate_category CHECK (certificate_category IN ('DAILY_WAGE', 'RETIREMENT_INCOME', 'EARNED_INCOME')),
    CONSTRAINT ck_income_certificate_document_type CHECK (document_type IN ('PAYMENT_STATEMENT', 'WITHHOLDING_RECEIPT')),
    CONSTRAINT ck_income_certificate_one_employee_id_daily_worker_id CHECK ((CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN daily_worker_id IS NOT NULL THEN 1 ELSE 0 END) = 1),
    CONSTRAINT ck_income_certificate_period_end_ge_period_start CHECK (period_end >= period_start),
    CONSTRAINT ck_income_certificate_total_payment_amount_ge_0 CHECK (total_payment_amount >= 0),
    CONSTRAINT ck_income_certificate_withheld_tax_amount_ge_0 CHECK (withheld_tax_amount >= 0)
);

COMMENT ON TABLE income_certificate IS '소득 지급명세서·원천징수영수증 - 한 행=발급 문서 1건. 구분(일용근로/퇴직소득/근로소득), 귀속기간. 임직원 또는 일용직 중 하나 참조.';

COMMENT ON COLUMN income_certificate.income_certificate_id IS '소득 지급명세서·원천징수영수증 ID - 대리키';

COMMENT ON COLUMN income_certificate.employee_id IS '임직원';

COMMENT ON COLUMN income_certificate.daily_worker_id IS '일용직 사원';

COMMENT ON COLUMN income_certificate.certificate_category IS '구분 - 일용근로/퇴직소득/근로소득';

COMMENT ON COLUMN income_certificate.document_type IS '문서 종류 - (가정) 지급명세서/원천징수영수증 구분';

COMMENT ON COLUMN income_certificate.period_start IS '귀속 시작일';

COMMENT ON COLUMN income_certificate.period_end IS '귀속 종료일';

COMMENT ON COLUMN income_certificate.total_payment_amount IS '총지급액 - 지급 데이터 기반 저장 후 산출';

COMMENT ON COLUMN income_certificate.withheld_tax_amount IS '원천징수세액 - 저장 후 산출';

COMMENT ON COLUMN income_certificate.resident_number_enc IS '주민등록번호(암호화) - 고유식별정보 암호화 저장';

COMMENT ON COLUMN income_certificate.issued_at IS '발급 일시';

COMMENT ON COLUMN income_certificate.created_at IS '생성 일시';

COMMENT ON COLUMN income_certificate.updated_at IS '수정 일시';

CREATE TABLE year_end_item (
    year_end_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    code VARCHAR(30) NOT NULL,
    name VARCHAR(100) NOT NULL,
    category VARCHAR(50),
    limit_amount NUMERIC(18,2),
    sort_order INTEGER,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_year_end_item PRIMARY KEY (year_end_item_id),
    CONSTRAINT uq_year_end_item_code UNIQUE (code),
    CONSTRAINT ck_year_end_item_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT ck_year_end_item_limit_amount_ge_0 CHECK (limit_amount >= 0)
);

COMMENT ON TABLE year_end_item IS '연말정산 항목 - 한 행=연말정산 공제 항목 1개. 급여 담당자 관리.';

COMMENT ON COLUMN year_end_item.year_end_item_id IS '연말정산 항목 ID - 대리키';

COMMENT ON COLUMN year_end_item.code IS '항목 코드 - (가정) 항목 코드. 길이는 가정';

COMMENT ON COLUMN year_end_item.name IS '항목명';

COMMENT ON COLUMN year_end_item.category IS '항목 분류 - (가정) 소득공제/세액공제 등 분류. 전체 집합 미확정';

COMMENT ON COLUMN year_end_item.limit_amount IS '공제 한도액 - (가정) 한도가 있는 항목만 입력';

COMMENT ON COLUMN year_end_item.sort_order IS '정렬 순서';

COMMENT ON COLUMN year_end_item.use_yn IS '사용 여부 - 공통 결정 ''사용 여부'' 도메인. 초기값: 신규 등록→사용(가정)';

COMMENT ON COLUMN year_end_item.created_at IS '생성 일시';

COMMENT ON COLUMN year_end_item.updated_at IS '수정 일시';

CREATE TABLE year_end_data (
    year_end_data_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    year_end_item_id BIGINT NOT NULL,
    target_year INTEGER NOT NULL,
    amount NUMERIC(18,2),
    closing_status VARCHAR(20) NOT NULL,
    closed_at TIMESTAMPTZ,
    attachment_id BIGINT,
    remark VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_year_end_data PRIMARY KEY (year_end_data_id),
    CONSTRAINT ck_year_end_data_closing_status CHECK (closing_status IN ('신청', '마감', '마감 취소')),
    CONSTRAINT uq_year_end_data_employee_id_year_end_item_id_target_year UNIQUE (employee_id, year_end_item_id, target_year),
    CONSTRAINT ck_year_end_data_closed_at_req CHECK (closing_status NOT IN ('마감') OR closed_at IS NOT NULL)
);

COMMENT ON TABLE year_end_data IS '연말정산 자료 - 한 행=임직원·연도·항목별 자료 1건. 마감 후 수정 불가.';

COMMENT ON COLUMN year_end_data.year_end_data_id IS '연말정산 자료 ID - 대리키';

COMMENT ON COLUMN year_end_data.employee_id IS '임직원';

COMMENT ON COLUMN year_end_data.year_end_item_id IS '연말정산 항목';

COMMENT ON COLUMN year_end_data.target_year IS '정산 대상 연도 - 연말정산 대상 연도(YYYY)';

COMMENT ON COLUMN year_end_data.amount IS '금액 - (가정) 항목별 공제·소득 금액. 항목에 따라 금액 외 입력이 있을 수 있어 선택값으로 둠';

COMMENT ON COLUMN year_end_data.closing_status IS '마감 상태 - (가정) 승인 처리 상태 도메인의 부분집합. 신청=입력·제출 중, 마감=급여 담당자 마감(수정 불가), 마감 취소=마감 해제. 초기값: 자료 최초 입력→신청';

COMMENT ON COLUMN year_end_data.closed_at IS '마감 일시 - 마감 처리 시 채워짐(저장 후 처리)';

COMMENT ON COLUMN year_end_data.attachment_id IS '증빙 첨부파일 - (가정) 증빙 첨부는 선택. 카탈로그 상위에 attachment가 없어 참조 불가 (카탈로그 수정 필요)';

COMMENT ON COLUMN year_end_data.remark IS '비고 - (가정) 길이 500';

COMMENT ON COLUMN year_end_data.created_at IS '생성 일시';

COMMENT ON COLUMN year_end_data.updated_at IS '수정 일시';

CREATE TABLE year_end_result (
    year_end_result_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    target_year INTEGER NOT NULL,
    total_salary_amount NUMERIC(18,2),
    determined_tax_amount NUMERIC(18,2),
    paid_tax_amount NUMERIC(18,2),
    payable_tax_amount NUMERIC(18,2),
    closing_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_year_end_result PRIMARY KEY (year_end_result_id),
    CONSTRAINT ck_year_end_result_closing_status CHECK (closing_status IN ('신청', '마감', '마감 취소')),
    CONSTRAINT uq_year_end_result_employee_id_target_year UNIQUE (employee_id, target_year)
);

COMMENT ON TABLE year_end_result IS '연말정산 결과 - 한 행=임직원·연도 정산 결과 1건. 납부세액.';

COMMENT ON COLUMN year_end_result.year_end_result_id IS '연말정산 결과 ID - 대리키';

COMMENT ON COLUMN year_end_result.employee_id IS '임직원';

COMMENT ON COLUMN year_end_result.target_year IS '정산 대상 연도';

COMMENT ON COLUMN year_end_result.total_salary_amount IS '총급여액 - 저장 후 산출';

COMMENT ON COLUMN year_end_result.determined_tax_amount IS '결정세액 - 저장 후 산출';

COMMENT ON COLUMN year_end_result.paid_tax_amount IS '기납부세액 - 저장 후 산출';

COMMENT ON COLUMN year_end_result.payable_tax_amount IS '납부세액 - 저장 후 산출. 분납 합계와 일치해야 함(여러 행 규칙, 확인 필요)';

COMMENT ON COLUMN year_end_result.closing_status IS '마감 상태 - (가정) 초기값: 정산 결과 생성→신청. 마감 후 수정 불가';

COMMENT ON COLUMN year_end_result.created_at IS '생성 일시';

COMMENT ON COLUMN year_end_result.updated_at IS '수정 일시';

CREATE TABLE year_end_installment (
    year_end_installment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    year_end_result_id BIGINT NOT NULL,
    installment_no INTEGER NOT NULL,
    installment_amount NUMERIC(18,2) NOT NULL,
    due_date DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_year_end_installment PRIMARY KEY (year_end_installment_id),
    CONSTRAINT uq_year_end_installment_year_end_result_id_installment_no UNIQUE (year_end_result_id, installment_no),
    CONSTRAINT ck_year_end_installment_installment_no_ge_1 CHECK (installment_no >= 1),
    CONSTRAINT ck_year_end_installment_installment_amount_gt_0 CHECK (installment_amount > 0)
);

COMMENT ON TABLE year_end_installment IS '연말정산 분납 - 한 행=정산 결과의 분납 회차 1건. 분납합계=납부세액.';

COMMENT ON COLUMN year_end_installment.year_end_installment_id IS '연말정산 분납 ID - 대리키';

COMMENT ON COLUMN year_end_installment.year_end_result_id IS '연말정산 결과';

COMMENT ON COLUMN year_end_installment.installment_no IS '분납 회차';

COMMENT ON COLUMN year_end_installment.installment_amount IS '분납 금액 - 분납 입력값. 회차별 합계=납부세액은 여러 행 규칙(확인 필요)';

COMMENT ON COLUMN year_end_installment.due_date IS '납부 예정일 - (가정) 선택값';

COMMENT ON COLUMN year_end_installment.created_at IS '생성 일시';

COMMENT ON COLUMN year_end_installment.updated_at IS '수정 일시';

CREATE TABLE purchase_asset_item (
    purchase_asset_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requisition_id BIGINT NOT NULL,
    asset_id BIGINT,
    item_name VARCHAR(200) NOT NULL,
    quantity INTEGER NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    asset_category VARCHAR(100),
    inspection_required BOOLEAN NOT NULL,
    inspection_completed BOOLEAN,
    asset_linked BOOLEAN NOT NULL,
    linked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_purchase_asset_item PRIMARY KEY (purchase_asset_item_id),
    CONSTRAINT ck_purchase_asset_item_asset_id_req CHECK (asset_linked NOT IN ('true') OR asset_id IS NOT NULL),
    CONSTRAINT ck_purchase_asset_item_quantity_gt_0 CHECK (quantity > 0),
    CONSTRAINT ck_purchase_asset_item_amount_ge_0 CHECK (amount >= 0)
);

COMMENT ON TABLE purchase_asset_item IS '구매품의 자산품목 - 한 행=구매품의서의 자산품목 1건. 수량, 금액, 검수 여부, 자산 등록 연계 여부(중복 연계 불가). 품의서 필수, 자산 선택.';

COMMENT ON COLUMN purchase_asset_item.purchase_asset_item_id IS '구매품의 자산품목 ID - 대리키';

COMMENT ON COLUMN purchase_asset_item.requisition_id IS '품의서';

COMMENT ON COLUMN purchase_asset_item.asset_id IS '자산 - 자산 등록 연계 후 채워짐';

COMMENT ON COLUMN purchase_asset_item.item_name IS '자산품목명 - (가정) 길이 200';

COMMENT ON COLUMN purchase_asset_item.quantity IS '수량';

COMMENT ON COLUMN purchase_asset_item.amount IS '금액 - (가정) 품목 금액 입력값';

COMMENT ON COLUMN purchase_asset_item.asset_category IS '자산 분류 - (확인 필요) 분류 코드 체계 미정';

COMMENT ON COLUMN purchase_asset_item.inspection_required IS '검수 필요 여부 - (가정) 입력 시 설정, 기본 false';

COMMENT ON COLUMN purchase_asset_item.inspection_completed IS '검수 완료 여부 - (가정) 검수 필요 품목에서 검수 후 채워짐';

COMMENT ON COLUMN purchase_asset_item.asset_linked IS '자산 등록 연계 여부 - (가정) 초기값 false, 연계 후 true. 중복 연계 불가';

COMMENT ON COLUMN purchase_asset_item.linked_at IS '자산 연계 일시 - 연계 처리 시 채워짐';

COMMENT ON COLUMN purchase_asset_item.created_at IS '생성 일시';

COMMENT ON COLUMN purchase_asset_item.updated_at IS '수정 일시';

CREATE TABLE asset_change (
    asset_change_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_id BIGINT NOT NULL,
    approval_document_id BIGINT,
    change_type VARCHAR(50) NOT NULL,
    change_date DATE NOT NULL,
    change_content TEXT NOT NULL,
    is_regular_change BOOLEAN NOT NULL,
    changed_by_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset_change PRIMARY KEY (asset_change_id)
);

COMMENT ON TABLE asset_change IS '자산 변동 이력 - 한 행=자산 변동 1건. 변동유형·일자·내용. 상시 변동 포함.';

COMMENT ON COLUMN asset_change.asset_change_id IS '자산 변동 이력 ID - 대리키';

COMMENT ON COLUMN asset_change.asset_id IS '자산';

COMMENT ON COLUMN asset_change.approval_document_id IS '전자결재 문서 - 결재 연계 사용 시에만 존재. 상시 변동은 NULL';

COMMENT ON COLUMN asset_change.change_type IS '변동 유형 - (확인 필요) 변동 유형 전체 목록 미정';

COMMENT ON COLUMN asset_change.change_date IS '변동 일자';

COMMENT ON COLUMN asset_change.change_content IS '변동 내용';

COMMENT ON COLUMN asset_change.is_regular_change IS '상시 변동 여부 - (가정) 실사 결과 차이로 반영된 상시 변동이면 true';

COMMENT ON COLUMN asset_change.changed_by_id IS '변경자 - (가정) 자동·외부 연계 시 NULL. 상위 employee가 카탈로그에 없음 (카탈로그 수정 필요)';

COMMENT ON COLUMN asset_change.created_at IS '생성 일시';

COMMENT ON COLUMN asset_change.updated_at IS '수정 일시';

CREATE TABLE asset_print_log (
    asset_print_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_id BIGINT NOT NULL,
    printed_by_id BIGINT NOT NULL,
    asset_number VARCHAR(50) NOT NULL,
    print_format VARCHAR(20) NOT NULL,
    printed_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset_print_log PRIMARY KEY (asset_print_log_id),
    CONSTRAINT ck_asset_print_log_print_format CHECK (print_format IN ('QR', 'BARCODE'))
);

COMMENT ON TABLE asset_print_log IS 'QR·바코드 출력 이력 - 한 행=출력 1건. 자산번호 기준.';

COMMENT ON COLUMN asset_print_log.asset_print_log_id IS 'QR·바코드 출력 이력 ID - 대리키';

COMMENT ON COLUMN asset_print_log.asset_id IS '자산 ID - 출력 대상 자산. 출력 시 입력으로 공급';

COMMENT ON COLUMN asset_print_log.printed_by_id IS '출력자 ID - 출력을 수행한 자산 담당자(임직원 계정)';

COMMENT ON COLUMN asset_print_log.asset_number IS '자산번호 - 출력 시점의 자산번호 값 스냅샷. QR·바코드 생성 기준이며 재출력 시 동일 값 사용 (가정: 길이 50, 선행 0 보존)';

COMMENT ON COLUMN asset_print_log.print_format IS '출력 형식 - (가정) 출력 형식은 QR·바코드 두 가지로 추정';

COMMENT ON COLUMN asset_print_log.printed_at IS '출력 일시 - 출력 사건 시각. 출력 시 시스템이 공급 (감사 컬럼과 별도)';

COMMENT ON COLUMN asset_print_log.created_at IS '생성 일시';

COMMENT ON COLUMN asset_print_log.updated_at IS '수정 일시';

CREATE TABLE asset_inspection_plan (
    asset_inspection_plan_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_document_id BIGINT,
    manager_id BIGINT NOT NULL,
    inspection_type VARCHAR(50) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    target_scope TEXT,
    approval_status VARCHAR(20) NOT NULL,
    progress_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset_inspection_plan PRIMARY KEY (asset_inspection_plan_id),
    CONSTRAINT ck_asset_inspection_plan_approval_status CHECK (approval_status IN ('신청', '승인', '승인 취소', '반려')),
    CONSTRAINT ck_asset_inspection_plan_progress_status CHECK (progress_status IN ('진행', '완료', '취소')),
    CONSTRAINT ck_asset_inspection_plan_end_date_gt_start_date CHECK (end_date > start_date)
);

COMMENT ON TABLE asset_inspection_plan IS '자산실사 계획 - 한 행=실사계획 1건. 유형, 기간(종료>시작), 승인 상태, 진행 상태.';

COMMENT ON COLUMN asset_inspection_plan.asset_inspection_plan_id IS '자산실사 계획 ID - 대리키';

COMMENT ON COLUMN asset_inspection_plan.approval_document_id IS '전자결재 문서 ID - 실사계획 결재 문서. 결재 연계 사용 여부는 환경설정에 따르므로 NULL 허용 (가정). 결재 상신 시 연결';

COMMENT ON COLUMN asset_inspection_plan.manager_id IS '실사 담당자 ID - 실사 담당자. 계획 등록 시 입력 (가정)';

COMMENT ON COLUMN asset_inspection_plan.inspection_type IS '실사 유형 - 실사 유형. 전체 유형 목록 미확인이라 허용값 미제한 (확인 필요)';

COMMENT ON COLUMN asset_inspection_plan.start_date IS '실사 시작일';

COMMENT ON COLUMN asset_inspection_plan.end_date IS '실사 종료일 - 시작일 이후여야 함';

COMMENT ON COLUMN asset_inspection_plan.target_scope IS '실사 대상 범위 - 대상 범위 조건 설명. 구조화 기준(부서·분류 등) 확인 필요 (확인 필요)';

COMMENT ON COLUMN asset_inspection_plan.approval_status IS '승인 처리 상태 - 공통 결정 ''승인 처리 상태''의 부분집합(마감·마감 취소 제외). 결재 결과 반영. (가정) 초기값 신청 (생성 시 신청으로 시작)';

COMMENT ON COLUMN asset_inspection_plan.progress_status IS '진행 상태 - (가정) 명세의 ''진행 중인 실사정보만 취소·삭제·완료'' 흐름에서 추론한 최소 상태. 초기값 진행';

COMMENT ON COLUMN asset_inspection_plan.created_at IS '생성 일시';

COMMENT ON COLUMN asset_inspection_plan.updated_at IS '수정 일시';

CREATE TABLE asset_inspection_item (
    asset_inspection_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_inspection_plan_id BIGINT NOT NULL,
    asset_id BIGINT NOT NULL,
    inspection_result VARCHAR(20),
    inspected_at TIMESTAMPTZ,
    remark TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_asset_inspection_item PRIMARY KEY (asset_inspection_item_id),
    CONSTRAINT uq_asset_inspection_item_asset_inspection_plan_id_asset_id UNIQUE (asset_inspection_plan_id, asset_id)
);

COMMENT ON TABLE asset_inspection_item IS '자산실사 결과 - 한 행=실사계획·자산별 실사 결과 1건.';

COMMENT ON COLUMN asset_inspection_item.asset_inspection_item_id IS '자산실사 결과 ID - 대리키';

COMMENT ON COLUMN asset_inspection_item.asset_inspection_plan_id IS '자산실사 계획 ID';

COMMENT ON COLUMN asset_inspection_item.asset_id IS '자산 ID';

COMMENT ON COLUMN asset_inspection_item.inspection_result IS '실사 결과 - 실사 후 외부 자산실사 시스템 연계로 채워지므로 NULL 허용. 허용 코드 미확정이라 값 제한 없음 (확인 필요)';

COMMENT ON COLUMN asset_inspection_item.inspected_at IS '실사 일시 - 저장 후 실사 처리 시 채워짐';

COMMENT ON COLUMN asset_inspection_item.remark IS '비고 - 실사 결과와 자산 현재 정보 차이 내용 등 (가정)';

COMMENT ON COLUMN asset_inspection_item.created_at IS '생성 일시';

COMMENT ON COLUMN asset_inspection_item.updated_at IS '수정 일시';

CREATE TABLE resource_category (
    resource_category_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(100) NOT NULL,
    sort_order INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_resource_category PRIMARY KEY (resource_category_id),
    CONSTRAINT ck_resource_category_sort_order_ge_0 CHECK (sort_order >= 0)
);

COMMENT ON TABLE resource_category IS '자원 분류 - 한 행=자원 분류 1개. 정렬 순서. 예약 존재 시 삭제 제한.';

COMMENT ON COLUMN resource_category.resource_category_id IS '자원 분류 ID - 대리키';

COMMENT ON COLUMN resource_category.name IS '분류명 - (가정) 길이 100';

COMMENT ON COLUMN resource_category.sort_order IS '정렬 순서 - (가정) 등록 시 입력 또는 기본 순번 공급';

COMMENT ON COLUMN resource_category.created_at IS '생성 일시';

COMMENT ON COLUMN resource_category.updated_at IS '수정 일시';

CREATE TABLE resource (
    resource_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    resource_category_id BIGINT NOT NULL,
    manager_id BIGINT,
    name VARCHAR(100) NOT NULL,
    approval_required VARCHAR(10) NOT NULL,
    visibility_scope VARCHAR(10) NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_resource PRIMARY KEY (resource_id),
    CONSTRAINT ck_resource_approval_required CHECK (approval_required IN ('사용', '미사용')),
    CONSTRAINT ck_resource_visibility_scope CHECK (visibility_scope IN ('전체', '부서', '개인')),
    CONSTRAINT uq_resource_resource_category_id_name UNIQUE (resource_category_id, name)
);

COMMENT ON TABLE resource IS '자원 - 한 행=자원 1개. 승인절차 사용 여부, 공개범위. 분류 필수, 담당자(임직원) 선택.';

COMMENT ON COLUMN resource.resource_id IS '자원 ID - 대리키';

COMMENT ON COLUMN resource.resource_category_id IS '자원 분류 ID';

COMMENT ON COLUMN resource.manager_id IS '담당자 ID - 선택 입력';

COMMENT ON COLUMN resource.name IS '자원명 - (가정) 길이 100';

COMMENT ON COLUMN resource.approval_required IS '승인절차 사용 여부 - ''사용''이면 예약 승인 필요, ''미사용''이면 자동 승인. (가정) 초기값 미사용';

COMMENT ON COLUMN resource.visibility_scope IS '공개범위 - 공통 결정 ''조회 범위'' 도메인 사용. (가정) 초기값 전체';

COMMENT ON COLUMN resource.description IS '자원 설명';

COMMENT ON COLUMN resource.created_at IS '생성 일시';

COMMENT ON COLUMN resource.updated_at IS '수정 일시';

CREATE TABLE resource_attribute (
    resource_attribute_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    resource_id BIGINT NOT NULL,
    attribute_name VARCHAR(100) NOT NULL,
    attribute_value VARCHAR(500) NOT NULL,
    sort_order INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_resource_attribute PRIMARY KEY (resource_attribute_id),
    CONSTRAINT uq_resource_attribute_resource_id_attribute_name UNIQUE (resource_id, attribute_name),
    CONSTRAINT ck_resource_attribute_sort_order_ge_0 CHECK (sort_order >= 0)
);

COMMENT ON TABLE resource_attribute IS '자원 속성 - 한 행=자원의 속성 1건(검색 필터).';

COMMENT ON COLUMN resource_attribute.resource_attribute_id IS '자원 속성 ID - 대리키';

COMMENT ON COLUMN resource_attribute.resource_id IS '자원';

COMMENT ON COLUMN resource_attribute.attribute_name IS '속성명 - 예약 조회 검색 필터의 속성 항목명 (가정: 길이 100)';

COMMENT ON COLUMN resource_attribute.attribute_value IS '속성값 - 검색 필터와 비교하는 속성 값 (가정: 길이 500)';

COMMENT ON COLUMN resource_attribute.sort_order IS '정렬 순서 - (가정) 미지정 시 기본 순서';

COMMENT ON COLUMN resource_attribute.created_at IS '생성 일시';

COMMENT ON COLUMN resource_attribute.updated_at IS '수정 일시';

CREATE TABLE resource_permission (
    resource_permission_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    resource_id BIGINT NOT NULL,
    department_id BIGINT,
    employee_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_resource_permission PRIMARY KEY (resource_permission_id),
    CONSTRAINT ck_resource_permission_one_department_id_employee_id CHECK ((CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

COMMENT ON TABLE resource_permission IS '자원 사용 권한 - 한 행=자원별 사용 권한 범위 1건(부서 또는 임직원).';

COMMENT ON COLUMN resource_permission.resource_permission_id IS '자원 사용 권한 ID - 대리키';

COMMENT ON COLUMN resource_permission.resource_id IS '자원';

COMMENT ON COLUMN resource_permission.department_id IS '부서 - 부서 단위 권한일 때 값 지정';

COMMENT ON COLUMN resource_permission.employee_id IS '임직원 - 임직원 단위 권한일 때 값 지정';

COMMENT ON COLUMN resource_permission.created_at IS '생성 일시';

COMMENT ON COLUMN resource_permission.updated_at IS '수정 일시';

CREATE TABLE resource_reservation (
    resource_reservation_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    resource_id BIGINT NOT NULL,
    reserver_id BIGINT NOT NULL,
    user_id BIGINT,
    start_at TIMESTAMPTZ NOT NULL,
    end_at TIMESTAMPTZ NOT NULL,
    content TEXT,
    repeat_type VARCHAR(20),
    repeat_until DATE,
    status VARCHAR(20) NOT NULL,
    reject_reason TEXT,
    processed_by BIGINT,
    processed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_resource_reservation PRIMARY KEY (resource_reservation_id),
    CONSTRAINT ck_resource_reservation_repeat_type CHECK (repeat_type IN ('NONE', 'DAILY', 'WEEKLY', 'MONTHLY')),
    CONSTRAINT ck_resource_reservation_status CHECK (status IN ('신청', '승인', '반려', '취소')),
    CONSTRAINT ck_resource_reservation_reject_reason_req CHECK (status NOT IN ('반려') OR reject_reason IS NOT NULL),
    CONSTRAINT ck_resource_reservation_end_at_ge_start_at CHECK (end_at >= start_at),
    CONSTRAINT ck_resource_reservation_repeat_until_ge_start_at CHECK (repeat_until >= start_at)
);

COMMENT ON TABLE resource_reservation IS '자원 예약 - 한 행=예약 1건. 기간(종료>=시작), 반복, 상태(신청/승인/반려/취소). 승인 예약과 시간 중복 불가.';

COMMENT ON COLUMN resource_reservation.resource_reservation_id IS '자원 예약 ID - 대리키';

COMMENT ON COLUMN resource_reservation.resource_id IS '자원';

COMMENT ON COLUMN resource_reservation.reserver_id IS '예약자 - 예약을 등록한 임직원';

COMMENT ON COLUMN resource_reservation.user_id IS '사용자 - 실제 사용자. 미지정 시 예약자가 사용 (가정)';

COMMENT ON COLUMN resource_reservation.start_at IS '시작 일시';

COMMENT ON COLUMN resource_reservation.end_at IS '종료 일시 - 시작 일시보다 빠를 수 없음';

COMMENT ON COLUMN resource_reservation.content IS '예약 내용 - (가정) 선택 입력';

COMMENT ON COLUMN resource_reservation.repeat_type IS '반복 유형 - (가정) 반복 설정의 전체 유형은 명세에 없어 최소 집합 추천. 미지정 시 NULL 또는 NONE';

COMMENT ON COLUMN resource_reservation.repeat_until IS '반복 종료일 - 반복 사용 시 종료일 (가정)';

COMMENT ON COLUMN resource_reservation.status IS '예약 상태 - 처음 상태는 신청. 초기값: 자원 승인 절차 미사용→승인(자동 승인). 승인 취소는 취소 상태로 반영 (가정: 승인취소를 취소로 매핑)';

COMMENT ON COLUMN resource_reservation.reject_reason IS '반려 사유 - 반려 시 필수';

COMMENT ON COLUMN resource_reservation.processed_by IS '처리자 - 승인·반려 처리한 자원 담당자. 자동 승인 시 NULL, 저장 후 처리';

COMMENT ON COLUMN resource_reservation.processed_at IS '처리 일시 - 저장 후 처리 시 기록';

COMMENT ON COLUMN resource_reservation.created_at IS '생성 일시';

COMMENT ON COLUMN resource_reservation.updated_at IS '수정 일시';

CREATE TABLE schedule (
    schedule_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    owner_id BIGINT NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    start_at TIMESTAMPTZ NOT NULL,
    end_at TIMESTAMPTZ NOT NULL,
    all_day BOOLEAN NOT NULL,
    location VARCHAR(200),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_schedule PRIMARY KEY (schedule_id),
    CONSTRAINT ck_schedule_end_at_ge_start_at CHECK (end_at >= start_at)
);

COMMENT ON TABLE schedule IS '일정 - 한 행=일정 1건. 소유 임직원 필수.';

COMMENT ON COLUMN schedule.schedule_id IS '일정 ID - 대리키';

COMMENT ON COLUMN schedule.owner_id IS '소유 임직원';

COMMENT ON COLUMN schedule.title IS '제목 - (가정) 길이 200';

COMMENT ON COLUMN schedule.content IS '내용';

COMMENT ON COLUMN schedule.start_at IS '시작 일시 - (가정) 일정 필수값';

COMMENT ON COLUMN schedule.end_at IS '종료 일시 - (가정) 일정 필수값';

COMMENT ON COLUMN schedule.all_day IS '종일 여부 - (가정) 기본 false';

COMMENT ON COLUMN schedule.location IS '장소 - (가정) 길이 200';

COMMENT ON COLUMN schedule.created_at IS '생성 일시';

COMMENT ON COLUMN schedule.updated_at IS '수정 일시';

CREATE TABLE board_post (
    board_post_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    author_id BIGINT NOT NULL,
    post_type VARCHAR(20) NOT NULL,
    category VARCHAR(100),
    title VARCHAR(300) NOT NULL,
    content TEXT NOT NULL,
    visibility_scope VARCHAR(20) NOT NULL,
    popup_start_date DATE,
    popup_end_date DATE,
    pin_start_date DATE,
    pin_end_date DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_board_post PRIMARY KEY (board_post_id),
    CONSTRAINT ck_board_post_post_type CHECK (post_type IN ('공지', '게시글')),
    CONSTRAINT ck_board_post_visibility_scope CHECK (visibility_scope IN ('전체', '부서', '개인')),
    CONSTRAINT ck_board_post_popup_end_date_ge_popup_start_date CHECK (popup_end_date >= popup_start_date),
    CONSTRAINT ck_board_post_pin_end_date_ge_pin_start_date CHECK (pin_end_date >= pin_start_date)
);

COMMENT ON TABLE board_post IS '공지·게시물 - 한 행=게시물 1건. 구분·분류, 공개범위, 팝업·상단고정 기간(시작<=종료). 작성자 필수.';

COMMENT ON COLUMN board_post.board_post_id IS '공지·게시물 ID - 대리키';

COMMENT ON COLUMN board_post.author_id IS '작성자';

COMMENT ON COLUMN board_post.post_type IS '구분 - (가정) 공지사항/게시글 구분만 확인됨';

COMMENT ON COLUMN board_post.category IS '분류 - (확인 필요) 분류 체계 미정의로 자유 텍스트 (가정)';

COMMENT ON COLUMN board_post.title IS '제목 - (가정) 길이 300';

COMMENT ON COLUMN board_post.content IS '내용 - (가정) 필수';

COMMENT ON COLUMN board_post.visibility_scope IS '공개범위 - 등록 시 필수. 조회 범위 공통 도메인 사용. 상세 대상은 post_audience로 관리';

COMMENT ON COLUMN board_post.popup_start_date IS '팝업공지 시작일 - 선택 설정';

COMMENT ON COLUMN board_post.popup_end_date IS '팝업공지 종료일 - 선택 설정. 시작일 설정 시 종료일도 필요 (가정)';

COMMENT ON COLUMN board_post.pin_start_date IS '상단 고정 시작일 - 선택 설정';

COMMENT ON COLUMN board_post.pin_end_date IS '상단 고정 종료일 - 선택 설정';

COMMENT ON COLUMN board_post.created_at IS '생성 일시';

COMMENT ON COLUMN board_post.updated_at IS '수정 일시';

CREATE TABLE post_audience (
    post_audience_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    board_post_id BIGINT NOT NULL,
    department_id BIGINT,
    employee_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_post_audience PRIMARY KEY (post_audience_id),
    CONSTRAINT uq_post_audience_board_post_id_department_id UNIQUE (board_post_id, department_id),
    CONSTRAINT uq_post_audience_board_post_id_employee_id UNIQUE (board_post_id, employee_id),
    CONSTRAINT ck_post_audience_one_department_id_employee_id CHECK ((CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

COMMENT ON TABLE post_audience IS '게시물 공개범위 대상 - 한 행=게시물 공개 대상 1건(부서 또는 임직원).';

COMMENT ON COLUMN post_audience.post_audience_id IS '게시물 공개범위 대상 ID - 대리키';

COMMENT ON COLUMN post_audience.board_post_id IS '게시물';

COMMENT ON COLUMN post_audience.department_id IS '공개 대상 부서 - 부서 단위 공개 시 사용. employee_id와 정확히 하나만 채움';

COMMENT ON COLUMN post_audience.employee_id IS '공개 대상 임직원 - 임직원 개별 공개 시 사용. department_id와 정확히 하나만 채움';

COMMENT ON COLUMN post_audience.created_at IS '생성 일시';

COMMENT ON COLUMN post_audience.updated_at IS '수정 일시';

CREATE TABLE post_read_log (
    post_read_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    board_post_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    read_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_post_read_log PRIMARY KEY (post_read_log_id),
    CONSTRAINT uq_post_read_log_board_post_id_employee_id UNIQUE (board_post_id, employee_id)
);

COMMENT ON TABLE post_read_log IS '게시물 열람 이력 - 한 행=게시물·임직원 열람 1건(열람 일시).';

COMMENT ON COLUMN post_read_log.post_read_log_id IS '게시물 열람 이력 ID - 대리키';

COMMENT ON COLUMN post_read_log.board_post_id IS '게시물';

COMMENT ON COLUMN post_read_log.employee_id IS '열람자';

COMMENT ON COLUMN post_read_log.read_at IS '열람 일시 - 상세 열람 시 자동 기록, 삽입 시 공급. 시간대 정책은 (확인 필요)';

COMMENT ON COLUMN post_read_log.created_at IS '생성 일시';

COMMENT ON COLUMN post_read_log.updated_at IS '수정 일시';

CREATE TABLE survey (
    survey_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    creator_id BIGINT NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    status VARCHAR(20) NOT NULL,
    comment_enabled BOOLEAN NOT NULL,
    result_public BOOLEAN NOT NULL,
    participant_public BOOLEAN NOT NULL,
    notification_channel VARCHAR(20),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey PRIMARY KEY (survey_id),
    CONSTRAINT ck_survey_status CHECK (status IN ('진행 전', '진행 중', '종료')),
    CONSTRAINT ck_survey_notification_channel CHECK (notification_channel IN ('메신저', '모바일', '대화방', '메일', '포털')),
    CONSTRAINT ck_survey_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE survey IS '설문조사 - 한 행=설문 1건. 기간(종료>=시작), 상태(진행 전/진행 중/종료), 댓글·결과·참여자 공개 여부, 알림 채널.';

COMMENT ON COLUMN survey.survey_id IS '설문조사 ID - 대리키';

COMMENT ON COLUMN survey.title IS '설문 제목 - (가정) 길이 200, 등록 시 필수';

COMMENT ON COLUMN survey.content IS '설문 내용 - (가정) 선택 입력';

COMMENT ON COLUMN survey.creator_id IS '작성자';

COMMENT ON COLUMN survey.start_date IS '설문 시작일 - (가정) 설문 기간 필수';

COMMENT ON COLUMN survey.end_date IS '설문 종료일 - (가정) 설문 기간 필수';

COMMENT ON COLUMN survey.status IS '진행상태 - 결정: 진행 전/진행 중/종료 세 가지. (가정) 등록 시 초기값은 진행 전, 기간 도래·경과에 따라 진행 중·종료로 변경';

COMMENT ON COLUMN survey.comment_enabled IS '댓글 사용 여부 - (가정) 등록 시 입력값 공급';

COMMENT ON COLUMN survey.result_public IS '결과 공개 여부 - (가정) 등록 시 입력값 공급';

COMMENT ON COLUMN survey.participant_public IS '참여자 정보 공개 여부 - (가정) 등록 시 입력값 공급';

COMMENT ON COLUMN survey.notification_channel IS '알림 채널 - (가정) 알림 발송 설정 시에만 선택. 단일 채널로 가정(복수 채널 필요 시 확인 필요)';

COMMENT ON COLUMN survey.created_at IS '생성 일시';

COMMENT ON COLUMN survey.updated_at IS '수정 일시';

CREATE TABLE survey_target (
    survey_target_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_target PRIMARY KEY (survey_target_id),
    CONSTRAINT uq_survey_target_survey_id_employee_id UNIQUE (survey_id, employee_id)
);

COMMENT ON TABLE survey_target IS '설문 대상 - 한 행=설문·임직원 1건. 설문당 1회 응답.';

COMMENT ON COLUMN survey_target.survey_target_id IS '설문 대상 ID - 대리키';

COMMENT ON COLUMN survey_target.survey_id IS '설문';

COMMENT ON COLUMN survey_target.employee_id IS '설문 대상 임직원';

COMMENT ON COLUMN survey_target.created_at IS '생성 일시';

COMMENT ON COLUMN survey_target.updated_at IS '수정 일시';

CREATE TABLE survey_question (
    survey_question_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_id BIGINT NOT NULL,
    title VARCHAR(500) NOT NULL,
    question_type VARCHAR(20) NOT NULL,
    answer_mode VARCHAR(20),
    other_opinion_enabled BOOLEAN NOT NULL,
    sort_order INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_question PRIMARY KEY (survey_question_id),
    CONSTRAINT ck_survey_question_question_type CHECK (question_type IN ('선택형', '주관식')),
    CONSTRAINT ck_survey_question_answer_mode CHECK (answer_mode IN ('단답', '다답')),
    CONSTRAINT ck_survey_question_answer_mode_req CHECK (question_type NOT IN ('선택형') OR answer_mode IS NOT NULL)
);

COMMENT ON TABLE survey_question IS '설문항목 - 한 행=설문 문항 1개. 유형(선택형/주관식), 단답/다답, 기타의견 여부.';

COMMENT ON COLUMN survey_question.survey_question_id IS '설문항목 ID - 대리키';

COMMENT ON COLUMN survey_question.survey_id IS '설문';

COMMENT ON COLUMN survey_question.title IS '문항 제목 - 길이는 (가정)';

COMMENT ON COLUMN survey_question.question_type IS '문항 유형';

COMMENT ON COLUMN survey_question.answer_mode IS '응답 방식 - 선택형 문항에서 사용. 주관식은 NULL (가정). 단답=하나만, 다답=복수 선택';

COMMENT ON COLUMN survey_question.other_opinion_enabled IS '기타 의견 입력 여부 - true일 때만 기타 의견 입력 가능. 기본 false는 (가정)';

COMMENT ON COLUMN survey_question.sort_order IS '문항 순서 - 표시 순서, 필요 시 사용 (가정)';

COMMENT ON COLUMN survey_question.created_at IS '생성 일시';

COMMENT ON COLUMN survey_question.updated_at IS '수정 일시';

CREATE TABLE survey_option (
    survey_option_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_question_id BIGINT NOT NULL,
    option_text VARCHAR(500) NOT NULL,
    sort_order INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_option PRIMARY KEY (survey_option_id),
    CONSTRAINT uq_survey_option_survey_question_id_option_text UNIQUE (survey_question_id, option_text),
    CONSTRAINT ck_survey_option_sort_order_ge_0 CHECK (sort_order >= 0)
);

COMMENT ON TABLE survey_option IS '설문 선택지 - 한 행=문항 선택지 1개. 선택형은 1개 이상.';

COMMENT ON COLUMN survey_option.survey_option_id IS '설문 선택지 ID - 대리키';

COMMENT ON COLUMN survey_option.survey_question_id IS '설문항목 ID';

COMMENT ON COLUMN survey_option.option_text IS '선택지 내용 - (가정) 길이 500';

COMMENT ON COLUMN survey_option.sort_order IS '표시 순서 - (가정) 미지정 시 등록순. 선택지 표시 순서';

COMMENT ON COLUMN survey_option.created_at IS '생성 일시';

COMMENT ON COLUMN survey_option.updated_at IS '수정 일시';

CREATE TABLE survey_response (
    survey_response_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_question_id BIGINT NOT NULL,
    respondent_id BIGINT NOT NULL,
    text_answer TEXT,
    other_opinion TEXT,
    submitted_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_response PRIMARY KEY (survey_response_id),
    CONSTRAINT uq_survey_response_survey_question_id_respondent_id UNIQUE (survey_question_id, respondent_id)
);

COMMENT ON TABLE survey_response IS '설문 응답 - 한 행=문항·응답자별 응답 1건. 주관식, 기타의견.';

COMMENT ON COLUMN survey_response.survey_response_id IS '설문 응답 ID - 대리키';

COMMENT ON COLUMN survey_response.survey_question_id IS '설문항목 ID';

COMMENT ON COLUMN survey_response.respondent_id IS '응답자 ID - 응답 제출 임직원. 참여자 정보 공개 여부는 설문 설정에 따라 표시 시점에 처리';

COMMENT ON COLUMN survey_response.text_answer IS '주관식 응답 - 주관식 문항에서만 필요. 문항 유형 조건은 다른 테이블 값이라 구조로 표현 불가 (확인 필요)';

COMMENT ON COLUMN survey_response.other_opinion IS '기타 의견 - 기타 의견 입력이 설정된 문항에서만 입력 가능. 다른 테이블 조건이라 구조로 표현 불가 (확인 필요)';

COMMENT ON COLUMN survey_response.submitted_at IS '응답 제출 시각 - 삽입 시 제출 시각 공급 (가정)';

COMMENT ON COLUMN survey_response.created_at IS '생성 일시';

COMMENT ON COLUMN survey_response.updated_at IS '수정 일시';

CREATE TABLE survey_response_option (
    survey_response_option_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_response_id BIGINT NOT NULL,
    survey_option_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_response_option PRIMARY KEY (survey_response_option_id),
    CONSTRAINT uq_survey_response_option_survey_response_id_survey_option_id UNIQUE (survey_response_id, survey_option_id)
);

COMMENT ON TABLE survey_response_option IS '설문 응답 선택지 - 한 행=응답에서 선택한 선택지 1건.';

COMMENT ON COLUMN survey_response_option.survey_response_option_id IS '설문 응답 선택지 ID - 대리키';

COMMENT ON COLUMN survey_response_option.survey_response_id IS '설문 응답 ID';

COMMENT ON COLUMN survey_response_option.survey_option_id IS '설문 선택지 ID - 응답 문항에 속한 선택지여야 함. 단답형은 1건, 다답형은 복수 허용은 여러 행 규칙이라 (확인 필요)';

COMMENT ON COLUMN survey_response_option.created_at IS '생성 일시';

COMMENT ON COLUMN survey_response_option.updated_at IS '수정 일시';

CREATE TABLE survey_comment (
    survey_comment_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    survey_id BIGINT NOT NULL,
    author_id BIGINT NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_survey_comment PRIMARY KEY (survey_comment_id)
);

COMMENT ON TABLE survey_comment IS '설문 댓글 - 한 행=설문 댓글 1건. 댓글 사용 설문만.';

COMMENT ON COLUMN survey_comment.survey_comment_id IS '설문 댓글 ID - 대리키';

COMMENT ON COLUMN survey_comment.survey_id IS '설문 ID - 댓글 사용 설문만 허용. 다른 테이블 조건이라 구조로 표현 불가 (확인 필요)';

COMMENT ON COLUMN survey_comment.author_id IS '작성자 ID - 댓글 작성 임직원 계정';

COMMENT ON COLUMN survey_comment.content IS '댓글 내용';

COMMENT ON COLUMN survey_comment.created_at IS '생성 일시';

COMMENT ON COLUMN survey_comment.updated_at IS '수정 일시';

CREATE TABLE messenger_room (
    messenger_room_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    creator_id BIGINT NOT NULL,
    room_name VARCHAR(200),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_messenger_room PRIMARY KEY (messenger_room_id)
);

COMMENT ON TABLE messenger_room IS '대화방 - 한 행=대화방 1개. 생성자(임직원) 관리.';

COMMENT ON COLUMN messenger_room.messenger_room_id IS '대화방 ID - 대리키';

COMMENT ON COLUMN messenger_room.creator_id IS '생성자 ID - 대화방 생성 임직원. 생성자가 등록·변경·삭제 관리';

COMMENT ON COLUMN messenger_room.room_name IS '대화방 이름 - (가정) 길이 200. 이름 미입력 대화방 가능 여부는 불명확하여 선택값으로 둠';

COMMENT ON COLUMN messenger_room.created_at IS '생성 일시';

COMMENT ON COLUMN messenger_room.updated_at IS '수정 일시';

CREATE TABLE messenger_room_member (
    messenger_room_member_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    messenger_room_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_messenger_room_member PRIMARY KEY (messenger_room_member_id),
    CONSTRAINT uq_messenger_room_member_messenger_room_id_employee_id UNIQUE (messenger_room_id, employee_id)
);

COMMENT ON TABLE messenger_room_member IS '대화방 참여자 - 한 행=대화방·임직원 1건.';

COMMENT ON COLUMN messenger_room_member.messenger_room_member_id IS '대화방 참여자 ID - 대리키';

COMMENT ON COLUMN messenger_room_member.messenger_room_id IS '대화방 ID';

COMMENT ON COLUMN messenger_room_member.employee_id IS '참여 임직원 ID - 대화방 참여자는 조직도의 임직원 중에서 선택';

COMMENT ON COLUMN messenger_room_member.created_at IS '생성 일시';

COMMENT ON COLUMN messenger_room_member.updated_at IS '수정 일시';

CREATE TABLE messenger_message (
    messenger_message_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    messenger_room_id BIGINT,
    sender_id BIGINT NOT NULL,
    reply_to_message_id BIGINT,
    message_type VARCHAR(20) NOT NULL,
    content TEXT,
    sent_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_messenger_message PRIMARY KEY (messenger_message_id),
    CONSTRAINT ck_messenger_message_message_type CHECK (message_type IN ('CHAT', 'NOTE'))
);

COMMENT ON TABLE messenger_message IS '메신저 메시지 - 한 행=쪽지·대화 메시지 1건. 발신자 필수, 대화방 선택(쪽지는 없음), 답장 원본 참조. 서버 저장.';

COMMENT ON COLUMN messenger_message.messenger_message_id IS '메신저 메시지 ID - 대리키';

COMMENT ON COLUMN messenger_message.messenger_room_id IS '대화방 ID - 쪽지는 대화방이 없으므로 NULL';

COMMENT ON COLUMN messenger_message.sender_id IS '발신자 ID - 발신자 필수';

COMMENT ON COLUMN messenger_message.reply_to_message_id IS '답장 원본 메시지 ID - 답장일 때만 원본 메시지를 참조. 자기 참조 FK이며 카탈로그 상위 엔티티에 없음(카탈로그 수정 필요)';

COMMENT ON COLUMN messenger_message.message_type IS '메시지 구분 - (가정) CHAT=대화방 메시지, NOTE=쪽지. 대화방이 있으면 CHAT, 없으면 NOTE';

COMMENT ON COLUMN messenger_message.content IS '메시지 내용 - (가정) 파일만 전송하는 경우 내용이 없을 수 있음';

COMMENT ON COLUMN messenger_message.sent_at IS '발송 일시 - 발송 시점에 서버에서 공급 (가정)';

COMMENT ON COLUMN messenger_message.created_at IS '생성 일시';

COMMENT ON COLUMN messenger_message.updated_at IS '수정 일시';

CREATE TABLE messenger_message_recipient (
    messenger_message_recipient_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    messenger_message_id BIGINT NOT NULL,
    recipient_id BIGINT NOT NULL,
    read_status VARCHAR(10) NOT NULL,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_messenger_message_recipient PRIMARY KEY (messenger_message_recipient_id),
    CONSTRAINT ck_messenger_message_recipient_read_status CHECK (read_status IN ('안읽음', '읽음')),
    CONSTRAINT uq_messenger_message_recipient_messenger_message_id_re_fa667b09 UNIQUE (messenger_message_id, recipient_id),
    CONSTRAINT ck_messenger_message_recipient_read_at_req CHECK (read_status NOT IN ('읽음') OR read_at IS NOT NULL)
);

COMMENT ON TABLE messenger_message_recipient IS '메시지 수신자 - 한 행=메시지·수신자 1건. 읽음 상태.';

COMMENT ON COLUMN messenger_message_recipient.messenger_message_recipient_id IS '메시지 수신자 ID - 대리키';

COMMENT ON COLUMN messenger_message_recipient.messenger_message_id IS '메시지 ID';

COMMENT ON COLUMN messenger_message_recipient.recipient_id IS '수신자 ID - 부서 선택 시 소속 임직원 전원이 개별 수신자 행으로 전개됨';

COMMENT ON COLUMN messenger_message_recipient.read_status IS '읽음 상태 - 공통 결정 읽음 상태 도메인. 수신자 행 생성 시 안읽음으로 시작(가정)';

COMMENT ON COLUMN messenger_message_recipient.read_at IS '읽은 일시 - 수신자가 확인한 뒤 채워짐';

COMMENT ON COLUMN messenger_message_recipient.created_at IS '생성 일시';

COMMENT ON COLUMN messenger_message_recipient.updated_at IS '수정 일시';

CREATE TABLE auth_setting (
    auth_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT,
    allowed_device_count INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_auth_setting PRIMARY KEY (auth_setting_id),
    CONSTRAINT ck_auth_setting_allowed_device_count_ge_0 CHECK (allowed_device_count >= 0)
);

COMMENT ON TABLE auth_setting IS '인증 설정 - 한 행=인증 대상 임직원별 허용 인증기기 수(0 이상). 대상 없음=기본 설정(가정).';

COMMENT ON COLUMN auth_setting.auth_setting_id IS '인증 설정 ID - 대리키';

COMMENT ON COLUMN auth_setting.employee_id IS '인증 대상 임직원 ID - NULL이면 기본 설정(가정). 대상별 1건이므로 유일. 기본 설정 행의 중복 방지는 (확인 필요)';

COMMENT ON COLUMN auth_setting.allowed_device_count IS '허용 인증기기 수 - 0 이상의 정수. 변경값은 이후 로그인·기기 승인부터 적용';

COMMENT ON COLUMN auth_setting.created_at IS '생성 일시';

COMMENT ON COLUMN auth_setting.updated_at IS '수정 일시';

CREATE TABLE auth_device (
    auth_device_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    device_identifier VARCHAR(200) NOT NULL,
    device_name VARCHAR(100),
    otp_enabled BOOLEAN NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    use_status VARCHAR(10) NOT NULL,
    approver_id BIGINT,
    processed_at TIMESTAMPTZ,
    reject_reason VARCHAR(500),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_auth_device PRIMARY KEY (auth_device_id),
    CONSTRAINT ck_auth_device_approval_status CHECK (approval_status IN ('신청', '승인', '반려')),
    CONSTRAINT ck_auth_device_use_status CHECK (use_status IN ('사용', '미사용')),
    CONSTRAINT ck_auth_device_reject_reason_req CHECK (approval_status NOT IN ('반려') OR reject_reason IS NOT NULL),
    CONSTRAINT ck_auth_device_approver_id_req CHECK (approval_status NOT IN ('승인', '반려') OR approver_id IS NOT NULL),
    CONSTRAINT ck_auth_device_processed_at_req CHECK (approval_status NOT IN ('승인', '반려') OR processed_at IS NOT NULL)
);

COMMENT ON TABLE auth_device IS '인증기기 - 한 행=임직원 인증기기 1대. OTP 기준, 승인 상태, 사용 여부.';

COMMENT ON COLUMN auth_device.auth_device_id IS '인증기기 ID - 대리키';

COMMENT ON COLUMN auth_device.employee_id IS '임직원 ID - 기기 소유 임직원(요청자)';

COMMENT ON COLUMN auth_device.device_identifier IS '기기 식별정보 - (가정) 길이 200. 기기 식별정보 원문 저장 여부는 (확인 필요)';

COMMENT ON COLUMN auth_device.device_name IS '기기명 - (가정)';

COMMENT ON COLUMN auth_device.otp_enabled IS 'OTP 사용 기기 여부 - 2차 인증 수단은 OTP이며 승인은 OTP 사용 기기 기준 (가정) 등록 시 공급';

COMMENT ON COLUMN auth_device.approval_status IS '승인 상태 - 공통 승인 처리 상태 도메인의 부분집합 (가정). 등록 요청 시 신청으로 시작';

COMMENT ON COLUMN auth_device.use_status IS '사용 여부 - (가정) 미사용 기기는 로그인 불가. 초기값 사용은 가정이며 승인 전에는 로그인 불가';

COMMENT ON COLUMN auth_device.approver_id IS '처리자 ID - 시스템 관리자가 승인·반려 후 채워짐 (카탈로그 상위 employee와 동일 대상, 역할 FK)';

COMMENT ON COLUMN auth_device.processed_at IS '처리 일시 - 승인·반려 후 산출';

COMMENT ON COLUMN auth_device.reject_reason IS '반려 사유 - (가정) 길이 500';

COMMENT ON COLUMN auth_device.created_at IS '생성 일시';

COMMENT ON COLUMN auth_device.updated_at IS '수정 일시';

CREATE TABLE menu_usage_log (
    menu_usage_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    menu_id BIGINT NOT NULL,
    used_at TIMESTAMPTZ NOT NULL,
    access_ip VARCHAR(45) NOT NULL,
    usage_environment VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_menu_usage_log PRIMARY KEY (menu_usage_log_id),
    CONSTRAINT ck_menu_usage_log_usage_environment CHECK (usage_environment IN ('웹', '모바일'))
);

COMMENT ON TABLE menu_usage_log IS '메뉴 사용 이력 - 한 행=메뉴 사용 1건. 일시, 접속 IP, 사용 환경(웹/모바일).';

COMMENT ON COLUMN menu_usage_log.menu_usage_log_id IS '메뉴 사용 이력 ID - 대리키';

COMMENT ON COLUMN menu_usage_log.employee_id IS '임직원 ID - 메뉴를 사용한 임직원. 사용 시 시스템이 자동 기록';

COMMENT ON COLUMN menu_usage_log.menu_id IS '메뉴 ID';

COMMENT ON COLUMN menu_usage_log.used_at IS '사용일시 - 메뉴를 연 시각. 기록 시 시스템이 공급. 감사 컬럼과 별도 사건 시각';

COMMENT ON COLUMN menu_usage_log.access_ip IS '접속 IP - (가정) IPv6 수용 길이 45';

COMMENT ON COLUMN menu_usage_log.usage_environment IS '사용 환경 - 웹/모바일 구분 조회용. 로그인 구분의 ''메신저/모바일 앱''과는 별개 도메인(확인 필요) 공통 도메인 조정: 메뉴 사용 환경은 웹/모바일만 명시됨';

COMMENT ON COLUMN menu_usage_log.created_at IS '생성 일시';

COMMENT ON COLUMN menu_usage_log.updated_at IS '수정 일시';

CREATE TABLE approval_line (
    approval_line_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_document_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    approval_order INTEGER NOT NULL,
    approval_status VARCHAR(20) NOT NULL,
    opinion TEXT,
    processed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_approval_line PRIMARY KEY (approval_line_id),
    CONSTRAINT ck_approval_line_approval_status CHECK (approval_status IN ('결재대기', '승인', '보류', '반려')),
    CONSTRAINT uq_approval_line_approval_document_id_approval_order UNIQUE (approval_document_id, approval_order),
    CONSTRAINT ck_approval_line_processed_at_req CHECK (approval_status NOT IN ('승인', '보류', '반려') OR processed_at IS NOT NULL),
    CONSTRAINT ck_approval_line_approval_order_gt_0 CHECK (approval_order > 0)
);

COMMENT ON TABLE approval_line IS '결재선 - 한 행=결재문서의 결재자 1명(순서, 결재 상태·의견).';

COMMENT ON COLUMN approval_line.approval_line_id IS '결재선 ID - 대리키';

COMMENT ON COLUMN approval_line.approval_document_id IS '전자결재 문서 ID';

COMMENT ON COLUMN approval_line.employee_id IS '결재자 ID - 결재자 계정';

COMMENT ON COLUMN approval_line.approval_order IS '결재 순서 - 1부터 시작. 상신 시 결재선과 함께 공급(가정)';

COMMENT ON COLUMN approval_line.approval_status IS '결재 상태 - (가정) 전자결재 처리 상태 중 결재자 개별 처리에 해당하는 부분집합. 초기값: 결재 차례 도래 전·후 모두 결재대기로 생성(가정, 차례 구분 필요 시 확인 필요)';

COMMENT ON COLUMN approval_line.opinion IS '결재 의견 - 처리 시 입력하는 선택값';

COMMENT ON COLUMN approval_line.processed_at IS '처리일시 - 저장 후 결재 처리 시 채워짐';

COMMENT ON COLUMN approval_line.created_at IS '생성 일시';

COMMENT ON COLUMN approval_line.updated_at IS '수정 일시';

CREATE TABLE document_numbering_rule (
    document_numbering_rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    department_id BIGINT NOT NULL,
    document_number VARCHAR(50) NOT NULL,
    number_prefix VARCHAR(30),
    last_sequence INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_document_numbering_rule PRIMARY KEY (document_numbering_rule_id),
    CONSTRAINT uq_document_numbering_rule_document_number UNIQUE (document_number),
    CONSTRAINT ck_document_numbering_rule_last_sequence_ge_0 CHECK (last_sequence >= 0)
);

COMMENT ON TABLE document_numbering_rule IS '문서번호 채번 기준 - 한 행=기안 부서별 채번 기준 1건. 번호 유일.';

COMMENT ON COLUMN document_numbering_rule.document_numbering_rule_id IS '문서번호 채번 기준 ID - 대리키';

COMMENT ON COLUMN document_numbering_rule.department_id IS '기안 부서 ID - 기안 부서별 채번 기준 1건(가정: 부서당 1건이 아닐 수 있어 유일 제약 미적용)';

COMMENT ON COLUMN document_numbering_rule.document_number IS '문서번호 - 번호 유일. 기안 시점에 채번. 기록물관리법 형식(확인 필요). 길이 가정';

COMMENT ON COLUMN document_numbering_rule.number_prefix IS '번호 접두 - (가정) 채번 형식 구성값';

COMMENT ON COLUMN document_numbering_rule.last_sequence IS '최종 일련번호 - (가정) 채번 후 갱신되는 값';

COMMENT ON COLUMN document_numbering_rule.created_at IS '생성 일시';

COMMENT ON COLUMN document_numbering_rule.updated_at IS '수정 일시';

CREATE TABLE approval_linked_form (
    approval_linked_form_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    approval_form_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_approval_linked_form PRIMARY KEY (approval_linked_form_id)
);

COMMENT ON TABLE approval_linked_form IS '연동결재 대상 양식 - 한 행=연동결재 대상으로 등록한 결재양식 1건.';

COMMENT ON COLUMN approval_linked_form.approval_linked_form_id IS '연동결재 대상 양식 ID - 대리키';

COMMENT ON COLUMN approval_linked_form.approval_form_id IS '결재양식 ID - 연동결재 대상 등록 양식. 양식당 1건(가정)';

COMMENT ON COLUMN approval_linked_form.created_at IS '생성 일시';

COMMENT ON COLUMN approval_linked_form.updated_at IS '수정 일시';

CREATE TABLE approval_handover (
    approval_handover_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    from_employee_id BIGINT NOT NULL,
    to_employee_id BIGINT NOT NULL,
    reason VARCHAR(500) NOT NULL,
    document_scope VARCHAR(1000) NOT NULL,
    handed_over_at TIMESTAMPTZ NOT NULL,
    handled_by_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_approval_handover PRIMARY KEY (approval_handover_id),
    CONSTRAINT ck_approval_handover_to_employee_id_ne_from_employee_id CHECK (to_employee_id <> from_employee_id)
);

COMMENT ON TABLE approval_handover IS '결재문서 인수인계 - 한 행=인수인계 1건. 인계자·인수자(임직원), 사유, 문서 범위.';

COMMENT ON COLUMN approval_handover.approval_handover_id IS '결재문서 인수인계 ID - 대리키';

COMMENT ON COLUMN approval_handover.from_employee_id IS '인계자 ID';

COMMENT ON COLUMN approval_handover.to_employee_id IS '인수자 ID';

COMMENT ON COLUMN approval_handover.reason IS '인수인계 사유 - 입·퇴사, 부서 통폐합 등 (전체 분류 미확정, 자유 입력 가정)';

COMMENT ON COLUMN approval_handover.document_scope IS '문서 범위 - (가정) 대상 문서 범위 조건 설명. 개별 문서 관리가 필요하면 별도 엔티티 필요(확인 필요)';

COMMENT ON COLUMN approval_handover.handed_over_at IS '인수인계일시 - 인수인계 처리 시각. 관리자 실행 시 공급';

COMMENT ON COLUMN approval_handover.handled_by_id IS '처리자 ID - 처리한 시스템 관리자 계정(카탈로그 parents에 역할 FK 없음 (카탈로그 수정 필요))';

COMMENT ON COLUMN approval_handover.created_at IS '생성 일시';

COMMENT ON COLUMN approval_handover.updated_at IS '수정 일시';

CREATE TABLE document_box (
    document_box_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(200) NOT NULL,
    employee_id BIGINT,
    department_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_document_box PRIMARY KEY (document_box_id),
    CONSTRAINT ck_document_box_one_employee_id_department_id CHECK ((CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

COMMENT ON TABLE document_box IS '문서함 - 한 행=문서함 1개. 개인(임직원) 또는 부서 소유.';

COMMENT ON COLUMN document_box.document_box_id IS '문서함 ID - 대리키';

COMMENT ON COLUMN document_box.name IS '문서함 이름 - (가정) 길이 200';

COMMENT ON COLUMN document_box.employee_id IS '소유 임직원 - 개인문서함이면 소유 임직원. 부서문서함이면 NULL';

COMMENT ON COLUMN document_box.department_id IS '소유 부서 - 부서문서함이면 소유 부서. 개인문서함이면 NULL';

COMMENT ON COLUMN document_box.created_at IS '생성 일시';

COMMENT ON COLUMN document_box.updated_at IS '수정 일시';

CREATE TABLE document_box_item (
    document_box_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    document_box_id BIGINT NOT NULL,
    approval_document_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_document_box_item PRIMARY KEY (document_box_item_id),
    CONSTRAINT uq_document_box_item_document_box_id_approval_document_id UNIQUE (document_box_id, approval_document_id)
);

COMMENT ON TABLE document_box_item IS '문서함 문서 - 한 행=문서함·결재문서 1건.';

COMMENT ON COLUMN document_box_item.document_box_item_id IS '문서함 문서 ID - 대리키';

COMMENT ON COLUMN document_box_item.document_box_id IS '문서함';

COMMENT ON COLUMN document_box_item.approval_document_id IS '전자결재 문서 - 완료 시점에 지정 문서함으로 자동 이관된 결재문서';

COMMENT ON COLUMN document_box_item.created_at IS '생성 일시';

COMMENT ON COLUMN document_box_item.updated_at IS '수정 일시';

CREATE TABLE document_dispatch_rule (
    document_dispatch_rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    document_type VARCHAR(100) NOT NULL,
    department_id BIGINT NOT NULL,
    confidence_threshold NUMERIC(18,2),
    usage_status VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_document_dispatch_rule PRIMARY KEY (document_dispatch_rule_id),
    CONSTRAINT ck_document_dispatch_rule_usage_status CHECK (usage_status IN ('사용', '미사용')),
    CONSTRAINT uq_document_dispatch_rule_document_type_department_id UNIQUE (document_type, department_id),
    CONSTRAINT ck_document_dispatch_rule_confidence_threshold_ge_0 CHECK (confidence_threshold >= 0),
    CONSTRAINT ck_document_dispatch_rule_confidence_threshold_le_1 CHECK (confidence_threshold <= 1)
);

COMMENT ON TABLE document_dispatch_rule IS '문서유형별 담당부서 배분 기준 - 한 행=문서유형별 담당 부서 1건(사전 설정).';

COMMENT ON COLUMN document_dispatch_rule.document_dispatch_rule_id IS '문서유형별 담당부서 배분 기준 ID - 대리키';

COMMENT ON COLUMN document_dispatch_rule.document_type IS '문서 유형 - (가정) 문서 유형 전체 목록이 확정되지 않아 allowed_values를 두지 않음. 길이 100';

COMMENT ON COLUMN document_dispatch_rule.department_id IS '담당 부서';

COMMENT ON COLUMN document_dispatch_rule.confidence_threshold IS '분류 신뢰도 기준 - (가정) 이 값보다 낮은 신뢰도의 문서는 자동 배분하지 않고 수동 지정 대상으로 남김. 0~1 범위 (확인 필요)';

COMMENT ON COLUMN document_dispatch_rule.usage_status IS '사용 여부 - (가정) 공통 도메인 사용 여부. 등록 시 기본값 사용';

COMMENT ON COLUMN document_dispatch_rule.created_at IS '생성 일시';

COMMENT ON COLUMN document_dispatch_rule.updated_at IS '수정 일시';

CREATE TABLE office_template (
    office_template_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    name VARCHAR(200) NOT NULL,
    template_type VARCHAR(255) NOT NULL,
    body_content TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_office_template PRIMARY KEY (office_template_id),
    CONSTRAINT ck_office_template_template_type CHECK (template_type IN ('REPORT', 'PROPOSAL'))
);

COMMENT ON TABLE office_template IS '웹 오피스 템플릿 - 한 행=템플릿 1개(보고서/기획서).';

COMMENT ON COLUMN office_template.office_template_id IS '웹 오피스 템플릿 ID - 대리키';

COMMENT ON COLUMN office_template.name IS '템플릿 이름 - (가정) 길이 200';

COMMENT ON COLUMN office_template.template_type IS '템플릿 구분 - REPORT=보고서, PROPOSAL=기획서';

COMMENT ON COLUMN office_template.body_content IS '양식 본문 - (가정) 선택 시 새 문서 생성에 사용하는 양식 본문';

COMMENT ON COLUMN office_template.created_at IS '생성 일시';

COMMENT ON COLUMN office_template.updated_at IS '수정 일시';

CREATE TABLE office_document (
    office_document_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    title VARCHAR(300) NOT NULL,
    author_id BIGINT NOT NULL,
    office_template_id BIGINT,
    body TEXT,
    chart_type VARCHAR(255),
    chart_data JSONB,
    ecm_document_id VARCHAR(200),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_office_document PRIMARY KEY (office_document_id),
    CONSTRAINT ck_office_document_chart_type CHECK (chart_type IN ('BAR', 'LINE', 'PIE')),
    CONSTRAINT ck_office_document_chart_data_req CHECK (chart_type NOT IN ('BAR', 'LINE', 'PIE') OR chart_data IS NOT NULL)
);

COMMENT ON TABLE office_document IS '웹 오피스 문서 - 한 행=문서 1건. 작성자 필수, 템플릿 선택, 차트 유형·데이터, ECM 참조.';

COMMENT ON COLUMN office_document.office_document_id IS '웹 오피스 문서 ID - 대리키';

COMMENT ON COLUMN office_document.title IS '문서 제목 - (가정) 길이 300';

COMMENT ON COLUMN office_document.author_id IS '작성자 - 작성자 필수. 변환 문서는 업로드한 사용자';

COMMENT ON COLUMN office_document.office_template_id IS '템플릿 - 템플릿 선택은 선택 사항';

COMMENT ON COLUMN office_document.body IS '문서 본문 - (가정) 본문 저장 위치(DB 또는 ECM)는 확인 필요';

COMMENT ON COLUMN office_document.chart_type IS '차트 유형 - BAR=막대형, LINE=선형, PIE=원형. 차트 미사용 시 NULL';

COMMENT ON COLUMN office_document.chart_data IS '차트 데이터 - 차트 유형 선택 시 필수';

COMMENT ON COLUMN office_document.ecm_document_id IS 'ECM 문서 식별자 - (가정) 문서 저장 후 ECM 연계 완료 시 채워지는 참조값. 길이 200';

COMMENT ON COLUMN office_document.created_at IS '생성 일시';

COMMENT ON COLUMN office_document.updated_at IS '수정 일시';

CREATE TABLE office_document_share (
    office_document_share_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    office_document_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    can_edit BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_office_document_share PRIMARY KEY (office_document_share_id),
    CONSTRAINT uq_office_document_share_office_document_id_employee_id UNIQUE (office_document_id, employee_id)
);

COMMENT ON TABLE office_document_share IS '문서 공유 권한 - 한 행=문서·사용자 공유 1건. 열람/수정 권한(수정은 열람 전제).';

COMMENT ON COLUMN office_document_share.office_document_share_id IS '문서 공유 권한 ID - 대리키';

COMMENT ON COLUMN office_document_share.office_document_id IS '웹 오피스 문서 ID';

COMMENT ON COLUMN office_document_share.employee_id IS '공유 대상자 ID - 공유 대상은 그룹웨어 사용자로 한정';

COMMENT ON COLUMN office_document_share.can_edit IS '수정 권한 여부 - 수정 권한 부여 여부. 열람 권한은 공유 행 존재로 부여되며 수정은 열람 전제. (가정) 기본 false, INSERT 시 공급';

COMMENT ON COLUMN office_document_share.created_at IS '생성 일시';

COMMENT ON COLUMN office_document_share.updated_at IS '수정 일시';

CREATE TABLE fee_unit_price (
    fee_unit_price_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fee_type VARCHAR(20) NOT NULL,
    unit_price NUMERIC(18,2) NOT NULL,
    effective_from DATE NOT NULL,
    effective_to DATE,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fee_unit_price PRIMARY KEY (fee_unit_price_id),
    CONSTRAINT ck_fee_unit_price_fee_type CHECK (fee_type IN ('REVIEW', 'REISSUE')),
    CONSTRAINT ck_fee_unit_price_unit_price_ge_0 CHECK (unit_price >= 0),
    CONSTRAINT ck_fee_unit_price_effective_to_ge_effective_from CHECK (effective_to >= effective_from)
);

COMMENT ON TABLE fee_unit_price IS '수수료 단가 - 한 행=수수료구분(심사/재발급)별 단가·적용기간 1건. 변경은 이후 등록분부터.';

COMMENT ON COLUMN fee_unit_price.fee_unit_price_id IS '수수료 단가 ID - 대리키';

COMMENT ON COLUMN fee_unit_price.fee_type IS '수수료 구분 - 심사수수료/재발급 수수료 구분. (가정) 신규 내부 코드로 REVIEW=심사, REISSUE=재발급';

COMMENT ON COLUMN fee_unit_price.unit_price IS '단가 - 수수료 단가. (확인 필요) 정밀도는 현행 소스 분석 결과에 따름';

COMMENT ON COLUMN fee_unit_price.effective_from IS '적용 시작일 - (가정) 적용 기간 시작일은 필수';

COMMENT ON COLUMN fee_unit_price.effective_to IS '적용 종료일 - (가정) 종료일 미정(현행 단가)이면 NULL. (확인 필요) 동일 구분 내 적용 기간 중복 금지는 스키마로 표현 불가, 현행 소스 분석 후 확정';

COMMENT ON COLUMN fee_unit_price.created_at IS '생성 일시';

COMMENT ON COLUMN fee_unit_price.updated_at IS '수정 일시';

CREATE TABLE fee_record (
    fee_record_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    fee_unit_price_id BIGINT NOT NULL,
    review_date DATE,
    resolution_date DATE,
    quantity INTEGER NOT NULL,
    amount NUMERIC(18,2) NOT NULL,
    is_offline BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_fee_record PRIMARY KEY (fee_record_id),
    CONSTRAINT ck_fee_record_quantity_gt_0 CHECK (quantity > 0),
    CONSTRAINT ck_fee_record_amount_ge_0 CHECK (amount >= 0)
);

COMMENT ON TABLE fee_record IS '수수료 등록 - 한 행=심사/재발급 수수료 등록 1건. 심사·결의일자, 수량, 금액(단가 기준), 오프라인 여부.';

COMMENT ON COLUMN fee_record.fee_record_id IS '수수료 등록 ID - 대리키';

COMMENT ON COLUMN fee_record.fee_unit_price_id IS '수수료 단가 ID - 등록 시점에 적용된 단가. 단가 변경 시 기존 등록 건 소급 변경 없음';

COMMENT ON COLUMN fee_record.review_date IS '심사일자 - (가정) 심사 수수료에서 사용, 재발급이면 NULL';

COMMENT ON COLUMN fee_record.resolution_date IS '결의일자 - (가정) 결의일자 기준 조회용, 선택값. (확인 필요) 필수 여부는 현행 소스 분석 후 확정';

COMMENT ON COLUMN fee_record.quantity IS '수량 - (가정) 등록 시 입력 필수';

COMMENT ON COLUMN fee_record.amount IS '금액 - 삽입 전 산출·공급: 등록된 단가×수량 기준으로 등록 시 산정하여 저장. 소급 변경 없음';

COMMENT ON COLUMN fee_record.is_offline IS '오프라인 여부 - 심사수수료 등록(오프라인) 메뉴 구분. (가정) 기본 false, 등록 시 공급';

COMMENT ON COLUMN fee_record.created_at IS '생성 일시';

COMMENT ON COLUMN fee_record.updated_at IS '수정 일시';

CREATE TABLE api_client (
    api_client_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    client_code VARCHAR(50) NOT NULL,
    name VARCHAR(100) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_api_client PRIMARY KEY (api_client_id),
    CONSTRAINT uq_api_client_client_code UNIQUE (client_code),
    CONSTRAINT ck_api_client_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE api_client IS '연계 시스템 - 한 행=API 호출 허용 등록 시스템 1개(Tcon, WTA 사이버연수원). 미등록 호출 불가.';

COMMENT ON COLUMN api_client.api_client_id IS '연계 시스템 ID - 대리키';

COMMENT ON COLUMN api_client.client_code IS '시스템 식별자 - API 요청 시스템 식별자. (가정) 시스템별 유일';

COMMENT ON COLUMN api_client.name IS '시스템명 - Tcon, WTA 사이버연수원 중 하나. (가정) 길이 100';

COMMENT ON COLUMN api_client.use_yn IS 'API 사용 여부 - 공통 결정의 사용 여부 도메인. (가정) 초기값 사용. 미등록·미사용 시스템 호출은 불가';

COMMENT ON COLUMN api_client.created_at IS '생성 일시';

COMMENT ON COLUMN api_client.updated_at IS '수정 일시';

CREATE TABLE interface_standard (
    interface_standard_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    api_client_id BIGINT NOT NULL,
    interface_items TEXT NOT NULL,
    link_method VARCHAR(100) NOT NULL,
    standard_version VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_interface_standard PRIMARY KEY (interface_standard_id),
    CONSTRAINT uq_interface_standard_api_client_id_standard_version_l_3e9b3117 UNIQUE (api_client_id, standard_version, link_method)
);

COMMENT ON TABLE interface_standard IS '연계 인터페이스 표준 - 한 행=대상 시스템별 표준 1건(연계 항목·방식·버전).';

COMMENT ON COLUMN interface_standard.interface_standard_id IS '연계 인터페이스 표준 ID - 대리키';

COMMENT ON COLUMN interface_standard.api_client_id IS '연계 시스템 ID';

COMMENT ON COLUMN interface_standard.interface_items IS '연계 정보 항목 - 연계 대상 정보 항목 기술. (가정) 표준 1건의 항목 정의 텍스트. (확인 필요) 항목을 개별 관리해야 하면 별도 엔티티 필요(카탈로그 수정 필요)';

COMMENT ON COLUMN interface_standard.link_method IS '연계 방식 - (가정) 연계 방식은 자유 기술, 전체 목록 미확정';

COMMENT ON COLUMN interface_standard.standard_version IS '표준 버전 - (가정) 길이 20';

COMMENT ON COLUMN interface_standard.created_at IS '생성 일시';

COMMENT ON COLUMN interface_standard.updated_at IS '수정 일시';

CREATE TABLE api_call_log (
    api_call_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    api_client_id BIGINT,
    interface_standard_id BIGINT,
    called_at TIMESTAMPTZ NOT NULL,
    request_system_identifier VARCHAR(100),
    result_status VARCHAR(20) NOT NULL,
    http_status_code INTEGER,
    error_code VARCHAR(50),
    error_message VARCHAR(1000),
    response_ms INTEGER,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_api_call_log PRIMARY KEY (api_call_log_id),
    CONSTRAINT ck_api_call_log_result_status CHECK (result_status IN ('성공', '실패')),
    CONSTRAINT ck_api_call_log_error_code_req CHECK (result_status NOT IN ('실패') OR error_code IS NOT NULL),
    CONSTRAINT ck_api_call_log_response_ms_ge_0 CHECK (response_ms >= 0)
);

COMMENT ON TABLE api_call_log IS 'API 호출 이력 - 한 행=API 호출 1건. 결과, 오류.';

COMMENT ON COLUMN api_call_log.api_call_log_id IS 'API 호출 이력 ID - 대리키';

COMMENT ON COLUMN api_call_log.api_client_id IS '연계 시스템 - 등록되지 않은 시스템의 호출도 이력으로 남길 수 있어 NULL 허용 (가정). 식별 불가 시 NULL';

COMMENT ON COLUMN api_call_log.interface_standard_id IS '연계 인터페이스 표준 - 요청이 표준과 매칭되지 않으면 NULL (가정)';

COMMENT ON COLUMN api_call_log.called_at IS '호출 일시 - 호출 수신 시점, 삽입 시 공급 (가정)';

COMMENT ON COLUMN api_call_log.request_system_identifier IS '요청 시스템 식별자 - 입력된 API 요청 시스템 식별자 원문 (가정 길이)';

COMMENT ON COLUMN api_call_log.result_status IS '호출 결과 - (가정) 최소 결과 집합. 호출 결과 기록 시 삽입 공급. 초기값: 처리 완료 후 기록→성공 또는 실패';

COMMENT ON COLUMN api_call_log.http_status_code IS '응답 상태코드 - 응답 코드, 응답 전 오류 시 NULL (가정)';

COMMENT ON COLUMN api_call_log.error_code IS '오류 코드 - 실패 시 오류 코드 (가정)';

COMMENT ON COLUMN api_call_log.error_message IS '오류 내용 - 실패 사유. 시스템 내부정보 미포함 (확인 필요)';

COMMENT ON COLUMN api_call_log.response_ms IS '응답 시간(ms) - 성능 모니터링용, 처리 후 산출 (가정)';

COMMENT ON COLUMN api_call_log.created_at IS '생성 일시';

COMMENT ON COLUMN api_call_log.updated_at IS '수정 일시';

CREATE TABLE help_content (
    help_content_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    menu_id BIGINT NOT NULL,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    manual_version VARCHAR(50),
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_help_content PRIMARY KEY (help_content_id),
    CONSTRAINT ck_help_content_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT uq_help_content_menu_id_title UNIQUE (menu_id, title)
);

COMMENT ON TABLE help_content IS '도움말 - 한 행=메뉴·기능별 도움말 1건. 사용자 매뉴얼과 일치.';

COMMENT ON COLUMN help_content.help_content_id IS '도움말 ID - 대리키';

COMMENT ON COLUMN help_content.menu_id IS '메뉴 - 도움말 대상 메뉴·기능';

COMMENT ON COLUMN help_content.title IS '제목 - (가정) 길이';

COMMENT ON COLUMN help_content.content IS '도움말 내용 - 사용자 매뉴얼과 일치하도록 관리';

COMMENT ON COLUMN help_content.manual_version IS '매뉴얼 버전 - 사용자 매뉴얼 일치 확인용 (가정)';

COMMENT ON COLUMN help_content.use_yn IS '사용 여부 - 공통 사용 여부 도메인. 초기값: 등록→사용 (가정)';

COMMENT ON COLUMN help_content.created_at IS '생성 일시';

COMMENT ON COLUMN help_content.updated_at IS '수정 일시';

CREATE TABLE error_message (
    error_message_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    error_code VARCHAR(50) NOT NULL,
    message VARCHAR(500) NOT NULL,
    cause_description VARCHAR(1000) NOT NULL,
    action_guide VARCHAR(1000) NOT NULL,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_error_message PRIMARY KEY (error_message_id),
    CONSTRAINT uq_error_message_error_code UNIQUE (error_code),
    CONSTRAINT ck_error_message_use_yn CHECK (use_yn IN ('사용', '미사용'))
);

COMMENT ON TABLE error_message IS '에러 메시지 - 한 행=에러 메시지 정의 1건(코드, 원인·조치 안내). 내부정보 미노출.';

COMMENT ON COLUMN error_message.error_message_id IS '에러 메시지 ID - 대리키';

COMMENT ON COLUMN error_message.error_code IS '에러 코드 - 에러 메시지 식별 코드 (가정)';

COMMENT ON COLUMN error_message.message IS '에러 메시지 - 사용자 표시 문구. 내부정보 미노출';

COMMENT ON COLUMN error_message.cause_description IS '원인 안내 - 오류 원인 안내 (가정 길이)';

COMMENT ON COLUMN error_message.action_guide IS '조치 안내 - 사용자가 취할 조치 안내 (가정 길이)';

COMMENT ON COLUMN error_message.use_yn IS '사용 여부 - 초기값: 등록→사용 (가정)';

COMMENT ON COLUMN error_message.created_at IS '생성 일시';

COMMENT ON COLUMN error_message.updated_at IS '수정 일시';

CREATE TABLE portal_widget_setting (
    portal_widget_setting_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    widget_type VARCHAR(30) NOT NULL,
    visible_yn BOOLEAN NOT NULL,
    display_order INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_portal_widget_setting PRIMARY KEY (portal_widget_setting_id),
    CONSTRAINT ck_portal_widget_setting_widget_type CHECK (widget_type IN ('결재양식', '결재함', '일정캘린더', '통합알림', '퀵링크', '나의정보')),
    CONSTRAINT uq_portal_widget_setting_employee_id_widget_type UNIQUE (employee_id, widget_type),
    CONSTRAINT ck_portal_widget_setting_display_order_ge_1 CHECK (display_order >= 1)
);

COMMENT ON TABLE portal_widget_setting IS '포털 위젯 설정 - 한 행=임직원별 위젯 표시 여부·순서 1건. 미설정 시 기본 구성(가정).';

COMMENT ON COLUMN portal_widget_setting.portal_widget_setting_id IS '포털 위젯 설정 ID - 대리키';

COMMENT ON COLUMN portal_widget_setting.employee_id IS '임직원';

COMMENT ON COLUMN portal_widget_setting.widget_type IS '위젯 종류 - 명세의 필수 표시 위젯 6종';

COMMENT ON COLUMN portal_widget_setting.visible_yn IS '표시 여부 - 저장 시 입력 공급 (가정)';

COMMENT ON COLUMN portal_widget_setting.display_order IS '배치 순서 - 저장 시 입력 공급 (가정)';

COMMENT ON COLUMN portal_widget_setting.created_at IS '생성 일시';

COMMENT ON COLUMN portal_widget_setting.updated_at IS '수정 일시';

CREATE TABLE portal_banner (
    portal_banner_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    title VARCHAR(200) NOT NULL,
    image_url VARCHAR(500),
    link_url VARCHAR(500),
    display_order INTEGER NOT NULL,
    start_date DATE,
    end_date DATE,
    use_yn VARCHAR(10) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_portal_banner PRIMARY KEY (portal_banner_id),
    CONSTRAINT ck_portal_banner_use_yn CHECK (use_yn IN ('사용', '미사용')),
    CONSTRAINT ck_portal_banner_end_date_ge_start_date CHECK (end_date >= start_date)
);

COMMENT ON TABLE portal_banner IS '포털 배너 - 한 행=배너 1개.';

COMMENT ON COLUMN portal_banner.portal_banner_id IS '포털 배너 ID - 대리키';

COMMENT ON COLUMN portal_banner.title IS '배너 제목 - (가정) 길이';

COMMENT ON COLUMN portal_banner.image_url IS '이미지 경로 - (확인 필요) 파일은 ECM 저장소 사용 여부';

COMMENT ON COLUMN portal_banner.link_url IS '링크 URL - (가정)';

COMMENT ON COLUMN portal_banner.display_order IS '표시 순서 - (가정)';

COMMENT ON COLUMN portal_banner.start_date IS '게시 시작일 - (가정)';

COMMENT ON COLUMN portal_banner.end_date IS '게시 종료일 - (가정)';

COMMENT ON COLUMN portal_banner.use_yn IS '사용 여부 - 초기값: 등록→사용 (가정)';

COMMENT ON COLUMN portal_banner.created_at IS '생성 일시';

COMMENT ON COLUMN portal_banner.updated_at IS '수정 일시';

CREATE TABLE quick_link (
