COMMENT ON COLUMN quick_link.employee_id IS '임직원 - 퀵링크를 소유한 임직원. 개인화 설정은 임직원별로 저장됨';

COMMENT ON COLUMN quick_link.title IS '퀵링크 제목 - (가정) 길이 100';

COMMENT ON COLUMN quick_link.link_url IS '연결 주소 - (가정) 메뉴 경로 또는 URL, 길이 2000';

COMMENT ON COLUMN quick_link.sort_order IS '표시 순서 - (가정) 미지정 시 등록순 표시';

COMMENT ON COLUMN quick_link.created_at IS '생성 일시';

COMMENT ON COLUMN quick_link.updated_at IS '수정 일시';

CREATE TABLE personal_menu (
    personal_menu_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    menu_id BIGINT NOT NULL,
    sort_order INTEGER NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_personal_menu PRIMARY KEY (personal_menu_id),
    CONSTRAINT uq_personal_menu_employee_id_menu_id UNIQUE (employee_id, menu_id),
    CONSTRAINT ck_personal_menu_sort_order_ge_0 CHECK (sort_order >= 0)
);

COMMENT ON TABLE personal_menu IS '개인 메뉴 구성 - 한 행=임직원·메뉴·순서. 사용 권한 있는 메뉴만.';

COMMENT ON COLUMN personal_menu.personal_menu_id IS '개인 메뉴 구성 ID - 대리키';

COMMENT ON COLUMN personal_menu.employee_id IS '임직원';

COMMENT ON COLUMN personal_menu.menu_id IS '메뉴 - 임직원이 사용 권한을 가진 메뉴만 추가 가능 (확인 필요) 여러 테이블에 걸친 규칙이라 스키마로 표현 불가, 애플리케이션에서 검증';

COMMENT ON COLUMN personal_menu.sort_order IS '메뉴 구성 순서 - (가정) 추가 시 순서 공급';

COMMENT ON COLUMN personal_menu.created_at IS '생성 일시';

COMMENT ON COLUMN personal_menu.updated_at IS '수정 일시';

CREATE TABLE employee_department (
    employee_department_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    employee_id BIGINT NOT NULL,
    department_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_employee_department PRIMARY KEY (employee_department_id),
    CONSTRAINT uq_employee_department_employee_id_department_id UNIQUE (employee_id, department_id)
);

COMMENT ON TABLE employee_department IS '겸직 부서 - 한 행=임직원·겸직 부서 1건(주부서는 employee).';

COMMENT ON COLUMN employee_department.employee_department_id IS '겸직 부서 ID - 대리키';

COMMENT ON COLUMN employee_department.employee_id IS '임직원';

COMMENT ON COLUMN employee_department.department_id IS '겸직 부서 - 주부서는 employee에서 관리하므로 겸직 부서만 저장';

COMMENT ON COLUMN employee_department.created_at IS '생성 일시';

COMMENT ON COLUMN employee_department.updated_at IS '수정 일시';

CREATE TABLE mail_message (
    mail_message_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sender_id BIGINT NOT NULL,
    subject VARCHAR(500) NOT NULL,
    body TEXT,
    sent_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_mail_message PRIMARY KEY (mail_message_id)
);

COMMENT ON TABLE mail_message IS '메일 - 한 행=메일 1건. 발신자 필수, 제목·본문.';

COMMENT ON COLUMN mail_message.mail_message_id IS '메일 ID - 대리키';

COMMENT ON COLUMN mail_message.sender_id IS '발신자 - 발신자 필수';

COMMENT ON COLUMN mail_message.subject IS '제목 - (가정) 길이 500, 필수';

COMMENT ON COLUMN mail_message.body IS '본문 - (가정) 본문 비어 있을 수 있음';

COMMENT ON COLUMN mail_message.sent_at IS '발송 시각 - (가정) 발송 처리 후 채워짐';

COMMENT ON COLUMN mail_message.created_at IS '생성 일시';

COMMENT ON COLUMN mail_message.updated_at IS '수정 일시';

CREATE TABLE mail_recipient (
    mail_recipient_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    mail_message_id BIGINT NOT NULL,
    recipient_id BIGINT NOT NULL,
    read_status VARCHAR(10) NOT NULL,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_mail_recipient PRIMARY KEY (mail_recipient_id),
    CONSTRAINT ck_mail_recipient_read_status CHECK (read_status IN ('안읽음', '읽음')),
    CONSTRAINT uq_mail_recipient_mail_message_id_recipient_id UNIQUE (mail_message_id, recipient_id),
    CONSTRAINT ck_mail_recipient_read_at_req CHECK (read_status NOT IN ('읽음') OR read_at IS NOT NULL)
);

COMMENT ON TABLE mail_recipient IS '메일 수신자 - 한 행=메일·수신자 1건. 읽음 상태.';

COMMENT ON COLUMN mail_recipient.mail_recipient_id IS '메일 수신자 ID - 대리키';

COMMENT ON COLUMN mail_recipient.mail_message_id IS '메일';

COMMENT ON COLUMN mail_recipient.recipient_id IS '수신자';

COMMENT ON COLUMN mail_recipient.read_status IS '읽음 상태 - 공통 읽음 상태 도메인. 초기값(가정): 수신 시 안읽음';

COMMENT ON COLUMN mail_recipient.read_at IS '읽은 시각 - 읽음 처리 시 채워짐';

COMMENT ON COLUMN mail_recipient.created_at IS '생성 일시';

COMMENT ON COLUMN mail_recipient.updated_at IS '수정 일시';

CREATE TABLE credit_card_permission (
    credit_card_permission_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    credit_card_id BIGINT NOT NULL,
    employee_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_credit_card_permission PRIMARY KEY (credit_card_permission_id),
    CONSTRAINT uq_credit_card_permission_credit_card_id_employee_id UNIQUE (credit_card_id, employee_id)
);

COMMENT ON TABLE credit_card_permission IS '신용카드 조회 권한 - 한 행=(신용카드, 임직원) 조회 권한 1건. 카드 N:1 필수, 임직원 N:1 필수. 조합(credit_card_id, employee_id) 유일. 권한 대상은 임직원으로 한정(가정).';

COMMENT ON COLUMN credit_card_permission.credit_card_permission_id IS '신용카드 조회 권한 ID - 대리키';

COMMENT ON COLUMN credit_card_permission.credit_card_id IS '신용카드';

COMMENT ON COLUMN credit_card_permission.employee_id IS '임직원';

COMMENT ON COLUMN credit_card_permission.created_at IS '생성 일시';

COMMENT ON COLUMN credit_card_permission.updated_at IS '수정 일시';

CREATE TABLE project_permission (
    project_permission_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id BIGINT NOT NULL,
    employee_id BIGINT,
    department_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_project_permission PRIMARY KEY (project_permission_id),
    CONSTRAINT uq_project_permission_project_id_employee_id UNIQUE (project_id, employee_id),
    CONSTRAINT uq_project_permission_project_id_department_id UNIQUE (project_id, department_id),
    CONSTRAINT ck_project_permission_one_employee_id_department_id CHECK ((CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

COMMENT ON TABLE project_permission IS '프로젝트 사용 권한 - 한 행=(프로젝트, 임직원 또는 부서) 사용 권한 1건. 프로젝트 N:1 필수. 대상은 임직원 또는 부서 중 하나만 지정(가정). 프로젝트·대상 조합 유일.';

COMMENT ON COLUMN project_permission.project_permission_id IS '프로젝트 사용 권한 ID - 대리키';

COMMENT ON COLUMN project_permission.project_id IS '프로젝트';

COMMENT ON COLUMN project_permission.employee_id IS '임직원 - 임직원 대상일 때 지정';

COMMENT ON COLUMN project_permission.department_id IS '부서 - 부서 대상일 때 지정';

COMMENT ON COLUMN project_permission.created_at IS '생성 일시';

COMMENT ON COLUMN project_permission.updated_at IS '수정 일시';

CREATE TABLE sub_project_permission (
    sub_project_permission_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sub_project_id BIGINT NOT NULL,
    employee_id BIGINT,
    department_id BIGINT,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_sub_project_permission PRIMARY KEY (sub_project_permission_id),
    CONSTRAINT uq_sub_project_permission_sub_project_id_employee_id UNIQUE (sub_project_id, employee_id),
    CONSTRAINT uq_sub_project_permission_sub_project_id_department_id UNIQUE (sub_project_id, department_id),
    CONSTRAINT ck_sub_project_permission_one_employee_id_department_id CHECK ((CASE WHEN employee_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

COMMENT ON TABLE sub_project_permission IS '하위사업 사용 권한 - 한 행=(하위사업, 임직원 또는 부서) 사용 권한 1건. 하위사업 N:1 필수. 대상은 임직원 또는 부서 중 하나만 지정(가정). 하위사업·대상 조합 유일.';

COMMENT ON COLUMN sub_project_permission.sub_project_permission_id IS '하위사업 사용 권한 ID - 대리키';

COMMENT ON COLUMN sub_project_permission.sub_project_id IS '하위사업';

COMMENT ON COLUMN sub_project_permission.employee_id IS '임직원 - 임직원 대상일 때 지정';

COMMENT ON COLUMN sub_project_permission.department_id IS '부서 - 부서 대상일 때 지정';

COMMENT ON COLUMN sub_project_permission.created_at IS '생성 일시';

COMMENT ON COLUMN sub_project_permission.updated_at IS '수정 일시';

CREATE TABLE account_transfer_resolution (
    account_transfer_resolution_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    expense_resolution_id BIGINT NOT NULL,
    partner_account_id BIGINT NOT NULL,
    transfer_reason TEXT NOT NULL,
    processor_id BIGINT NOT NULL,
    processed_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_account_transfer_resolution PRIMARY KEY (account_transfer_resolution_id)
);

COMMENT ON TABLE account_transfer_resolution IS '계좌 대체결의 - 한 행=원 결의서의 은행계좌 대체 1건. 원 결의서 N:1 필수, 대체 거래처 계좌 N:1 필수, 대체 사유 필수, 처리자(임직원) 필수·처리일시. 대체결의서는 expense_resolution으로 별도 선택 연결(가정).';

COMMENT ON COLUMN account_transfer_resolution.account_transfer_resolution_id IS '계좌 대체결의 ID - 대리키';

COMMENT ON COLUMN account_transfer_resolution.expense_resolution_id IS '원 결의서';

COMMENT ON COLUMN account_transfer_resolution.partner_account_id IS '대체 거래처 계좌';

COMMENT ON COLUMN account_transfer_resolution.transfer_reason IS '대체 사유 - 결정: 대체 사유 필수';

COMMENT ON COLUMN account_transfer_resolution.processor_id IS '처리자 - 처리자 필수. 대체결의서(expense_resolution) 별도 선택 연결은 카탈로그 parents에 없어 컬럼 미추가 (카탈로그 수정 필요)';

COMMENT ON COLUMN account_transfer_resolution.processed_at IS '처리일시 - (가정) 대체 처리 시점에 함께 공급. 마감 기간 건 대체 금지는 (확인 필요) 다른 엔티티 규칙';

COMMENT ON COLUMN account_transfer_resolution.created_at IS '생성 일시';

COMMENT ON COLUMN account_transfer_resolution.updated_at IS '수정 일시';

CREATE TABLE rfid_scan_log (
    rfid_scan_log_id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    asset_id BIGINT,
    tag_value VARCHAR(100) NOT NULL,
    scanned_at TIMESTAMPTZ NOT NULL,
    match_status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_rfid_scan_log PRIMARY KEY (rfid_scan_log_id),
    CONSTRAINT ck_rfid_scan_log_match_status CHECK (match_status IN ('MATCHED', 'UNMATCHED'))
);

COMMENT ON TABLE rfid_scan_log IS 'RFID 스캔 이력 - 한 행=RFID 태그 스캔 1건. 태그 식별값, 스캔일시, 매칭 여부 속성. 자산은 선택 참조(미매칭이면 NULL). 미매칭 태그 목록은 매칭 여부로 조회.';

COMMENT ON COLUMN rfid_scan_log.rfid_scan_log_id IS 'RFID 스캔 이력 ID - 대리키';

COMMENT ON COLUMN rfid_scan_log.asset_id IS '자산 ID - 매칭된 자산. 미매칭이면 NULL. 스캔 저장 시 매칭 결과에 따라 공급';

COMMENT ON COLUMN rfid_scan_log.tag_value IS 'RFID 태그 식별값 - 리더기가 읽은 태그 식별값. 길이는 (가정) 100, 선행 0 보존을 위해 문자열로 저장';

COMMENT ON COLUMN rfid_scan_log.scanned_at IS '스캔 일시 - 리더기 연계로 전달되는 스캔 시각. 시간대 정책은 (확인 필요)';

COMMENT ON COLUMN rfid_scan_log.match_status IS '매칭 여부 - (가정) 스캔 저장 시 등록 자산과 매칭하여 결정. 매칭 성공이면 MATCHED, 등록 자산이 없으면 UNMATCHED. 미매칭 목록은 UNMATCHED로 조회. 초기값: 자산 매칭 성공→MATCHED, 실패→UNMATCHED';

COMMENT ON COLUMN rfid_scan_log.created_at IS '생성 일시';

COMMENT ON COLUMN rfid_scan_log.updated_at IS '수정 일시';

